  function 判断角色允许删除(角色键 = '', 角色数据 = {}, snapshot = {}) {
    const safe角色键 = toText(角色键, '').trim();
    if (!safe角色键) return false;
    const 显示名 = toText(角色数据 && (角色数据.name || deepGet(角色数据, 'base.name', '')), safe角色键);
    const 玩家名 = toText(deepGet(snapshot, 'rootData.sys.玩家名', ''), '').trim();
    const 当前角色键 = resolveSnapshotCharKey(snapshot, toText(snapshot && snapshot.activeName, ''));
    const 当前显示名 = toText(snapshot && snapshot.activeName, '').trim();
    const 待判定 = [safe角色键, 显示名];
    if (角色删除保护名单.has(safe角色键) || 角色删除保护名单.has(显示名)) return false;
    return !待判定.some(名称 => 名称 && [玩家名, 当前角色键, 当前显示名].includes(名称));
  }

  function 清理被删角色引用(数据根 = {}, 角色键 = '', 角色显示名 = '') {
    const 名称集合 = new Set([角色键, 角色显示名].map(名称 => toText(名称, '').trim()).filter(Boolean));
    safeEntries(数据根.char || {}).forEach(([, 角色数据]) => {
      if (!角色数据 || typeof 角色数据 !== 'object') return;
      const 关系 = deepGet(角色数据, '社交.关系', null);
      if (关系 && typeof 关系 === 'object' && !Array.isArray(关系)) {
        名称集合.forEach(名称 => {
          delete 关系[名称];
        });
      }
    });
    const 索引角色 = deepGet(数据根, '相关实体索引.角色', null);
    if (Array.isArray(索引角色)) {
      deepSetMutable(数据根, ['相关实体索引', '角色'], 索引角色.filter(名称 => !名称集合.has(toText(名称, '').trim())));
    }
  }

  async function 确保交互模块已加载(moduleName, mountName) {
    if (typeof window[mountName] === 'function') return true;
    const chatId = getCurrentUiRequestChatId();
    try {
      const result = await window.__LWCS_确保模块已加载__?.(moduleName, { 来源: 'interaction', 允许失败降级: false, 抛错: true });
      return chatId === getCurrentUiRequestChatId() && result?.ok === true && typeof window[mountName] === 'function';
    } catch (error) {
      console.warn(`[LWCS] ${moduleName}按需加载失败`, error);
      return false;
    }
  }


  function cloneJsonValue(value, fallback = {}) {
    try {
      return structuredClone(value);
    } catch (error) {}
    try {
      return JSON.parse(JSON.stringify(value));
    } catch (error) {}
    return fallback;
  }

