    const 新状态 = { ...当前, [类型]: !!阻断 };
    globalThis.__LWCS_LIBRARY_ARCHIVE_BLOCKS__ = 新状态;
    try { if (globalThis.parent && globalThis.parent !== globalThis) globalThis.parent.__LWCS_LIBRARY_ARCHIVE_BLOCKS__ = 新状态; } catch (错误) {}
