    if (当前chatKey && 物品归档状态_桥接.chatKey && 当前chatKey === 物品归档状态_桥接.chatKey && 当前存储键 === 物品归档状态_桥接.存储键 && 当前楼层 === 物品归档状态_桥接.楼层) return;
