    try { if (globalThis.parent && globalThis.parent !== globalThis) 候选窗口.push(globalThis.parent); } catch (错误) {}
    try { if (globalThis.top && globalThis.top !== globalThis) 候选窗口.push(globalThis.top); } catch (错误) {}
