    if (['自身', '目标', '自身与目标'].includes(显式对象)) return 显式对象;
    if (位移类型 === '换位') return '自身与目标';
    if (['瞬移', '脱离'].includes(位移类型)) return '自身';
    if (['自身', '友方', '召唤物'].includes(目标)) return '自身';
    if (位移类型 === '拉近') return '自身';
    return '目标';
