    字段['距离'] = Math.max(1, Math.min(30, toNumber(字段['距离'], 1)));
    字段['持续回合'] = Math.max(1, Math.min(10, parseSkillDesignerIntegerInputValue(字段['持续回合'], 1, 1)));
