      const 数值文本 = normalizeSkillUiText(字段['数值'], '');
      if (技能设计台字段值是百分比修正(数值文本)) 字段['数值'] = formatSkillDesignerSignedValue(解析技能设计台正负数值(数值文本), true);
      else delete 字段['数值'];
