    字段['目标'] = '自身';
    字段['数量'] = Math.max(1, parseSkillDesignerIntegerInputValue(字段['数量'], 1, 1));
    const 默认行动模式 = ['魂师', '魂兽', '本命召唤兽', '深渊生物'].includes(字段['召唤单位类型']) ? '自主行动' : '协同攻击';
    if (!['自主行动', '护卫', '协同攻击'].includes(normalizeSkillUiText(字段['行动模式'], '')))
      字段['行动模式'] = 默认行动模式;
