  function 读取技能设计台原型字段输入值(raw = '') {
    const text = toText(raw, '').trim();
    if (!text) return '';
    if (/^[\[{]/.test(text)) {
      try {
        return JSON.parse(text);
      } catch (error) {
        return text;
      }
    }
    return text;
  }






  function 读取技能设计台多枚举值(value = '') {
    return (Array.isArray(value) ? value : String(value || '').split(/[、,，|/]/))
      .map(item => normalizeSkillUiText(item, ''))
      .filter(Boolean);
  }

  const 技能设计台时窗最大调整tick = 7 * 24 * 6;








  function 规范化技能设计台原型生效方式列表(效果列表 = [], context = {}) {
    const 列表 = Array.isArray(效果列表) ? 效果列表 : [];
    const 主目标 = normalizeSkillDesignerEffectTargetValue(列表[0] && 列表[0]['目标'], '');
    const 主原型 = normalizeSkillUiText(列表[0] && 列表[0]['原型'], '');
    const 嵌套字段 = normalizeSkillUiText(context && context.嵌套字段, '');
    const 强制独立 = !!(context && (context.强制独立 || context.条件分支 || 嵌套字段));
    const 可跟随主原型 = 效果条目 => {
      const 原型 = normalizeSkillUiText(效果条目 && 效果条目['原型'], '');
      if (!主原型 || !原型 || 原型 === 主原型) return false;
      return ['状态施加', '状态移除', '判定修正', '结算修正', '决策干扰'].includes(
        原型,
      );
    };
    return 列表.map((效果条目, 序号) => {
      if (!效果条目 || typeof 效果条目 !== 'object') return 效果条目;
        const 下一条 = 技能设计台清理并水合原型效果(效果条目, 主目标 || '单体', { 嵌套字段, 强制独立, 允许对应等级: context && context.允许对应等级 });
      const 当前目标 = normalizeSkillDesignerEffectTargetValue(下一条['目标'], 主目标 || '单体');
      const 当前生效方式 = normalizeSkillUiText(效果条目['生效方式'], '独立生效');
      下一条['生效方式'] =
        强制独立 || 序号 === 0 || (主目标 && 当前目标 !== 主目标) || !可跟随主原型(下一条) ? '独立生效' : 当前生效方式;
      return 下一条;
    });
  }



  function 读取技能设计台原型效果状态(
    mountEl,
    fallbackTarget = '单体',
    gridName = '',
    允许空列表 = false,
    context = {},
  ) {
    const target = normalizeSkillDesignerEffectTargetValue(fallbackTarget, '单体');
    const grid = gridName
      ? mountEl
        ? mountEl.querySelector(`[data-skill-designer-prototype-grid=\"${gridName}\"]`)
        : null
      : mountEl && mountEl.matches && mountEl.matches('[data-skill-designer-prototype-grid]')
        ? mountEl
        : mountEl?.querySelector?.('[data-skill-designer-prototype-grid]');
    const rows = Array.from(grid ? grid.children : []).filter(
      node => node instanceof HTMLElement && node.matches('[data-skill-designer-prototype-row]'),
    );
    if (!rows.length && (gridName === 'side' || 允许空列表)) return [];
    const effects = rows
      .map(row => {
        const select = row.querySelector('[data-skill-designer-prototype-select]');
        const prototype = normalizeSkillUiText(select && select.value, '');
        if (!prototype || !SKILL_DESIGNER_PROTOTYPE_REGISTRY[prototype]) return null;
        const effect = { 原型: prototype, 目标: target };
        const 字段容器 = row.querySelector(':scope > [data-skill-designer-prototype-fields]');
        (字段容器 || row).querySelectorAll('[data-skill-designer-prototype-field]').forEach(input => {
          if (input.closest('[data-skill-designer-prototype-row]') !== row) return;
          const key = normalizeSkillUiText(input.getAttribute('data-skill-designer-prototype-field'), '');
          if (!key) return;
          if (input instanceof HTMLInputElement && input.type === 'checkbox') {
            if (input.checked) effect[key] = true;
            return;
          }
          const value =
            input instanceof HTMLSelectElement && input.multiple
              ? Array.from(input.selectedOptions)
                  .map(option => normalizeSkillUiText(option.value, ''))
                  .filter(Boolean)
              : input.hasAttribute('data-skill-designer-prototype-json')
                ? (() => {
                    try {
                      const parsed = JSON.parse(input.value || '{}');
                      return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
                    } catch (_) {
                      return {};
                    }
                  })()
              : input.hasAttribute('data-skill-designer-prototype-multiple')
                ? 读取技能设计台多枚举值(input.value)
                : 读取技能设计台原型字段输入值(input.value);
          if (value === '无') return;
          if (value !== '' && !(value && typeof value === 'object' && !Array.isArray(value) && !Object.keys(value).length))
            effect[key] =
              key === '防御穿透' ? Math.max(0, Math.min(100, parseSkillDesignerIntegerInputValue(value, 0, 0))) : value;
        });
        if (prototype === '状态施加' && normalizeSkillUiText(effect['状态'], '') === '无视异常' && !effect['触发限制']) {
          effect['触发限制'] = { 周期: '每日', 次数: 3 };
        }
        (字段容器 || row).querySelectorAll('[data-skill-designer-condition-branch]').forEach(block => {
          if (block.closest('[data-skill-designer-prototype-row]') !== row) return;
          const enabledInput = block.querySelector(':scope [data-skill-designer-condition-branch-enabled]');
          const enabled =
            enabledInput instanceof HTMLInputElement && enabledInput.type === 'checkbox'
              ? enabledInput.checked
              : normalizeSkillUiText(enabledInput?.value, '无') === '启用';
          if (!enabled) return;
          const branches = Array.from(block.querySelectorAll(':scope [data-skill-designer-condition-branch-row]'))
            .map(branchRow => {
              if (branchRow.closest('[data-skill-designer-prototype-row]') !== row) return null;
              const action = normalizeSkillUiText(
                branchRow.querySelector('[data-skill-designer-condition-branch-action]')?.value,
                '替换效果',
              );
              const conditions = Array.from(branchRow.querySelectorAll(':scope [data-skill-designer-condition-row]'))
                .map(conditionRow => {
                  const readCondition = key => {
                    const input = Array.from(
                      conditionRow.querySelectorAll(`[data-skill-designer-condition-field="${key}"]`),
                    // 保存时 setBusy 会禁用全部可禁用控件，只跳过有意禁用的隐藏输入，否则保存会丢掉全部条件分支
                    ).find(node => !node.disabled || node.hasAttribute('data-skill-designer-disableable'));
                    return input ? 读取技能设计台原型字段输入值(input.value) : '';
                  };
                  const 类型 = normalizeSkillUiText(readCondition('类型'), '');
                  const 比较 = 规范化技能设计台条件分支比较值(类型, readCondition('比较'));
                  const condition = {
                    类型: 类型,
                    对象: normalizeSkillUiText(readCondition('对象'), '目标'),
                    比较: 比较,
                  };
                  const 显示配置 = 读取技能设计台条件分支值控件配置(类型, 比较);
                  if (显示配置.显示值) {
                    const value = readCondition('值');
                    if (value !== '') condition['值'] = value;
                  }
                  if (显示配置.显示状态) {
                    const state = normalizeSkillUiText(readCondition('状态'), '');
                    if (state) condition['状态'] = state;
                  }
                  return condition['类型'] ? condition : null;
                })
                .filter(Boolean);
              if (!conditions.length) return null;
              const branch = { 条件: conditions, 处理: action };
              if (action === '替换效果' || action === '追加效果') {
                const effectKey = action === '替换效果' ? '替换效果' : '追加效果';
                const effectBlock = branchRow.querySelector(`[data-skill-designer-condition-effect="${effectKey}"]`);
                const nestedGrid = effectBlock
                  ? effectBlock.querySelector('[data-skill-designer-prototype-grid]')
                  : null;
                const nestedEffects = 读取技能设计台原型效果状态(nestedGrid, target, '', true, {
                  条件分支: true,
                  强制独立: true,
                  允许对应等级: context && context.允许对应等级,
                });
                if (nestedEffects.length) branch[effectKey] = nestedEffects;
              }
              return branch;
            })
            .filter(Boolean);
          if (branches.length) effect['条件分支'] = branches;
        });
        (字段容器 || row).querySelectorAll('[data-skill-designer-nested-prototype-field]').forEach(block => {
          if (block.closest('[data-skill-designer-prototype-row]') !== row) return;
          const key = normalizeSkillUiText(block.getAttribute('data-skill-designer-nested-prototype-field'), '');
          if (!key) return;
          const nestedGrid = block.querySelector('[data-skill-designer-prototype-grid]');
          const nestedEffects = 读取技能设计台原型效果状态(nestedGrid, target, '', true, {
            嵌套字段: key,
            强制独立: true,
            允许对应等级: context && context.允许对应等级,
          });
          if (nestedEffects.length) effect[key] = nestedEffects;
        });
        return effect;
      })
      .filter(Boolean);
    const 规范续效果列表 = 规范化技能设计台原型生效方式列表(effects, context);
    const 归一效果列表 =
      允许空列表 && !规范续效果列表.length ? [] : 规范化技能设计台原型效果列表(规范续效果列表, target, context);
    清理技能设计台等价替换条件分支(归一效果列表);
    return 归一效果列表;
  }






  function buildSkillDesignerRuntimeObject(source = {}) {
    const result = {};
    safeEntries(source && typeof source === 'object' ? source : {}).forEach(([key, value]) => {
      if (value === undefined || value === null) return;
      if (typeof value === 'string' && !value.trim()) return;
      if (Array.isArray(value) && !value.length) return;
      if (value && typeof value === 'object' && !Array.isArray(value) && !safeEntries(value).length) return;
      result[key] = value;
    });
      if (!normalizeSkillUiText(result['原型'], '') && normalizeSkillUiText(result['机制'], '')) {
        const 原型列表 = getSkillDesignerMechanismCompiledPrototypeList(result['机制']);
        if (原型列表.length) {
          const 原型条目 = 原型列表[0];
          const 原型 = typeof 原型条目 === 'string' ? 原型条目 : normalizeSkillUiText(原型条目 && 原型条目['原型'], '');
          if (原型) {
            const 转换结果 = { ...result, ...(typeof 原型条目 === 'object' && 原型条目 ? 原型条目 : {}), 原型: 原型 };
            delete 转换结果['机制'];
            return 转换结果;
          }
        }
      }
    delete result['机制'];
    return result;
  }

  function parseSkillDesignerNumericInputValue(value, fallback = 0, digits = 4) {
    const rawText = toText(value, '').trim();
    if (!rawText) return Number(Number(fallback || 0).toFixed(digits));
    const match = rawText.match(/-?\d+(?:\.\d+)?/);
    const parsed = Number(match ? match[0] : rawText);
    if (!Number.isFinite(parsed)) return Number(Number(fallback || 0).toFixed(digits));
    return Number(parsed.toFixed(digits));
  }

  function parseSkillDesignerIntegerInputValue(value, fallback = 0, minimum = 0) {
    const parsed = Math.round(parseSkillDesignerNumericInputValue(value, fallback, 0));
    if (!Number.isFinite(parsed)) return Math.max(minimum, Math.round(Number(fallback || 0)));
    return Math.max(minimum, parsed);
  }

  function parseSkillDesignerPercentRatio(value, fallback = 0) {
    const rawText = toText(value, '').trim();
    if (!rawText) return Number(Number(fallback || 0).toFixed(4));
    const parsed = parseSkillDesignerNumericInputValue(rawText, fallback, 4);
    if (!Number.isFinite(parsed)) return Number(Number(fallback || 0).toFixed(4));
    if (/%/.test(rawText) || parsed > 1) return Number((parsed / 100).toFixed(4));
    return Number(parsed.toFixed(4));
  }


  function 规范化技能设计台伤害威力倍率(value, fallback = 100) {
    const parsed = Number(value);
    if (!Number.isFinite(parsed) || parsed <= 0) return Math.max(1, Number(fallback || 100));
    return Math.max(1, Math.round(parsed));
  }



  function normalizeSkillDesignerTargetForRuntime(target = '') {
    return normalizeSkillDesignerEffectTargetValue(target, '单体');
  }


  function isSkillDesignerGrantableMechanism(label = '') {
    const normalizedLabel = normalizeSkillUiText(label, '');
    return Array.isArray(SKILL_DESIGNER_TARGET_SEMANTICS.可赋予)
      ? SKILL_DESIGNER_TARGET_SEMANTICS.可赋予.includes(normalizedLabel)
      : false;
  }


  function getSkillDesignerMechanismRegistryMeta(label = '') {
    const normalizedLabel = normalizeSkillUiText(label, '');
    if (!normalizedLabel) return null;
    const meta = SKILL_DESIGNER_MECHANISM_META[normalizedLabel];
    return meta && typeof meta === 'object' ? meta : null;
  }

  function buildSkillDesignerPrimaryHintFromRegistry(label = '') {
    const meta = getSkillDesignerMechanismRegistryMeta(label);
    if (!meta) return null;
    const main = normalizeSkillUiText(meta.designerMainHint, '');
    const sub = normalizeSkillUiText(meta.designerSubHint, '');
    const secondary = normalizeSkillUiText(meta.designerSecondaryHint, '');
    if (!main && !sub) return null;
    return {
      main: main || sub,
      sub: sub || main,
      secondary: secondary || undefined,
    };
  }

  function buildSkillDesignerSecondaryHintsFromRegistry(label = '') {
    const meta = getSkillDesignerMechanismRegistryMeta(label);
    if (!meta) return [];
    const hint = normalizeSkillUiText(meta.designerSecondaryHint, '');
    return hint ? [hint] : [];
  }

  function resolveSkillDesignerMechanismParamDefsFromRegistry(label = '') {
    const meta = getSkillDesignerMechanismRegistryMeta(label);
    const schema = Array.isArray(meta && meta.设计台参数定义) ? meta.设计台参数定义 : [];
    if (!schema.length) return [];
    return schema
      .map(def => {
        if (!def || typeof def !== 'object') return null;
        const type = normalizeSkillUiText(def.type, 'text');
        const key = normalizeSkillUiText(def.key, '');
        const title = normalizeSkillUiText(def.label, '');
        if (!key || !title) return null;
        const placeholder = normalizeSkillUiText(def.placeholder, '');
        if (type === 'select') {
          const optionKey = normalizeSkillUiText(def.optionsKey, '');
          const options = optionKey
            ? SKILL_DESIGNER_PARAM_OPTION_REGISTRY[optionKey] || []
            : Array.isArray(def.options)
              ? def.options
              : [];
          return createSkillDesignerSelectParam(key, title, options, placeholder || '未设置');
        }
        if (type === 'number') {
          return createSkillDesignerNumberParam(key, title, placeholder, normalizeSkillUiText(def.step, '0.1'));
        }
        return createSkillDesignerTextParam(key, title, placeholder);
      })
      .filter(Boolean);
  }


  function resolveSkillDesignerGrantableMechanismTargetForRuntime(target = '', mechanismLabel = '') {
    const normalizedTarget = normalizeSkillDesignerTargetForRuntime(target);
    if (mechanismLabel && !isSkillDesignerGrantableMechanism(mechanismLabel)) return normalizedTarget || '自身';
    if (normalizeSkillUiText(mechanismLabel, '') === '能力共享' && normalizedTarget === '自身') return '群体';
    return normalizedTarget || '自身';
  }







  function getSkillDesignerEffectivePrimaryLabel(draft = {}) {
    const primarySub = normalizeSkillUiText(draft && draft.primarySub, '');
    if (primarySub) return primarySub;
    const primaryMain = normalizeSkillUiText(draft && draft.primaryMain, '');
    return primaryMain;
  }





















  function summarizeSkillEffectArray(effectArray, skill = null, cachedDraft = null) {
    const effectNames = (Array.isArray(effectArray) ? effectArray : [])
      .map(effect => {
        const name = toText(effect && effect['原型'], '').trim();
        if (!name && Array.isArray(effect && effect['使用效果'])) return summarizeConstructEffectUi(effect);
        if (!name || isSkillSummaryEffect(effect)) return '';
        if (name === '召唤生成') return summarizeSummonEffectUi(effect);
        if (name === '状态施加') return normalizeSkillUiText(effect && effect['状态'], '状态施加');
        return name;
      })
      .filter(Boolean);
    if (effectNames.length) return effectNames.join(' / ');
    const draft = cachedDraft || (skill ? readSkillDesignerDraft(skill) : null);
    const designSummary = buildSkillDesignerMechanicSummary(draft || {});
    return designSummary || '未知';
  }

  function resolveExpiryUiText(item, fallback = '') {
    const expiryTick = toNumber(item && item['有效期至tick'], 0);
    if (expiryTick > 0) return formatTickToCalendarDateText(expiryTick);
    const explicitText = normalizeSkillUiText(item && item['有效期至'], '');
    if (explicitText) return explicitText;
    return fallback;
  }

  function 读取场外魂技冷却档(skill = {}) {
    const 前摇 = Math.max(0, toNumber(skill && skill['前摇'], 0));
    if (前摇 < 30) return { 标签: '随时', 冷却tick: 0 };
    if (前摇 < 60) return { 标签: '每小时', 冷却tick: 6 };
    if (前摇 < 90) return { 标签: '每日', 冷却tick: 144 };
    return { 标签: '每周', 冷却tick: 1008 };
  }

  function 读取场外魂技冷却状态(skill = {}, 当前tick = 0) {
    const 冷却档 = 读取场外魂技冷却档(skill);
    const 当前 = Math.max(0, toNumber(当前tick, 0));
    const 冷却至tick = Math.max(0, toNumber(skill && skill['场外冷却至tick'], 0));
    const 冷却中 = 冷却至tick > 当前;
    return {
      ...冷却档,
      冷却至tick,
      冷却中,
      冷却文本: 冷却中 ? `冷却至${formatTickToCalendarDateText(冷却至tick)}` : '',
    };
  }

  function 校验场外魂技冷却(skill = {}, 当前tick = 0, 技能名 = '技能') {
    const 冷却状态 = 读取场外魂技冷却状态(skill, 当前tick);
    if (冷却状态.冷却中) throw new Error(`【${技能名}】场外冷却中，${冷却状态.冷却文本}。`);
    return 冷却状态;
  }

  function 写入场外魂技冷却(skill = {}, 当前tick = 0, 冷却倍率 = 1) {
    if (!skill || typeof skill !== 'object' || Array.isArray(skill)) return null;
    const 冷却状态 = 读取场外魂技冷却状态(skill, 当前tick);
    const 倍率 = Math.max(1, toNumber(冷却倍率, 1));
    const 实际冷却tick = 冷却状态.冷却tick > 0 ? Math.max(1, Math.ceil(冷却状态.冷却tick / 倍率)) : 0;
    if (实际冷却tick > 0) skill['场外冷却至tick'] = Math.max(0, toNumber(当前tick, 0)) + 实际冷却tick;
    else delete skill['场外冷却至tick'];
    return { ...读取场外魂技冷却状态(skill, 当前tick), 冷却tick: 实际冷却tick };
  }

  function extractConstructCreateEffects(effectArray = []) {
    return (Array.isArray(effectArray) ? effectArray : []).filter(
      effect =>
        effect &&
        typeof effect === 'object' &&
        !toText(effect['原型'], '').trim() &&
        Array.isArray(effect['使用效果']),
    );
  }

  function buildConstructSkillActionHtml(skillPath = [], skill = {}, 当前tick = 0) {
    if (!Array.isArray(skillPath) || !skillPath.length) return '';
    const 冷却状态 = 读取场外魂技冷却状态(skill, 当前tick);
    const 禁用 = 冷却状态.冷却中;
    const 提示 = 禁用 ? ` title="${escapeHtmlAttr(冷却状态.冷却文本)}"` : '';
    return `
        <div class="tag-cloud armory-quick-actions mvu-detail-toolbar mvu-detail-toolbar--tight">
          <button type="button" class="tag-chip live skill-inline-action-btn" data-skill-action="cast-construct" data-skill-path="${escapeHtmlAttr(JSON.stringify(skillPath))}"${禁用 ? ' disabled aria-disabled="true"' : ''}${提示}>${禁用 ? '冷却中' : '日常施展'}</button>
        </div>
      `;
  }

  function skillHasDailyMvuWritebackEffect(skill = {}) {
    const 可写回原型 = new Set(['资源变化', '属性修正', '状态施加', '状态移除', '修炼增益', '战斗外复活', '灵物吸收', '永久属性提升', '魂骨年限提升', '护盾变化', '机制授予', '复制执行']);
    const visit = effects =>
      (Array.isArray(effects) ? effects : []).some(effect => {
        if (!effect || typeof effect !== 'object') return false;
        if (!toText(effect['原型'], '').trim() && Array.isArray(effect['使用效果'])) return false;
        const 原型 = toText(effect['原型'], '').trim();
        if (可写回原型.has(原型)) return true;
        if (技能设计台嵌套效果数组字段表.some(字段名 => visit(effect[字段名]))) return true;
        return (Array.isArray(effect['条件分支']) ? effect['条件分支'] : []).some(branch =>
          技能设计台条件分支效果数组字段表.some(字段名 => visit(branch && branch[字段名])),
        );
      });
    return visit(skill && skill['_效果数组']);
  }

