  function 读取试炼状态文本(snapshot) {
    return toText(deepGet(snapshot, 'rootData.world.战斗.试炼状态', ''), '').trim();
  }

  function 是否试炼内地点(location = '') {
    return toText(location, '').trim().startsWith(试炼地点前缀);
  }

  function 构建升灵台试炼地点(档位 = '初级', 暴动期 = false) {
    const safeTier = ['初级', '中级', '高级'].includes(toText(档位, '初级')) ? toText(档位, '初级') : '初级';
    return `${试炼地点前缀}${暴动期 ? '暴动期' : ''}${safeTier}升灵台`;
  }

  function 构建魂灵塔试炼地点(层数 = 1) {
    const floor = Math.min(SOUL_TOWER_TOTAL_FLOORS, Math.max(1, Math.floor(toNumber(层数, 1))));
    return `${试炼地点前缀}魂灵塔-第${floor}层`;
  }

  function 解析试炼地点(location = '') {
    const safeLocation = toText(location, '').trim();
    if (!是否试炼内地点(safeLocation)) return null;
    const 塔匹配 = safeLocation.match(/^试炼-魂灵塔-第(\d+)层$/);
    if (塔匹配) {
      const floor = Math.min(SOUL_TOWER_TOTAL_FLOORS, Math.max(1, Math.floor(toNumber(塔匹配[1], 1))));
      return {
        试炼类型: '魂灵塔',
        门票名: '魂灵塔门票',
        档位: '魂灵塔',
        暴动期: false,
        入场地点: 魂灵塔退出地点,
        当前层: floor,
        试炼内地点: 构建魂灵塔试炼地点(floor),
      };
    }
    if (/升灵台/.test(safeLocation)) {
      const body = safeLocation.replace(/^试炼-/, '');
      const 暴动期 = /暴动期/.test(body);
      const 档位 = 解析升灵台档位(body);
      return {
        试炼类型: '升灵台',
        门票名: `${暴动期 ? '暴动期' : ''}${档位}升灵台门票`,
        档位,
        暴动期,
        入场地点: 升灵台退出地点,
        当前层: 0,
        试炼内地点: 构建升灵台试炼地点(档位, 暴动期),
      };
    }
    return null;
  }

  function isSoulTowerCombatType(detail = {}) {
    const battleType = toText(detail && (detail['战斗类型'] || detail.combatType || detail.type), '');
    return battleType === '魂灵塔冲塔';
  }

  function getSoulTowerGateMeta(floor = 0) {
    const safeFloor = Math.max(1, Math.floor(Number(floor) || 1));
    const rule =
      SOUL_TOWER_LAYER_RULES.find(item => safeFloor >= item.gateStart && safeFloor <= item.gateEnd) ||
      SOUL_TOWER_LAYER_RULES[SOUL_TOWER_LAYER_RULES.length - 1];
    const layerInGate = safeFloor - rule.gateStart + 1;
    const gateIndex = SOUL_TOWER_LAYER_RULES.findIndex(item => item.key === rule.key) + 1;
    const isGateBoss = safeFloor === rule.gateEnd;
    const nextGateBossFloor = rule.gateEnd;
    const layerProgress =
      rule.gateEnd > rule.gateStart ? (safeFloor - rule.gateStart) / (rule.gateEnd - rule.gateStart) : 1;
    return {
      floor: safeFloor,
      gateIndex,
      gateStart: rule.gateStart,
      gateEnd: rule.gateEnd,
      layerInGate,
      isGateBoss,
      gateLabel: rule.label,
      gateRangeLabel: `${rule.gateStart}-${rule.gateEnd}层`,
      nextGateBossFloor,
      rewardTier: rule.rewardTier,
      layerProgress,
      minAge: rule.minAge,
      maxAge: rule.maxAge,
      qualitySteps: rule.qualitySteps,
      isTopNine: safeFloor >= 100,
      totalFloors: SOUL_TOWER_TOTAL_FLOORS,
      key: rule.key,
    };
  }



  function getSoulTowerGuardianQualityForFloor(floor = 1) {
    const meta = getSoulTowerGateMeta(floor);
    const steps = Array.isArray(meta.qualitySteps) && meta.qualitySteps.length ? meta.qualitySteps : ['C'];
    if (steps.length === 1) return steps[0];
    const progress = Math.max(0, Math.min(1, Number(meta.layerProgress || 0)));
    const index = Math.min(steps.length - 1, Math.floor(progress * steps.length));
    return steps[index] || steps[steps.length - 1];
  }

  function buildSoulTowerGuardianAgeForFloor(floor = 1, rng = Math.random) {
    const meta = getSoulTowerGateMeta(floor);
    const minAge = Math.max(1, Math.floor(Number(meta.minAge || 1)));
    const maxAge = Math.max(minAge, Math.floor(Number(meta.maxAge || minAge)));
    if (meta.isGateBoss) return maxAge;
    const gateLength = Math.max(1, meta.gateEnd - meta.gateStart);
    const progress = Math.max(0, Math.min(1, Number(meta.layerProgress || 0)));
    const anchor = minAge + Math.round((maxAge - minAge) * progress);
    const bucket = Math.max(1, Math.floor((maxAge - minAge) / Math.max(2, gateLength + 1)));
    const variance = Math.max(0, Math.floor(bucket * 0.45));
    const offset = variance > 0 ? pickTemporaryBattleInt(-variance, variance, rng) : 0;
    return Math.max(minAge, Math.min(maxAge, anchor + offset));
  }

  function buildSoulTowerGuardianSeed(floor = 1, options = {}) {
    const safeFloor = Math.max(1, Math.floor(toNumber(floor, 1)));
    const rng = typeof options.rng === 'function' ? options.rng : Math.random;
    const speciesPool =
      Array.isArray(options.speciesPool) && options.speciesPool.length
        ? options.speciesPool
        : BATTLE_SOUL_BEAST_STANDARD_SPECIES;
    const species = toText(options.species, pickTemporaryBattleItem(speciesPool, rng) || '龙类') || '龙类';
    const age = Math.max(1, Math.floor(toNumber(options.age, buildSoulTowerGuardianAgeForFloor(safeFloor, rng))));
    const quality =
      normalizeSoulSpiritQuality(options.品质 || options.quality || getSoulTowerGuardianQualityForFloor(safeFloor)) ||
      'C';
    const name = toText(options.name, '');
    return {
      name,
      名称: name,
      来源: '临时单位',
      单位性质: '魂兽',
      数量: 1,
      标准物种: species,
      具体物种: toText(options.具体物种, species),
      物种品质: '普通',
      年限: age,
      品质: quality,
    };
  }

  function buildSoulTowerDiscountSpiritRecordFromSeed(floor = 1, seed = {}) {
    const safeFloor = Math.max(1, Math.floor(toNumber(floor, 1)));
    const species = toText(seed.标准物种, '');
    const age = Math.max(0, Math.floor(toNumber(seed.年限, 0)));
    const quality = normalizeSoulSpiritQuality(seed.品质 || '');
    const 名称 = toText(seed.name || seed.名称, '');
    if (!(species && age > 0 && quality)) return createEmptySoulTowerDiscountSpiritRecord();
    return {
      层数: safeFloor,
      名称: 名称 || `${species}魂灵`,
      标准物种: species,
      年限: age,
      品质: quality,
      已使用: false,
    };
  }

  function 构建魂灵塔待结算记录(combatData = {}, 守塔单位 = {}) {
    const 层数 = Math.min(SOUL_TOWER_TOTAL_FLOORS, Math.max(1, Math.floor(toNumber(combatData.floor, 1))));
    const 大关信息 = getSoulTowerGateMeta(层数);
    const 五折魂灵 = buildSoulTowerDiscountSpiritRecordFromSeed(层数, 守塔单位 || {});
    if (!(五折魂灵.层数 > 0)) return null;
    return {
      状态: '待选择',
      层数,
      区域标签: 大关信息.gateLabel,
      区间标签: 大关信息.gateRangeLabel,
      守塔名称: toText((守塔单位 || {}).name || (守塔单位 || {}).名称, 五折魂灵.名称),
      五折魂灵,
      下一层: Math.min(SOUL_TOWER_TOTAL_FLOORS, 层数 + 1),
      可继续: 层数 < SOUL_TOWER_TOTAL_FLOORS,
    };
  }

  function buildSoulTowerTeamValidationResult(members = []) {
    const safeMembers = Array.isArray(members) ? members.filter(member => member && typeof member === 'object') : [];
    if (!safeMembers.length) return { ok: false, message: '魂灵塔队伍为空。' };
    if (safeMembers.length > SOUL_TOWER_TEAM_LIMIT) {
      return { ok: false, message: `魂灵塔队伍最多 ${SOUL_TOWER_TEAM_LIMIT} 人。` };
    }
    const invalidAgeMember = safeMembers.find(member => !(member.age > 0) || member.age > SOUL_TOWER_MAX_AGE);
    if (invalidAgeMember) {
      return {
        ok: false,
        message: `${toText(invalidAgeMember.name, '队员')} 已超过 ${SOUL_TOWER_MAX_AGE} 岁，不能参与魂灵塔。`,
      };
    }
    const ages = safeMembers.map(member => Number(member.age || 0)).filter(age => age > 0);
    const minAge = Math.min(...ages);
    const maxAge = Math.max(...ages);
    if (maxAge - minAge > SOUL_TOWER_MAX_AGE_GAP) {
      return { ok: false, message: `魂灵塔队伍成员年龄差不能超过 ${SOUL_TOWER_MAX_AGE_GAP} 岁。` };
    }
    return {
      ok: true,
      count: safeMembers.length,
      minAge,
      maxAge,
      totalFloors: SOUL_TOWER_TOTAL_FLOORS,
    };
  }



  function buildTrialBattleDispatchDetail(snapshot, dispatchDetail = {}, trialContext = null) {
    const sourceSnapshot = snapshot && snapshot.rootData ? snapshot : liveSnapshot || lastRenderableSnapshot;
    if (!sourceSnapshot || !sourceSnapshot.rootData) return null;
    const baseDetail = { ...cloneJsonValue(dispatchDetail, {}) };
    const 显式参战者 =
      baseDetail.参战者 && typeof baseDetail.参战者 === 'object' ? cloneJsonValue(baseDetail.参战者, {}) : null;
    const 显式己方队伍 = Array.isArray(显式参战者 && 显式参战者.team_player)
      ? cloneJsonValue(显式参战者.team_player, [])
      : [];
    const 状态上下文 = 解析试炼地点(读取试炼状态文本(sourceSnapshot));
    const safeContext = 规范化试炼状态上下文(trialContext || 状态上下文 || null);
    if (!safeContext) return null;
    const activeKey = resolveSnapshotCharKey(sourceSnapshot, toText(sourceSnapshot && sourceSnapshot.activeName, ''));
    if (!activeKey) return null;
    const activeName = toText(
      deepGet(sourceSnapshot, ['rootData', 'char', activeKey, 'name'], ''),
      toText(sourceSnapshot && sourceSnapshot.activeName, activeKey),
    );
    if (safeContext.试炼类型 === '升灵台') {
      const ascensionResult = 生成升灵台战斗参数(sourceSnapshot, safeContext);
      return {
        ...baseDetail,
        action: 'battle',
        currentLoc: safeContext.试炼内地点 || 读取当前角色位置(sourceSnapshot),
        target: safeContext.试炼内地点 || 读取当前角色位置(sourceSnapshot),
        战斗类型: '升灵台虚拟战斗',
        战斗意图: '升灵试炼',
        source: toText(baseDetail.source, 'trial_entry'),
        试炼状态: safeContext.试炼内地点 || 构建升灵台试炼地点(safeContext.档位, safeContext.暴动期),
        ascension_ticket: toText(baseDetail.ascension_ticket, safeContext.门票名),
        killed_age: Math.max(1, Math.floor(toNumber(baseDetail.killed_age, ascensionResult.killedAge))),
        party_size: Math.max(1, Math.floor(toNumber(baseDetail.party_size, 1))),
        升灵对手类型: toText(baseDetail.升灵对手类型, ascensionResult.对手类型),
        升灵档位百分位: Math.max(0, Math.min(1, toNumber(baseDetail.升灵档位百分位, ascensionResult.百分位))),
        参战者: {
          team_player: [{ name: activeName || activeKey }, ...显式己方队伍],
          team_enemy: [cloneJsonValue(ascensionResult.对手种子, {})],
        },
      };
    }
    if (safeContext.试炼类型 === '魂灵塔') {
      const 塔层基准值 = toNumber(
        baseDetail.floor,
        toNumber(
          deepGet(
            sourceSnapshot,
            'rootData.world.战斗.floor',
            safeContext.当前层 || getDefaultSoulTowerChallengeFloor(sourceSnapshot),
          ),
          safeContext.当前层 || getDefaultSoulTowerChallengeFloor(sourceSnapshot),
        ),
      );
      const requestedFloor = Math.min(SOUL_TOWER_TOTAL_FLOORS, Math.max(1, Math.floor(塔层基准值)));
      const guardianSeed = 构建魂灵塔守塔种子({ ...safeContext, 当前层: requestedFloor });
      const 显式敌方队伍 = Array.isArray(显式参战者 && 显式参战者.team_enemy)
        ? cloneJsonValue(显式参战者.team_enemy, [])
        : [];
      const 显式敌方 = 显式敌方队伍[0] && typeof 显式敌方队伍[0] === 'object' ? cloneJsonValue(显式敌方队伍[0], {}) : null;
      const 显式敌方名称 = toText(显式敌方 && (显式敌方.name || 显式敌方.名称), '').trim();
      if (!显式敌方名称) {
        return {
          invalid: true,
          reason: '魂灵塔 battle 路由缺少正式敌方名称。',
          战斗类型: '魂灵塔冲塔',
          floor: requestedFloor,
        };
      }
      const 敌方种子 = {
        ...guardianSeed,
        ...(显式敌方 || {}),
        name: 显式敌方名称,
        名称: 显式敌方名称,
        标准物种: toText(显式敌方 && 显式敌方.标准物种, guardianSeed.标准物种),
        年限: Math.max(1, Math.floor(toNumber(显式敌方 && 显式敌方.年限, guardianSeed.年限))),
        品质: normalizeSoulSpiritQuality((显式敌方 && 显式敌方.品质) || guardianSeed.品质) || guardianSeed.品质,
      };
      return {
        ...baseDetail,
        action: 'battle',
        currentLoc: safeContext.试炼内地点 || 构建魂灵塔试炼地点(requestedFloor),
        target: safeContext.试炼内地点 || 构建魂灵塔试炼地点(requestedFloor),
        战斗类型: '魂灵塔冲塔',
        战斗意图: '魂灵塔试炼',
        source: toText(baseDetail.source, 'trial_entry'),
        试炼状态: safeContext.试炼内地点 || 构建魂灵塔试炼地点(requestedFloor),
        floor: requestedFloor,
        soulTowerTicket: toText(baseDetail.soulTowerTicket, safeContext.门票名),
        门票已扣除: true,
        参战者: {
          team_player: [{ name: activeName || activeKey }, ...显式己方队伍],
          team_enemy: [cloneJsonValue(敌方种子, {})],
        },
      };
    }
    return null;
  }


  // 私密档案入口规则（设计约定）：
  // - 只对「女性」且 属性.年龄 为有效数值、满 18 岁的角色开放；年龄缺失、为 0 或无法解析一律视为不满足，此时入口、路由与页面都不存在。
  // - 不在任何导航中直接显示（座舱子页列表、操作台按键都不列出），也不为它单独设计控件；只借用已有内容（角色名、档案天幕、档案标题等）挂 data-longpress 长按触发。
  // - 所有打开路径（长按、预览路由、详情页构建）都要经过本函数复核；新增入口时同样遵守。
  function canOpenPrivateArchive(snapshot) {
    const activeChar = getActiveSnapshotCharacter(snapshot);
    const genderText = toText(deepGet(activeChar, '属性.性别', ''), '');
    if (!isFemaleGenderText(genderText)) return false;
    const ageValue = getPrivateArchiveAgeValue(deepGet(activeChar, '属性.年龄', null));
    return Number.isFinite(ageValue) && ageValue >= 18;
  }

  function getActiveNsfwPath(snapshot) {
    const activeCharKey = resolveSnapshotCharKey(snapshot, toText(snapshot && snapshot.activeName, ''));
    return activeCharKey ? ['char', activeCharKey, '私密档案'] : [];
  }

  function getActiveNsfwData(snapshot) {
    const activeNsfw = deepGet(snapshot, 'activeChar.私密档案', null);
    if (activeNsfw && typeof activeNsfw === 'object' && safeEntries(activeNsfw).length) return activeNsfw;
    const activeCharKey = resolveSnapshotCharKey(snapshot, toText(snapshot && snapshot.activeName, ''));
    const rootNsfw = activeCharKey ? deepGet(snapshot, ['rootData', 'char', activeCharKey, '私密档案'], null) : null;
    if (rootNsfw && typeof rootNsfw === 'object') return rootNsfw;
    return activeNsfw && typeof activeNsfw === 'object' ? activeNsfw : {};
  }


  function syncPrivateArchiveLongPressTargets() {}






  function createRoutineActionBridge(ports) {
    const previews = new Map();
    const executing = new Set();
    const pendingNarrations = new Map();
    let cacheContext = '';
    let receiptSequence = 0;
    const labels = { rest: '休整', sleep: '睡眠', meditate: '冥想', train: '训练' };
    const modes = { rest: '睡眠', sleep: '睡眠', meditate: '冥想' };
    const projects = ['力量', '防御', '敏捷', '体魄', '精神'];
    function prepare(options = {}) {
      const current = ports.read();
      const fail = reason => ({ allowed: false, reason, contextKey: current.contextKey, revision: current.revision, changes: [] });
      if (!current.root || !current.character || !current.chatId) return { error: fail('尚未读取到当前角色与聊天。') };
      if (!current.playerControlled) return { error: fail('正在查看他人，仅能阅读其状态。') };
      if (options.contextKey !== undefined && options.contextKey !== current.contextKey) return { error: fail('角色或聊天已改变，请重新查看预计结果。') };
      if (options.revision !== undefined && options.revision !== current.revision) return { error: fail('当前状态已改变，请重新查看预计结果。') };
      const action = String(options.action || '');
      const durationMinutes = Number(options.durationMinutes);
      const trainingProject = String(options.trainingProject || '力量');
      if (!Object.hasOwn(labels, action)) return { error: fail('请选择可用的日常行动。') };
      if (!Number.isInteger(durationMinutes) || durationMinutes < 10 || durationMinutes > 1440 || durationMinutes % 10) return { error: fail('请输入 10～1440 分钟，按 10 分钟递增。') };
      if (action === 'train' && !projects.includes(trainingProject)) return { error: fail('请选择可用的训练侧重。') };
      const actionMode = action === 'train' ? (trainingProject === '精神' ? '精神训练' : '肉体训练') : modes[action];
      const context = ports.worldContext(current, actionMode, durationMinutes / 10);
      if (!context.ok) return { error: fail(context.reason || '当前地点暂时无法进行此项行动。') };
      const attributes = current.character.属性 || {};
      const conditions = [];
      if (actionMode === '肉体训练') {
        const required = Math.max(1, Number(attributes.体力上限) || 1) * .3;
        const enough = Number(attributes.体力) >= required;
        conditions.push({ label: '体力', current: Number(attributes.体力) || 0, required, met: enough });
        if (!enough) return { error: { ...fail('体力不足以完成一轮训练，请先休整。'), conditions } };
      }
      if (actionMode === '精神训练') {
        const required = Math.max(1, Number(attributes.精神力上限) || 1) * .1;
        const enough = Number(attributes.精神力) > required;
        conditions.push({ label: '精神', current: Number(attributes.精神力) || 0, required, met: enough });
        if (!enough) return { error: { ...fail('精神不足以完成一轮训练，请先调息。'), conditions } };
      }
      const key = `${current.contextKey}|${current.revision}`;
      if (key !== cacheContext) { previews.clear(); cacheContext = key; }
      return { current, action, durationMinutes, trainingProject, actionMode, conditions, key: `${action}|${durationMinutes}|${action === 'train' ? trainingProject : ''}` };
    }
    function calculate(prepared) {
      const { current, action, durationMinutes, actionMode, conditions } = prepared;
      const startTick = Number(current.root.world?.时间?.tick) || 0;
      const settledRoot = ports.settle(current.root, current.charKey, startTick, startTick + durationMinutes / 10, actionMode);
      const after = settledRoot?.char?.[current.charKey];
      if (!after) throw new Error('本次行动没有返回角色结果。');
      const beforeValues = ports.projectAttributes(current.character);
      const afterValues = ports.projectAttributes(after);
      const changes = beforeValues.flatMap(before => {
        const next = afterValues.find(item => item.key === before.key);
        return next && Math.abs(next.value - before.value) > 1e-9 ? [{ key: before.key, label: before.label, before: before.value, after: next.value }] : [];
      });
      const preview = { allowed: true, reason: '', contextKey: current.contextKey, revision: current.revision, changes, conditions, summary: `${labels[action]} ${durationMinutes} 分钟${changes.length ? '后的预计变化' : '，当前资源与属性没有数值变化'}` };
      return { preview, settledRoot };
    }
    function previewRoutineAction(options = {}) {
      const prepared = prepare(options);
      if (prepared.error) return prepared.error;
      if (previews.has(prepared.key)) return structuredClone(previews.get(prepared.key));
      const result = calculate(prepared).preview;
      previews.set(prepared.key, result);
      if (previews.size > 4) previews.delete(previews.keys().next().value);
      return structuredClone(result);
    }
    async function executeRoutineAction(options = {}) {
      const initial = ports.read();
      const contextKey = initial.contextKey;
      if (options.contextKey !== undefined && options.contextKey !== contextKey) return { ok: false, settled: false, message: '角色或聊天已改变，请重新查看预计结果。' };
      if (executing.has(contextKey)) return { ok: false, settled: false, message: '同一行动仍在办理，请稍候。' };
      const pending = pendingNarrations.get(contextKey);
      if (pending) return { ok: false, settled: true, receiptId: pending.id, message: '上一项行动已结算，叙事尚未完成。请重试叙事。' };
      executing.add(contextKey);
      try {
        await ports.refresh();
        const prepared = prepare({ ...options, contextKey });
        if (prepared.error) return { ok: false, settled: false, message: prepared.error.reason, preview: prepared.error };
        const { preview, settledRoot } = calculate(prepared);
        const { current, durationMinutes, action, trainingProject } = prepared;
        const actionLabel = action === 'train' ? `${trainingProject}训练` : labels[action];
        const systemText = `${String(settledRoot.sys?.系统播报 || '').replace(/^初始化$/, '')} ${current.charKey} 在【${current.location}】进行${actionLabel}，耗时 ${durationMinutes} 分钟。`.trim();
        const patchOps = ports.buildPatches(current.charKey, settledRoot, systemText);
        const playerInput = `我在【${current.location}】进行 ${durationMinutes} 分钟${actionLabel}。`;
        const resultSummary = preview.changes.map(item => `${item.label} ${item.before} → ${item.after}`).join('；') || '当前数值无变化';
        const systemPrompt = `[日常行动]\n角色：${current.charKey}\n地点：${current.location}\n动作：${actionLabel}\n耗时：${durationMinutes} 分钟\n已结算结果：${resultSummary}\n本次行动已经由前端按正式规则结算，收益已写回，行动耗时仅用于本轮时间裁定。请承接行动过程、收获及后续剧情，不重复结算收益，不输出 JSON、变量维护指令或系统术语。`;
        const result = await ports.dispatch(playerInput, systemPrompt, { requestKind: `map_action_${action === 'train' ? (trainingProject === '精神' ? 'train_mind' : 'train_body') : action}`, patchOps, settlementKind: 'routine', silent: true, contextKey, expectedRoot: current.root });
        previews.clear();
        if (result?.ok && result.settlementCommitted === true) return { ...result, settled: true, message: `${actionLabel}已完成。` };
        if (result?.settlementCommitted) {
          const receipt = { id: `routine-${++receiptSequence}`, contextKey, chatId: current.chatId, charKey: current.charKey, playerInput, systemPrompt, requestId: result.requestId || '', userMessageId: result.userMessageId, requestKind: `map_action_${action}`, createdAt: Date.now() };
          pendingNarrations.set(contextKey, receipt);
          if (pendingNarrations.size > 8) pendingNarrations.delete(pendingNarrations.keys().next().value);
          return { ok: false, settled: true, receiptId: receipt.id, message: `${actionLabel}已结算，叙事未完成。重试叙事不会再次结算行动收益。` };
        }
        return { ok: false, settled: false, message: result?.message || '行动未提交，尚未完成结算。请稍后重试。' };
      } finally { executing.delete(contextKey); }
    }
    async function retryNarration(contextKey, receiptId) {
      const receipt = pendingNarrations.get(contextKey);
      const current = ports.read();
      if (!receipt || receipt.id !== receiptId || contextKey !== current.contextKey || receipt.chatId !== current.chatId) return { ok: false, message: '该行动的上下文已改变，请在原聊天中重试续写。' };
      if (executing.has(contextKey)) return { ok: false, settled: true, receiptId, message: '叙事仍在办理，请稍候。' };
      executing.add(contextKey);
      try {
        const result = Number.isInteger(receipt.userMessageId)
          ? await ports.retry(receipt.requestId || receipt.userMessageId)
          : await ports.dispatch(receipt.playerInput, receipt.systemPrompt, { requestKind: receipt.requestKind, patchOps: [], silent: true, contextKey });
        if (result?.ok) { pendingNarrations.delete(contextKey); return { ok: true, settled: true, message: '叙事已补全，本次没有重复结算。' }; }
        if (Number.isInteger(result?.userMessageId)) { receipt.userMessageId = result.userMessageId; receipt.requestId = result.requestId || ''; }
        return { ok: false, settled: true, receiptId, message: '叙事尚未完成，已结算的结果保持不变。' };
      } finally { executing.delete(contextKey); }
    }
    // 待重试的叙事回执（座舱据此把「开始行动」换成「重试叙事」）
    const pendingNarration = contextKey => { const r = pendingNarrations.get(contextKey); return r ? { receiptId: r.id, playerInput: r.playerInput } : null; };
    return { previewRoutineAction, executeRoutineAction, retryNarration, pendingNarration };
  }


  let statusCabinInstance = null;
