  function getSoulBeastAgeBandName(age = 1) {
    const value = Math.max(1, Math.floor(Number(age || 1)));
    if (value >= 100000) return '十万年';
    if (value >= 10000) return '万年';
    if (value >= 1000) return '千年';
    if (value >= 100) return '百年';
    return '十年';
  }

  function buildSoulBeastBestiaryKey(age = 1, specificSpecies = '') {
    const species = String(specificSpecies || '').trim();
    return species ? `${getSoulBeastAgeBandName(age)}${species}` : '';
  }

  function normalizeSoulBeastQualityTier(value = '') {
    const text = String(value || '').trim();
    if (Object.prototype.hasOwnProperty.call(BATTLE_SOUL_BEAST_QUALITY_TIER_MULTIPLIERS, text)) return text;
    return '普通';
  }

  function getSoulBeastQualityTierMultiplier(value = '') {
    return Number(BATTLE_SOUL_BEAST_QUALITY_TIER_MULTIPLIERS[normalizeSoulBeastQualityTier(value)] || 1);
  }

  const BATTLE_TEMPORARY_TYPE_MULTIPLIERS = Object.freeze({
    强攻系: { sp_max: 1.0, men_max: 1.0, str: 1.0, def: 1.0, agi: 1.0, vit_max: 1.0 },
    防御系: { sp_max: 1.0, men_max: 1.0, str: 0.9, def: 1.5, agi: 0.7, vit_max: 1.0 },
    敏攻系: { sp_max: 1.0, men_max: 1.0, str: 0.8, def: 0.7, agi: 1.6, vit_max: 0.8 },
    控制系: { sp_max: 1.0, men_max: 1.2, str: 0.9, def: 0.8, agi: 1.1, vit_max: 0.9 },
    辅助系: { sp_max: 1.2, men_max: 1.2, str: 0.7, def: 0.6, agi: 0.8, vit_max: 0.7 },
    食物系: { sp_max: 1.2, men_max: 1.2, str: 0.7, def: 0.6, agi: 0.8, vit_max: 0.7 },
    治疗系: { sp_max: 1.2, men_max: 1.2, str: 0.7, def: 0.6, agi: 0.8, vit_max: 0.7 },
  });

  function getTemporaryBattleBaseStats(level = 1) {
    const 基础属性函数 = 读取窗口函数('__LWCS_GET_BASE_STATS__');
    if (typeof 基础属性函数 !== 'function') {
      throw new Error('MVU基础属性函数未加载');
    }
    const 基础 = 基础属性函数(level);
    return {
      sp_max: Math.floor(Number(基础.sp_max || 0)),
      men_max: Math.floor(Number(基础.men_max || 0)),
      str: Math.floor(Number(基础.str || 0)),
      def: Math.floor(Number(基础.def || 0)),
      agi: Math.floor(Number(基础.agi || 0)),
      vit_max: Math.floor(Number(基础.vit_max || 0)),
    };
  }

  function buildSkillDesignConfirmState(snapshot) {
    const state = 待处理技能设计确认 && typeof 待处理技能设计确认 === 'object' ? 待处理技能设计确认 : null;
    if (!state) return null;
    if (state.growthRecord && typeof state.growthRecord === 'object') {
      return {
        ...state,
        charName: toText(state.charName || state.growthRecord.角色名, ''),
        sourceLabel: toText(state.sourceLabel, '成长技能模板'),
        skillName: normalizeSkillUiText(state.growthRecord.魂技名 || state.growthRecord.技能名称, '成长技能'),
        signature: toText(state.signature, ''),
      };
    }
    const previewKey = toText(state.previewKey, '').trim();
    const previewMeta = parseSkillDesignerPreviewKey(previewKey);
    if (!previewKey || !previewMeta || !Array.isArray(previewMeta.path) || !previewMeta.path.length) return null;
    const safeSnapshot = snapshot && typeof snapshot === 'object' ? snapshot : liveSnapshot || lastRenderableSnapshot;
    const skillSource =
      safeSnapshot && safeSnapshot.rootData ? deepGet(safeSnapshot.rootData, previewMeta.path, null) : null;
    if (!skillSource || typeof skillSource !== 'object') return null;
    return {
      ...state,
      previewKey,
      previewMeta,
      charName: toText(state.charName, safeSnapshot ? toText(safeSnapshot.activeName, '') : ''),
      sourceLabel: toText(state.sourceLabel, previewMeta.category || '技能'),
      skillName: normalizeSkillUiText(skillSource['魂技名'] || skillSource.name, previewMeta.label || '新技能'),
      signature: toText(state.signature, previewKey),
    };
  }

  function 打开技能设计确认(确认数据 = {}) {
    const previewKey = toText(确认数据.previewKey, '').trim();
    if (!previewKey || !isSkillDesignerPreviewKey(previewKey)) return false;
    const signature = toText(确认数据.signature || previewKey, previewKey);
    const currentState = buildSkillDesignConfirmState(liveSnapshot || lastRenderableSnapshot);
    if (currentState && (currentState.previewKey === previewKey || currentState.signature === signature)) {
      openDetailPreview(PENDING_SKILL_DESIGN_PREVIEW_KEY, {
        preserveMapDispatchContext: true,
        replace: true,
      });
      return true;
    }
    待处理技能设计确认 = {
      previewKey,
      charName: toText(确认数据.charName, ''),
      sourceLabel: toText(确认数据.sourceLabel, '技能'),
      returnPreviewKey: toText(确认数据.returnPreviewKey, ''),
      submitAfterSave: 确认数据.submitAfterSave !== false,
      signature,
    };
    if (!buildSkillDesignConfirmState(liveSnapshot || lastRenderableSnapshot)) {
      待处理技能设计确认 = null;
      return false;
    }
    openDetailPreview(PENDING_SKILL_DESIGN_PREVIEW_KEY, {
      preserveMapDispatchContext: true,
      replace: true,
    });
    return true;
  }

  function 继续现有技能获得流程() {
    const state = buildSkillDesignConfirmState(liveSnapshot || lastRenderableSnapshot);
    if (state?.growthRecord && state.signature) 已跳过成长技能确认签名.add(state.signature);
    const skillName = normalizeSkillUiText(state?.skillName, '当前技能');
    const returnPreviewKey = toText(state?.returnPreviewKey, '').trim();
    待处理技能设计确认 = null;
    if (returnPreviewKey) {
      openDetailPreview(returnPreviewKey, { preserveMapDispatchContext: true, replace: true });
    } else {
      closeDetailSurface({
        surface: currentUnifiedPreviewKey === PENDING_SKILL_DESIGN_PREVIEW_KEY ? 'unified' : 'modal',
      });
    }
    showUiToast(`已保留【${skillName}】。`, 'success', 2200);
  }

  function 构建成长技能模板预览键(记录 = {}) {
    const 角色名 = toText(记录 && 记录.角色名, '').trim();
    const 写入路径 = toText(记录 && 记录.写入路径, '').trim();
    const 写入类型 = toText(记录 && 记录.写入类型, '').trim();
    if (!角色名 || !写入路径) return '';
    const path = ['char', 角色名, ...写入路径.split('.').map(片段 => toText(片段, '').trim()).filter(Boolean)];
    if (写入类型 === '武魂融合技' && path[path.length - 1] !== '技能数据') path.push('技能数据');
    return buildSkillDesignerPreviewKey({
      path,
      label: toText(记录.魂技名 || 记录.技能名称, path[path.length - 1] || '成长技能'),
      category: 写入类型 || '成长技能',
      scope: 写入类型 === '自创魂技' ? '自创魂技' : 写入类型 === '武魂融合技' ? '武魂融合技' : '魂技',
    });
  }

  async function 应用成长技能模板并打开设计台(记录 = {}) {
    const runtime = 读取MVUSchema运行时接口_桥接();
    if (!runtime || typeof runtime.应用内置角色成长技能模板记录 !== 'function') {
      showUiToast('成长技能模板接口不可用。', 'error', 4200);
      return false;
    }
    let previewKey = 构建成长技能模板预览键(记录);
    let result = null;
    try {
      await mutateStatDataByEditor(
        statData => {
          result = runtime.应用内置角色成长技能模板记录(statData, 记录);
          if (!result || result.changed !== true) throw new Error(result?.reason || 'growth_skill_not_written');
        },
        { force: true },
      );
      await refreshLiveSnapshot({ force: true });
    } catch (error) {
      showUiToast(error && error.message ? error.message : '成长技能写入失败。', 'error', 4200);
      return false;
    }
    待处理技能设计确认 = null;
    if (previewKey && isSkillDesignerPreviewKey(previewKey)) {
      openDetailPreview(previewKey, { preserveMapDispatchContext: true, replace: true });
    } else {
      closeModal();
      showUiToast('成长技能已采用。', 'info', 2200);
    }
    return true;
  }

  function 打开待处理技能设计台(snapshot) {
    const state = buildSkillDesignConfirmState(snapshot);
    if (!state) throw new Error('当前没有可设计的技能。');
    if (state.growthRecord) {
      void 应用成长技能模板并打开设计台(state.growthRecord);
      return;
    }
    openDetailPreview(state.previewKey, { preserveMapDispatchContext: true, replace: true });
  }

  async function 准备剧情技能自行设计(选项 = {}) {
    const snapshot = liveSnapshot || lastRenderableSnapshot || (await getLiveSnapshot());
    const activeName = toText(snapshot && snapshot.activeName, '');
    const 输入角色名 = toText(选项.角色 || 选项.charName || 选项.character || activeName, activeName);
    const charKey = resolveSnapshotCharKey(snapshot, 输入角色名) || resolveSnapshotCharKey(snapshot, activeName) || activeName;
    if (!charKey) throw new Error('未找到当前角色，无法新建技能设计。');
    const skillType = /武魂融合技/.test(toText(选项.技能类型 || 选项.type || '', '')) ? '武魂融合技' : '自创魂技';
    const skillKey = `剧情技能_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 6)}`;
    const skillLabel = toText(选项.label || 选项.技能名称 || 选项.name, '剧情新技能');
    const path = skillType === '武魂融合技'
      ? ['char', charKey, '武魂融合技', skillLabel, '技能数据']
      : ['char', charKey, '自创魂技', skillKey];
    const previewKey = buildSkillDesignerPreviewKey({
      path,
      label: skillLabel,
      category: skillType,
      scope: skillType,
    });
    await mutateStatDataByEditor(
      statData => {
        const charData = deepGet(statData, ['char', charKey], null);
        if (!charData || typeof charData !== 'object') throw new Error('未找到当前角色。');
        if (skillType === '武魂融合技') {
          if (!charData.武魂融合技 || typeof charData.武魂融合技 !== 'object' || Array.isArray(charData.武魂融合技)) charData.武魂融合技 = {};
          if (!charData.武魂融合技[skillLabel] || typeof charData.武魂融合技[skillLabel] !== 'object' || Array.isArray(charData.武魂融合技[skillLabel])) charData.武魂融合技[skillLabel] = {};
          if (!charData.武魂融合技[skillLabel].技能数据) {
            charData.武魂融合技[skillLabel].技能数据 = {
              魂技名: skillLabel,
              画面描述: '未知',
              效果描述: '未知',
              _效果数组: [],
            };
          }
          return;
        }
        if (!charData.自创魂技 || typeof charData.自创魂技 !== 'object' || Array.isArray(charData.自创魂技)) charData.自创魂技 = {};
        if (!charData.自创魂技[skillKey]) {
          charData.自创魂技[skillKey] = {
            魂技名: skillLabel,
            画面描述: '未知',
            效果描述: '未知',
            _效果数组: [],
          };
        }
      },
      { force: true },
    );
    await refreshLiveSnapshot({ force: true });
    const opened = 打开技能设计确认({
      previewKey,
      charName: 输入角色名 || activeName || charKey,
      sourceLabel: toText(选项.sourceLabel, '剧情获得技能'),
      submitAfterSave: true,
      signature: `story_skill::${charKey}::${skillType}::${skillLabel}`,
    });
    if (!opened) throw new Error('技能记录创建后无法打开确认页。');
    return { ok: true, previewKey, skillKey };
  }

  function 规范化传授内容类型(内容类型 = '') {
    const 文本 = toText(内容类型, '').trim();
    if (/情报|信息|秘密|机密/.test(文本)) return '情报';
    if (/功法|心法|绝学/.test(文本)) return '功法';
    if (/秘技|战斗技巧|技巧|技艺/.test(文本)) return '战斗技巧';
    if (/自创魂技|魂技|技能/.test(文本)) return '自创魂技';
    return 文本 || '情报';
  }

  function 构建功法学习记录_桥接(功法名 = '', 描述 = '未知', 根数据 = {}) {
    const 名称 = toText(功法名, '').trim();
    const 功法描述 = normalizeSkillUiText(描述, '未知');
    if (名称 !== '紫极魔瞳') return { 描述: 功法描述 };
    const 当前tick = Math.max(0, Math.floor(toNumber(deepGet(根数据, ['world', '时间', 'tick'], 0), 0)));
    return { 境界: '纵观', lv: 1, 获得tick: 当前tick, 描述: 功法描述 };
  }

  function 解析传授模块意图请求(snapshot, payload = {}) {
    const 学生名 = toText(payload.学生 || payload.student || payload.角色 || payload.char || snapshot?.activeName, '').trim();
    const 老师名 = toText(payload.老师 || payload.teacher || payload.对象 || payload.npc || payload.target, '').trim();
    const 内容名称 = toText(payload.内容名称 || payload.名称 || payload.name || payload.内容 || payload.targetName, '').trim();
    const 内容类型 = 规范化传授内容类型(payload.内容类型 || payload.type || payload.category || payload.类型);
    const 结果 = toText(payload.结果 || payload.result || '成立', '成立').trim();
    const 理由 = toText(payload.理由 || payload.reason, '').trim();
    const 效果数组 = Array.isArray(payload._效果数组) ? payload._效果数组 : [];
    const 已定义 = payload.已定义 === true || (payload.已定义 !== false && 效果数组.length > 0);
    const 学生 = resolveSnapshotCharacter(snapshot, 学生名 || snapshot?.activeName);
    const 老师 = 老师名 ? resolveSnapshotCharacter(snapshot, 老师名) : { key: '', displayName: '', char: null };
    if (!学生.key || !学生.char) return { invalid: true, reason: 'teaching_student_unresolved', 学生: 学生名, 老师: 老师名, 内容类型, 内容名称, 结果, 理由 };
    if (!内容名称) return { invalid: true, reason: 'teaching_content_missing', 学生: 学生.displayName || 学生.key, 老师: 老师.displayName || 老师名, 内容类型, 内容名称, 结果, 理由 };
    return {
      动作: toText(payload.动作 || payload.action, '请教'),
      老师: 老师.displayName || 老师名,
      teacherKey: 老师.key || '',
      学生: 学生.displayName || 学生.key,
      studentKey: 学生.key,
      内容类型,
      内容名称,
      结果,
      理由,
      _效果数组: 效果数组,
      已定义,
      画面描述: toText(payload.画面描述, '').trim(),
      效果描述: toText(payload.效果描述, '').trim(),
      承载方式: toText(payload.承载方式, '').trim(),
      消耗: payload.消耗,
      前摇: payload.前摇,
    };
  }

  async function 打开传授技能设计台(request = {}) {
    const studentKey = toText(request.studentKey, '').trim();
    const skillLabel = toText(request.内容名称, '').trim();
    const 内容类型 = 规范化传授内容类型(request.内容类型);
    if (!studentKey || !skillLabel) throw new Error('传授内容缺少学生或名称。');
    const scope = 内容类型 === '功法' ? 'art' : '自创魂技';
    const category = 内容类型 === '功法' ? '功法' : '自创魂技';
    const parentKey = 内容类型 === '功法' ? '功法' : '自创魂技';
    const recordKey = skillLabel;
    const 已定义 = 内容类型 !== '功法' && request.已定义 === true && Array.isArray(request._效果数组) && request._效果数组.length > 0;
    const previewKey = buildSkillDesignerPreviewKey({
      path: ['char', studentKey, parentKey, recordKey],
      label: skillLabel,
      category,
      scope,
    });
    await mutateStatDataByEditor(
      statData => {
        const charData = deepGet(statData, ['char', studentKey], null);
        if (!charData || typeof charData !== 'object') throw new Error('未找到学生角色。');
        if (!charData[parentKey] || typeof charData[parentKey] !== 'object' || Array.isArray(charData[parentKey]))
          charData[parentKey] = {};
        if (已定义) {
          charData[parentKey][recordKey] = {
            魂技名: skillLabel,
            画面描述: normalizeSkillUiText(request.画面描述, '未知'),
            效果描述: normalizeSkillUiText(request.效果描述, '未知'),
            承载方式: toText(request.承载方式, '直接生效') || '直接生效',
            消耗: request.消耗 ?? '无',
            前摇: toNumber(request.前摇, 0),
            _效果数组: cloneJsonValue(request._效果数组, []),
          };
          return;
        }
        if (!charData[parentKey][recordKey]) {
          charData[parentKey][recordKey] = 内容类型 === '功法'
            ? 构建功法学习记录_桥接(skillLabel, '未知', statData)
            : { 魂技名: skillLabel, 画面描述: '未知', 效果描述: '未知', _效果数组: [] };
        }
      },
      { force: true },
    );
    await refreshLiveSnapshot({ force: true });
    if (已定义) return { ok: true, recordKey, 内容类型, 已定义: true, skipDesigner: true };
    打开技能设计确认({
      previewKey,
      charName: toText(request.学生, studentKey),
      sourceLabel: `${toText(request.老师, '他人')}传授${内容类型}`,
      submitAfterSave: true,
    });
    return { ok: true, previewKey, recordKey, 内容类型 };
  }

  async function 执行传授模块意图路由(snapshot, request = {}) {
    if (request.invalid) return 构建模块路由失败结果('teaching', request, request.reason || 'teaching_request_invalid');
    if (toText(request.结果, '成立') !== '成立') {
      return 构建模块路由成功结果('teaching', request, {
        dispatchMode: 'patch',
        skipped: true,
        reason: 'teaching_not_established',
      });
    }
    const 内容类型 = 规范化传授内容类型(request.内容类型);
    if (内容类型 === '情报') {
      await mutateStatDataByEditor(
        statData => {
          const intelPath = ['char', request.studentKey, '已掌握情报'];
          let knowledges = deepGet(statData, intelPath, null);
          if (!Array.isArray(knowledges)) {
            deepSetMutable(statData, intelPath, []);
            knowledges = deepGet(statData, intelPath, null);
          }
          if (!knowledges.some(item => toText(item, '').trim() === request.内容名称)) knowledges.push(request.内容名称);
        },
        { force: true },
      );
      await refreshLiveSnapshot({ force: true });
      return 构建模块路由成功结果('teaching', request, { dispatchMode: 'patch', 内容类型 });
    }
    const result = await 打开传授技能设计台({ ...request, 内容类型 });
    return 构建模块路由成功结果('teaching', request, {
      dispatchMode: 'settled_summary',
      result,
    });
  }

  async function 执行新技能获得模块意图路由(snapshot, request = {}) {
    if (request.invalid) return 构建模块路由失败结果('skill_gain', request, request.reason || 'skill_gain_request_invalid');
    const result = await 准备剧情技能自行设计({
      角色: request.charKey || request.角色,
      技能名称: request.技能名称,
      技能类型: request.技能类型,
      sourceLabel: request.来源 ? `剧情新技能：${request.来源}` : '剧情新技能',
    });
    return 构建模块路由成功结果('skill_gain', request, {
      dispatchMode: 'pending_confirmation',
      result,
    });
  }

  window.__LWCS_PROMPT_SKILL_DESIGN__ = async (选项 = {}) => {
    try {
      return await 准备剧情技能自行设计(选项);
    } catch (error) {
      showUiToast(error && error.message ? error.message : '技能设计入口打开失败。', 'error', 4200);
      return { ok: false, reason: error && error.message ? error.message : 'failed' };
    }
  };

  function hashTemporaryBattleSeed(seedText = '') {
    const text = String(seedText || '');
    let hash = 2166136261;
    for (let index = 0; index < text.length; index += 1) {
      hash ^= text.charCodeAt(index);
      hash = Math.imul(hash, 16777619);
    }
    return hash >>> 0;
  }

  function createTemporaryBattleRng(seedText = '') {
    let state = hashTemporaryBattleSeed(seedText) || 1;
    return () => {
      state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
      return state / 4294967296;
    };
  }

  function withTemporaryBattleRandom(seedText, runner) {
    const rng = createTemporaryBattleRng(seedText);
    return runner(rng);
  }

  function pickTemporaryBattleItem(items = [], rng = Math.random) {
    if (!Array.isArray(items) || !items.length) return '';
    return items[Math.max(0, Math.min(items.length - 1, Math.floor(rng() * items.length)))] || items[0];
  }

  function pickTemporaryBattleInt(min = 0, max = min, rng = Math.random) {
    const low = Math.floor(Math.min(min, max));
    const high = Math.floor(Math.max(min, max));
    if (high <= low) return low;
    return low + Math.floor(rng() * (high - low + 1));
  }

  function createTemporaryBattleSkillShell(skillName = '战技') {
    return {
      魂技名: skillName,
      画面描述: '未知',
      效果描述: '未知',
      _效果数组: [],
    };
  }

  function buildTemporaryBattleSkillMap(skillCount = 0, skillNames = []) {
    const total = Math.max(0, Math.min(4, Math.floor(Number(skillCount || 0))));
    const skillMap = {};
    for (let index = 1; index <= total; index += 1) {
      const skillName = String(skillNames[index - 1] || `战技${index}`).trim() || `战技${index}`;
      skillMap[skillName] = createTemporaryBattleSkillShell(skillName);
    }
    return skillMap;
  }

  function buildTemporarySoulBeastSkillNames(species = '', specificSpecies = '', skillCount = 0) {
    const baseNames = {
      龙类: ['龙息冲击', '龙鳞护体', '龙爪裂空', '龙威震慑'],
      蛛类: ['毒丝缠束', '蛛矛突刺', '蛛网封锁', '剧毒侵蚀'],
      熊类: ['厚甲冲撞', '撕裂爪击', '震地重压', '狂暴扑杀'],
      植物系: ['藤蔓缠束', '花粉迷障', '根须穿刺', '生命汲取'],
      海魂兽: ['水刃切割', '潮汐冲撞', '水幕护体', '深海压迫'],
      鸟类: ['疾羽切割', '俯冲突袭', '风翼闪避', '锐鸣震慑'],
      猫科: ['迅影扑杀', '裂爪连击', '潜伏突袭', '野性爆发'],
      蛇类: ['毒牙突袭', '蛇影缠杀', '鳞甲偏转', '麻痹毒雾'],
    }[species] || ['撕裂爪击', '厚甲冲撞', '毒牙突袭', '藤蔓缠束'];
    return baseNames.slice(0, Math.max(0, Math.floor(Number(skillCount || 0))));
  }

  function buildTemporaryAbyssSkillNames(race = '', skillCount = 0) {
    const text = String(race || '').trim();
    let baseNames = ['深渊撕裂', '深渊冲撞', '浊能护体', '裂隙压迫'];
    if (/蝙蝠/.test(text)) baseNames = ['翼刃切割', '音波扰乱', '俯冲撕咬', '群翼遮蔽'];
    else if (/蜂/.test(text)) baseNames = ['爆裂蜂刺', '自爆冲击', '毒雾扩散', '蜂群围杀'];
    else if (/魔|巴安|天牛|猛犸|魔傀/.test(text)) baseNames = ['深渊重击', '浊甲护体', '蛮力践踏', '深渊震荡'];
    else if (/黑皇|魔魅|恶镰|附体/.test(text)) baseNames = ['浊能侵袭', '精神扰乱', '影刃切割', '附体压制'];
    return baseNames.slice(0, Math.max(0, Math.floor(Number(skillCount || 0))));
  }

  function buildTemporaryHumanSkillNames(combatType = '', skillCount = 0) {
    const baseNames = {
      强攻系: ['正面强击', '魂力爆发', '破阵重击', '战意压迫'],
      防御系: ['护体免伤', '坚壁反震', '重盾压制', '阵地固守'],
      敏攻系: ['迅步突刺', '连环切击', '闪身追击', '残影扰乱'],
      控制系: ['魂力束缚', '节奏干扰', '领域压迫', '封锁牵引'],
      辅助系: ['魂力增幅', '节奏支援', '状态稳定', '协同强化'],
      食物系: ['补给凝成', '体力补充', '魂力滋养', '状态调和'],
      治疗系: ['伤势修复', '气息稳定', '持续治疗', '生命回流'],
      召唤系: ['召唤牵引', '协同攻势', '召唤护卫', '群体压制'],
    }[combatType] || ['正面强击', '魂力爆发', '迅步突刺', '护体免伤'];
    return baseNames.slice(0, Math.max(0, Math.floor(Number(skillCount || 0))));
  }

  function estimateTemporaryHumanSkillCount(level = 1) {
    const safeLevel = Math.max(1, Math.floor(Number(level || 1)));
    if (safeLevel >= 80) return 4;
    if (safeLevel >= 50) return 3;
    if (safeLevel >= 30) return 2;
    return 1;
  }

  function estimateTemporaryMonsterSkillCount(unitNature = '魂兽', seed = {}) {
    if (unitNature === '魂兽') {
      const age = Math.max(0, Math.floor(Number(seed?.年限 || 0)));
      if (age >= 100000) return 4;
      if (age >= 10000) return 3;
      if (age >= 1000) return 2;
      return 1;
    }
    const tier = String(seed?.级别 || '').trim();
    if (tier === '深渊帝君' || tier === '深渊王者') return 4;
    if (tier === '高阶生物') return 3;
    if (tier === '中阶生物') return 2;
    return 1;
  }

  function buildTemporaryBattleEquipmentShell() {
    return {
      武器: {
        名称: '无',
        品阶: '无',
        属性加成: { 魂力上限: 0, 精神力上限: 0, 力量: 0, 防御: 0, 敏捷: 0, 体力上限: 0 },
      },
      斗铠: { 等级: 0, 名称: '无', 领域: '无', 材质: '无', 装备状态: '未装备', 部件: {} },
      机甲: {
        等级: '无',
        名称: '无',
        型号: '无',
        材质: '无',
        状态: '无',
        装备状态: '未装备',
        武装: '无',
        品质系数: 1.0,
      },
    };
  }

  function buildTemporaryBattleSkeleton(name = '未知单位', unitNature = '人类') {
    return {
      name,
      来源: '临时单位',
      单位性质: unitNature,
      系别: '未知系',
      属性: {
        等级: 0,
        HP: 1,
        HP上限: 1,
        体力: 1,
        体力上限: 1,
        魂力: 0,
        魂力上限: 0,
        精神力: 1,
        精神力上限: 1,
        力量: 1,
        防御: 1,
        敏捷: 1,
        状态效果: {},
      },
      状态: {
        存活: true,
      },
      装备: buildTemporaryBattleEquipmentShell(),
      自创魂技: {},
      社交: { 势力: {} },
    };
  }

  function resolveTemporaryHumanCombatType(identity = '魂师', rng = Math.random, explicitType = '') {
    const requestedType = String(explicitType || '').trim();
    if (requestedType && BATTLE_TEMPORARY_TYPE_MULTIPLIERS[requestedType]) return requestedType;
    if (identity === '军人') {
      return pickTemporaryBattleItem(['强攻系', '强攻系', '防御系', '敏攻系', '控制系'], rng) || '强攻系';
    }
    return (
      pickTemporaryBattleItem(['强攻系', '敏攻系', '防御系', '控制系', '辅助系', '治疗系', '食物系', '召唤系'], rng) ||
      '强攻系'
    );
  }




  function 填充临时斗铠部件(斗铠, 性别文本 = '') {
    if (!斗铠 || typeof 斗铠 !== 'object') return;
    const 部件名列表 = 读取斗铠部件槽位列表_桥接(性别文本);
    if (!斗铠.部件 || typeof 斗铠.部件 !== 'object') 斗铠.部件 = {};
    部件名列表.forEach(部件名 => {
      if (!斗铠.部件[部件名]) 斗铠.部件[部件名] = { 状态: '完好', 品质系数: 1.0 };
    });
  }

  function applyTemporaryHumanEquipment(stats, equipment, identity = '魂师', level = 1, rng = Math.random, seed = {}) {
    if (identity === '普通人' || !equipment || typeof equipment !== 'object') return stats;
    const request = seed && typeof seed === 'object' ? seed.装备 || {} : {};
    const mechGrade = String(request?.机甲 || request?.mech || '').trim();
    if (['黄级', '紫级', '黑级', '红级'].includes(mechGrade)) {
      equipment.机甲.等级 = mechGrade;
      equipment.机甲.名称 = `${mechGrade}制式机甲`;
      equipment.机甲.型号 = level >= 70 ? '远程' : '近战';
      equipment.机甲.状态 = '完好';
      equipment.机甲.装备状态 = '未装备';
    }
    const armorLevel = Math.max(0, Math.min(4, Math.floor(Number(request?.斗铠 ?? request?.armor ?? 0))));
    if (armorLevel > 0) {
      equipment.斗铠.等级 = armorLevel;
      equipment.斗铠.名称 = `${armorLevel}字斗铠`;
      equipment.斗铠.装备状态 = '未装备';
      填充临时斗铠部件(equipment.斗铠, toText(seed?.性别 ?? seed?.gender ?? seed?.属性?.性别 ?? request?.性别 ?? request?.gender, ''));
    }
    return stats;
  }

  function getTemporarySoulBeastStats(age = 1, species = '', quality = '', speciesQualityTier = '普通') {
    let level = 1;
    if (age >= 100000) level = 90 + Math.floor((age - 100000) / 100000);
    else if (age >= 10000) level = 50 + Math.floor((age - 10000) / 2250);
    else if (age >= 1000) level = 30 + Math.floor((age - 1000) / 450);
    else if (age >= 100) level = 10 + Math.floor((age - 100) / 45);
    else level = Math.max(1, Math.floor(age / 10));
    const qualityKey = normalizeSoulSpiritQuality(quality);
    level = Math.max(1, level + Number(SOUL_SPIRIT_QUALITY_LEVEL_OFFSET_MAP[qualityKey] || 0));
    const speciesQualityMult = getSoulBeastQualityTierMultiplier(speciesQualityTier);
    const base = getTemporaryBattleBaseStats(level);
    const mult = {
      龙类: { str: 1.5, vit_max: 1.5, def: 1.3, agi: 0.9 },
      蛛类: { agi: 1.6, str: 0.8, def: 0.8 },
      熊类: { str: 1.8, def: 1.5, agi: 0.6 },
      植物系: { vit_max: 2.0, str: 0.7, def: 0.8 },
      海魂兽: { sp_max: 1.3, men_max: 1.2, agi: 1.1 },
      鸟类: { agi: 1.8, str: 0.7, vit_max: 0.8 },
      猫科: { agi: 1.5, str: 1.2, def: 0.9 },
      蛇类: { agi: 1.4, str: 1.0, def: 0.9, men_max: 1.1 },
    }[species] || { str: 1.0, def: 1.0, agi: 1.0, vit_max: 1.0, men_max: 1.0, sp_max: 1.0 };
    const qualityMult = Number(SOUL_SPIRIT_QUALITY_MULTIPLIER_MAP[qualityKey] || 1);
    return {
      对标等级: level,
      str: Math.floor(base.str * (mult.str || 1) * qualityMult * speciesQualityMult),
      def: Math.floor(base.def * (mult.def || 1) * qualityMult * speciesQualityMult),
      agi: Math.floor(base.agi * (mult.agi || 1) * qualityMult * speciesQualityMult),
      vit_max: Math.floor(base.vit_max * (mult.vit_max || 1) * qualityMult * speciesQualityMult),
      men_max: Math.floor(base.men_max * (mult.men_max || 1) * qualityMult * speciesQualityMult),
      sp_max: Math.floor(base.sp_max * (mult.sp_max || 1) * qualityMult * speciesQualityMult),
    };
  }

  function getTemporaryAbyssStats(tier = '', species = '') {
    return withTemporaryBattleRandom(`${tier}|${species}`, rng => {
      let level = 10;
      let mult = { str: 1.0, def: 1.0, agi: 1.0, vit_max: 1.0, men_max: 1.0, sp_max: 1.0 };
      if (tier === '低阶生物') {
        level = 20 + Math.floor(rng() * 20);
        mult = { str: 0.8, def: 0.8, agi: 1.2, vit_max: 0.8, men_max: 0.5, sp_max: 1.0 };
      } else if (tier === '中阶生物') {
        level = 40 + Math.floor(rng() * 30);
        mult = { str: 1.2, def: 1.2, agi: 1.0, vit_max: 1.2, men_max: 0.8, sp_max: 1.2 };
      } else if (tier === '高阶生物') {
        level = 70 + Math.floor(rng() * 20);
        mult = { str: 1.5, def: 1.5, agi: 1.5, vit_max: 1.5, men_max: 1.2, sp_max: 1.5 };
      } else if (tier === '深渊王者' || tier === '深渊帝君') {
        level = 99;
        mult = { str: 2.0, def: 2.0, agi: 2.0, vit_max: 2.0, men_max: 2.0, sp_max: 2.0 };
      }

      if (species.includes('蝙蝠') || species.includes('魔魅') || species.includes('恶镰')) {
        mult.agi *= 1.5;
        mult.def *= 0.7;
      } else if (species.includes('巴安') || species.includes('天牛') || species.includes('猛犸')) {
        mult.def *= 1.8;
        mult.vit_max *= 1.8;
        mult.agi *= 0.6;
      } else if (species.includes('黑皇')) {
        mult.sp_max *= 1.5;
        mult.men_max *= 1.5;
      }

      const base = getTemporaryBattleBaseStats(level);
      return {
        对标等级: level,
        str: Math.floor(base.str * mult.str),
        def: Math.floor(base.def * mult.def),
        agi: Math.floor(base.agi * mult.agi),
        vit_max: Math.floor(base.vit_max * mult.vit_max),
        men_max: Math.floor(base.men_max * mult.men_max),
        sp_max: Math.floor(base.sp_max * mult.sp_max),
      };
    });
  }

  function inferTemporarySoulBeastCombatType(species = '', stats = {}) {
    const text = String(species || '').trim();
    if (/植物/.test(text)) return '控制系';
    if (/海/.test(text)) return '控制系';
    if (/蛛|鸟|猫|蛇/.test(text)) return '敏攻系';
    if (/熊/.test(text)) return '防御系';
    if (Number(stats?.men_max || 0) > Number(stats?.str || 0) * 1.3) return '控制系';
    if (Number(stats?.agi || 0) > Number(stats?.def || 0) * 1.2) return '敏攻系';
    if (Number(stats?.def || 0) > Number(stats?.agi || 0) * 1.2) return '防御系';
    return '强攻系';
  }

  function inferTemporaryAbyssCombatType(species = '', stats = {}) {
    const text = String(species || '').trim();
    if (/蝙蝠|魔魅|恶镰/.test(text)) return '敏攻系';
    if (/附体魔|黑皇/.test(text)) return '控制系';
    if (/巴安|天牛|猛犸|魔傀/.test(text)) return '防御系';
    if (Number(stats?.men_max || 0) > Number(stats?.str || 0) * 1.3) return '控制系';
    if (Number(stats?.agi || 0) > Number(stats?.def || 0) * 1.2) return '敏攻系';
    if (Number(stats?.def || 0) > Number(stats?.agi || 0) * 1.2) return '防御系';
    return '强攻系';
  }

  function buildTemporaryHumanParticipant(seed = {}, slotName = 'enemy') {
    const identity = String(seed?.身份 || '普通人').trim();
    const quantity = Math.max(1, Math.floor(Number(seed?.数量 || 1)));
    const level = identity === '普通人' ? 0 : Math.max(1, Math.floor(Number(seed?.等级 || 1)));
    const unitName = String(seed?.名称 || seed?.name || slotName || '临时单位').trim() || '临时单位';
    return withTemporaryBattleRandom(`${unitName}|${identity}|${quantity}|${level}|${slotName}`, rng => {
      const next = buildTemporaryBattleSkeleton(unitName, '人类');
      next.身份 = identity;
      next.数量 = quantity;
      if (identity === '普通人') {
        const hpMax = pickTemporaryBattleInt(48, 82, rng);
        const menMax = pickTemporaryBattleInt(8, 16, rng);
        next.属性.等级 = 0;
        next.系别 = '普通人';
        next.属性.HP上限 = hpMax;
        next.属性.HP = hpMax;
        next.属性.体力上限 = hpMax;
        next.属性.体力 = hpMax;
        next.属性.魂力上限 = 0;
        next.属性.魂力 = 0;
        next.属性.精神力上限 = menMax;
        next.属性.精神力 = menMax;
        next.属性.力量 = pickTemporaryBattleInt(6, 10, rng);
        next.属性.防御 = pickTemporaryBattleInt(5, 9, rng);
        next.属性.敏捷 = pickTemporaryBattleInt(6, 10, rng);
        return next;
      }

      const combatType = resolveTemporaryHumanCombatType(identity, rng, seed?.系别 || seed?.type);
      const base = getTemporaryBattleBaseStats(level);
      const typeMult = BATTLE_TEMPORARY_TYPE_MULTIPLIERS[combatType] || BATTLE_TEMPORARY_TYPE_MULTIPLIERS['强攻系'];
      const variance = 0.92 + rng() * 0.16;
      const derived = {
        str: Math.floor(base.str * typeMult.str * variance),
        def: Math.floor(base.def * typeMult.def * variance),
        agi: Math.floor(base.agi * typeMult.agi * variance),
        vit_max: Math.floor(base.vit_max * typeMult.vit_max * variance),
        men_max: Math.floor(base.men_max * typeMult.men_max * variance),
        sp_max: Math.floor(base.sp_max * typeMult.sp_max * variance),
      };
      applyTemporaryHumanEquipment(derived, next.装备, identity, level, rng, seed);
      next.属性.等级 = level;
      next.系别 = combatType;
      next.属性.HP上限 = Math.max(1, derived.vit_max);
      next.属性.HP = next.属性.HP上限;
      next.属性.体力上限 = next.属性.HP上限;
      next.属性.体力 = next.属性.HP上限;
      next.属性.魂力上限 = Math.max(1, derived.sp_max);
      next.属性.魂力 = next.属性.魂力上限;
      next.属性.精神力上限 = Math.max(1, derived.men_max);
      next.属性.精神力 = next.属性.精神力上限;
      next.属性.力量 = Math.max(1, derived.str);
      next.属性.防御 = Math.max(1, derived.def);
      next.属性.敏捷 = Math.max(1, derived.agi);
      next.自创魂技 = buildTemporaryBattleSkillMap(
        estimateTemporaryHumanSkillCount(level),
        buildTemporaryHumanSkillNames(combatType, estimateTemporaryHumanSkillCount(level)),
      );
      return next;
    });
  }

  function resolveBestiaryEntryFromSnapshot(snapshot, entryName = '', fallbackName = '') {
    const names = [entryName, fallbackName].map(name => String(name || '').trim()).filter(Boolean);
    if (!names.length) return null;
    const root = snapshot && snapshot.rootData ? snapshot.rootData : snapshot;
    const bestiary =
      root && root.world && root.world.图鉴 && typeof root.world.图鉴 === 'object' ? root.world.图鉴 : {};
    if (!bestiary || typeof bestiary !== 'object') return null;
    for (const name of names) {
      if (bestiary[name] && typeof bestiary[name] === 'object') return bestiary[name];
    }
    return null;
  }

  function buildTemporarySoulBeastParticipant(seed = {}, slotName = 'enemy', snapshot = null) {
    const unitName = String(seed?.名称 || seed?.name || slotName || '魂兽').trim() || '魂兽';
    const species = String(seed?.标准物种 || '').trim();
    const specificSpecies = String(seed?.具体物种 || seed?.物种 || unitName || species || '').trim();
    const speciesQualityTier = normalizeSoulBeastQualityTier(seed?.物种品质 || '');
    const age = Math.max(1, Math.floor(Number(seed?.年限 || 1)));
    const quantity = Math.max(1, Math.floor(Number(seed?.数量 || 1)));
    const quality = normalizeSoulSpiritQuality(seed?.品质 || '');
    const bestiaryEntry = resolveBestiaryEntryFromSnapshot(snapshot, buildSoulBeastBestiaryKey(age, specificSpecies), specificSpecies);
    const stats = getTemporarySoulBeastStats(age, species, quality, speciesQualityTier);
    const combatType = inferTemporarySoulBeastCombatType(species, stats);
    const next = buildTemporaryBattleSkeleton(unitName, '魂兽');
    next.数量 = quantity;
    next.年限 = age;
    next.标准物种 = species;
    next.具体物种 = specificSpecies;
    next.物种品质 = speciesQualityTier;
    if (quality) next.品质 = quality;
    next.系别 = combatType;
    next.属性.年龄 = age;
    next.属性.等级 = Number(stats.对标等级 || 1);
    next.属性.HP上限 = Math.max(1, Number(stats.vit_max || 1));
    next.属性.HP = next.属性.HP上限;
    next.属性.体力上限 = next.属性.HP上限;
    next.属性.体力 = next.属性.体力上限;
    next.属性.魂力上限 = Math.max(1, Number(stats.sp_max || 1));
    next.属性.魂力 = next.属性.魂力上限;
    next.属性.精神力上限 = Math.max(1, Number(stats.men_max || 1));
    next.属性.精神力 = next.属性.精神力上限;
    next.属性.力量 = Math.max(1, Number(stats.str || 1));
    next.属性.防御 = Math.max(1, Number(stats.def || 1));
    next.属性.敏捷 = Math.max(1, Number(stats.agi || 1));
    next.社交.势力['魂兽一族'] = { 身份: '敌对', 权限级: 1 };
    next.自创魂技 =
      bestiaryEntry?.标准技能 && typeof bestiaryEntry.标准技能 === 'object' && !Array.isArray(bestiaryEntry.标准技能)
        ? cloneJsonValue(bestiaryEntry.标准技能, {})
        : buildTemporaryBattleSkillMap(
            estimateTemporaryMonsterSkillCount('魂兽', seed),
            buildTemporarySoulBeastSkillNames(species, specificSpecies, estimateTemporaryMonsterSkillCount('魂兽', seed)),
          );
    return next;
  }

  function buildTemporaryAbyssParticipant(seed = {}, slotName = 'enemy') {
    const unitName = String(seed?.名称 || seed?.name || slotName || '深渊生物').trim() || '深渊生物';
    const race = String(seed?.标准种族 || '').trim();
    const tier = String(seed?.级别 || '').trim();
    const quantity = Math.max(1, Math.floor(Number(seed?.数量 || 1)));
    const stats = getTemporaryAbyssStats(tier, race);
    const combatType = inferTemporaryAbyssCombatType(race, stats);
    const next = buildTemporaryBattleSkeleton(unitName, '深渊');
    next.数量 = quantity;
    next.级别 = tier;
    next.标准种族 = race;
    next.系别 = combatType;
    next.属性.等级 = Number(stats.对标等级 || 1);
    next.属性.HP上限 = Math.max(1, Number(stats.vit_max || 1));
    next.属性.HP = next.属性.HP上限;
    next.属性.体力上限 = next.属性.HP上限;
    next.属性.体力 = next.属性.体力上限;
    next.属性.魂力上限 = Math.max(1, Number(stats.sp_max || 1));
    next.属性.魂力 = next.属性.魂力上限;
    next.属性.精神力上限 = Math.max(1, Number(stats.men_max || 1));
    next.属性.精神力 = next.属性.精神力上限;
    next.属性.力量 = Math.max(1, Number(stats.str || 1));
    next.属性.防御 = Math.max(1, Number(stats.def || 1));
    next.属性.敏捷 = Math.max(1, Number(stats.agi || 1));
    next.社交.势力['深渊生物'] = { 身份: '敌对', 权限级: 1 };
    next.自创魂技 = buildTemporaryBattleSkillMap(
      estimateTemporaryMonsterSkillCount('深渊', seed),
      buildTemporaryAbyssSkillNames(race, estimateTemporaryMonsterSkillCount('深渊', seed)),
    );
    return next;
  }

  function buildExpandedBattleSeedParticipant(snapshot, participant = null, slotKey = 'enemy') {
    if (!participant || typeof participant !== 'object' || Array.isArray(participant)) return null;
    if (isExpandedBattleParticipant(participant)) return cloneJsonValue(participant, {});
    const participantName = String(participant.name || '').trim();
    const charKey = resolveSnapshotCharKey(snapshot, participantName);
    if (charKey) {
      return 应用已有参战者种子实力封顶(
        snapshot,
        charKey,
        buildCombatParticipantFromSnapshotChar(snapshot, charKey, String(slotKey || '').includes('team_player') ? '己方' : '敌对'),
        participant,
      );
    }
    const unitNature = String(participant.单位性质 || '').trim();
    if (unitNature === '人类') return buildTemporaryHumanParticipant(participant, slotKey);
    if (unitNature === '魂兽') return buildTemporarySoulBeastParticipant(participant, slotKey, snapshot);
    if (unitNature === '深渊') return buildTemporaryAbyssParticipant(participant, slotKey);
    return cloneJsonValue(participant, {});
  }

  function explodeBattleSeedParticipant(snapshot, participant = null, slotKey = 'enemy') {
    const expanded = buildExpandedBattleSeedParticipant(snapshot, participant, slotKey);
    if (!expanded) return [];
    if (isExpandedBattleParticipant(expanded) && String(expanded.来源 || '').trim() !== '临时单位') return [expanded];
    const quantity = Math.max(1, Math.floor(Number(participant?.数量 || expanded?.数量 || 1)));
    if (quantity <= 1) return [expanded];
    const results = [];
    const baseName = String(participant?.name || expanded?.name || slotKey).trim() || slotKey;
    for (let index = 1; index <= quantity; index += 1) {
      const cloneSeed = cloneJsonValue(participant, {});
      const displayName = index === 1 ? baseName : `${baseName}·${index}`;
      cloneSeed.name = displayName;
      cloneSeed.数量 = 1;
      const nextExpanded = buildExpandedBattleSeedParticipant(snapshot, cloneSeed, `${slotKey}_${index}`);
      if (nextExpanded) results.push(nextExpanded);
    }
    return results;
  }

  function expandBattleRosterForSnapshot(snapshot, combatData = {}) {
    const participants = combatData?.参战者 && typeof combatData.参战者 === 'object' ? combatData.参战者 : null;
    if (!participants) return null;
    const nextParticipants = {
      team_player: [],
      team_enemy: [],
    };
    // A stored unit that was out of the battle comes back out of it, for the same reason (compactBattleParticipantForStorage).
    const 保留离场 = (units, seed) => {
      const 原因 = toText(seed?.__战斗失能原因, '').trim();
      if (原因) units.forEach(unit => { if (unit && typeof unit === 'object') unit.__战斗失能原因 = 原因; });
      return units;
    };
    const teamPlayerSeeds = Array.isArray(participants.team_player) ? participants.team_player : [];
    teamPlayerSeeds.forEach((participant, index) => {
      nextParticipants.team_player.push(
        ...保留离场(explodeBattleSeedParticipant(snapshot, participant, `team_player_${index + 1}`), participant),
      );
    });
    const teamEnemySeeds = Array.isArray(participants.team_enemy) ? participants.team_enemy : [];
    teamEnemySeeds.forEach((participant, index) => {
      nextParticipants.team_enemy.push(
        ...保留离场(explodeBattleSeedParticipant(snapshot, participant, `team_enemy_${index + 1}`), participant),
      );
    });

    nextParticipants.team_player.forEach(unit => {
      if (unit && typeof unit === 'object') unit.势力 = '己方';
    });
    nextParticipants.team_enemy.forEach(unit => {
      if (unit && typeof unit === 'object') unit.势力 = '敌对';
    });
    return nextParticipants;
  }

  function validateBattleSeedParticipant(snapshot, seed, role = 'enemy') {
    const normalized = normalizeBattleSeedParticipant(seed);
    if (!normalized) return { ok: false, reason: `${role}_seed_missing_name` };
    const charKey = resolveSnapshotCharKey(snapshot, normalized.name);
    if (charKey) return { ok: true, normalized, charKey, kind: 'char' };

    const unitNature = toText(normalized.单位性质, '');
    if (!unitNature) return { ok: false, reason: `${role}_seed_missing_unit_nature` };
    if (!['人类', '魂兽', '深渊'].includes(unitNature))
      return { ok: false, reason: `${role}_seed_invalid_unit_nature` };

    if (toNumber(normalized.数量, 0) <= 0) return { ok: false, reason: `${role}_seed_missing_quantity` };
    const quantity = Math.max(1, Math.floor(toNumber(normalized.数量, 1)));
    normalized.数量 = quantity;

    if (unitNature === '人类') {
      let identity = toText(normalized.身份, '');
      const levelValue = Math.max(0, Math.floor(toNumber(normalized.等级, 0)));
      if (!identity) identity = levelValue > 0 ? '魂师' : '普通人';
      if (!['普通人', '魂师', '军人'].includes(identity)) {
        identity = levelValue > 0 ? '魂师' : '普通人';
      }
      normalized.身份 = identity;
      if (identity !== '普通人') {
        if (levelValue <= 0) return { ok: false, reason: `${role}_seed_missing_level` };
        normalized.等级 = levelValue;
      } else {
        normalized.等级 = 0;
      }
    } else if (unitNature === '魂兽') {
      const levelValue = Math.max(1, Math.floor(toNumber(normalized.等级, 1)));
      normalized.等级 = levelValue;
      if (toNumber(normalized.年限, 0) <= 0) normalized.年限 = 按模块路由等级换算魂兽年限(levelValue);
      const species = toText(normalized.标准物种, '') || 推断模块路由魂兽标准物种(normalized.name);
      normalized.标准物种 = BATTLE_SOUL_BEAST_STANDARD_SPECIES.includes(species)
        ? species
        : 推断模块路由魂兽标准物种(species || normalized.name);
      normalized.具体物种 = toText(normalized.具体物种 || normalized.物种, '') || toText(normalized.name, '') || normalized.标准物种;
      normalized.物种品质 = normalizeSoulBeastQualityTier(normalized.物种品质 || normalized.品质 || '');
      if (normalized.品质 !== undefined) {
        const quality = normalizeSoulSpiritQuality(normalized.品质 || '');
        normalized.品质 = quality || '';
      }
    } else if (unitNature === '深渊') {
      const levelValue = Math.max(1, Math.floor(toNumber(normalized.等级, 1)));
      normalized.等级 = levelValue;
      if (!toText(normalized.级别, '').trim()) normalized.级别 = 按模块路由等级换算深渊级别(levelValue);
      const race = toText(normalized.标准种族, '') || 推断模块路由深渊标准种族(normalized.name);
      normalized.标准种族 = BATTLE_ABYSS_STANDARD_RACES.includes(race)
        ? race
        : 推断模块路由深渊标准种族(race || normalized.name);
    }

    return { ok: true, normalized, charKey: '', kind: 'seed' };
  }

  function buildSoulTowerTeamMemberEntry(snapshot, charKey = '', fallbackName = '') {
    const safeKey = toText(charKey, '').trim();
    const charData = safeKey ? deepGet(snapshot, ['rootData', 'char', safeKey], null) : null;
    let ageValue = getSoulTowerAgeValueFromCharacter(charData || {});
    if (!(Number.isFinite(ageValue) && ageValue > 0)) {
      const activeName = toText(snapshot && snapshot.activeName, '').trim();
      if (safeKey && activeName && safeKey === activeName) {
        ageValue = getSoulTowerAgeValueFromCharacter(deepGet(snapshot, 'activeChar', {}));
      }
    }
    return {
      key: safeKey,
      name: toText(deepGet(charData, 'name', ''), fallbackName || safeKey || '队员'),
      age: ageValue,
    };
  }

  function validateSoulTowerRosterFromBattleSeeds(snapshot, activeKey, teamPlayerChecks = []) {
    const memberEntries = [
      buildSoulTowerTeamMemberEntry(snapshot, activeKey, toText(snapshot && snapshot.activeName, '玩家')),
    ];
    if (!memberEntries[0].key) return { ok: false, message: '当前角色未绑定有效档案，无法参与魂灵塔。' };
    for (const itemCheck of Array.isArray(teamPlayerChecks) ? teamPlayerChecks : []) {
      if (!itemCheck || itemCheck.kind !== 'char' || !toText(itemCheck.charKey, '').trim()) {
        return { ok: false, message: '魂灵塔队友必须是已建档角色。' };
      }
      memberEntries.push(
        buildSoulTowerTeamMemberEntry(
          snapshot,
          itemCheck.charKey,
          toText(itemCheck.normalized && itemCheck.normalized.name, '队友'),
        ),
      );
    }
    const unresolvedMember = memberEntries.find(member => !Number.isFinite(member.age) || !(member.age > 0));
    if (unresolvedMember) {
      return { ok: false, message: `${toText(unresolvedMember.name, '队员')} 年龄未记录，无法校验魂灵塔资格。` };
    }
    return buildSoulTowerTeamValidationResult(memberEntries);
  }

  function buildBattleSeedRoster(snapshot, detail = {}) {
    const detailParticipants = detail.参战者 && typeof detail.参战者 === 'object' ? detail.参战者 : null;
    const activeKey = resolveSnapshotCharKey(
      snapshot,
      toText(snapshot && snapshot.activeName, '') || deepGet(snapshot, 'rootData.sys.玩家名', ''),
    );
    if (!snapshot || !snapshot.rootData || !activeKey) return { ok: false, reason: 'player_context_unresolved' };
    const playerChar = buildCombatParticipantFromSnapshotChar(snapshot, activeKey, '己方');
    if (!playerChar) return { ok: false, reason: 'player_context_unresolved' };
    const soulTowerCombat = isSoulTowerCombatType(detail);
    const activeChar = getActiveSnapshotCharacter(snapshot);
    const defaultSoulTowerFloor = Math.min(
      SOUL_TOWER_TOTAL_FLOORS,
      Math.max(1, toNumber(deepGet(activeChar, '魂灵塔记录.最高层', 0), 0) + 1),
    );
    const soulTowerFloor = soulTowerCombat
      ? Math.min(SOUL_TOWER_TOTAL_FLOORS, Math.max(1, Math.floor(toNumber(detail.floor, defaultSoulTowerFloor))))
      : 0;

    if (!detailParticipants) {
      if (soulTowerCombat) {
        const soloCheck = validateSoulTowerRosterFromBattleSeeds(snapshot, activeKey, []);
        if (!soloCheck.ok) return { ok: false, reason: soloCheck.message };
      }
      const npcTargets = Array.isArray(detail.npcTargets)
        ? detail.npcTargets.map(item => toText(item, '').trim()).filter(Boolean)
        : [];
      const npcTarget = toText(detail.npcTarget, '').trim() || (npcTargets.length === 1 ? npcTargets[0] : '');
      const targetKey =
        resolveSnapshotCharKey(snapshot, toText(detail.npcKey, '').trim()) ||
        resolveSnapshotCharKey(snapshot, npcTarget);
      if (targetKey) {
        const enemyChar = buildCombatParticipantFromSnapshotChar(snapshot, targetKey, '敌对');
        if (!enemyChar) return { ok: false, reason: 'combat_context_unresolved' };
        return {
          ok: true,
          participants: {
            team_player: [playerChar],
            team_enemy: [enemyChar],
          },
        };
      }
      if (!soulTowerCombat) return { ok: false, reason: 'combat_context_unresolved' };
      return { ok: false, reason: '魂灵塔 battle 路由缺少正式敌方名称。' };
    }

    const normalizedRoster = {
      team_player: [{ name: playerChar.name }],
      team_enemy: [],
    };

    const teamEnemySeeds = Array.isArray(detailParticipants.team_enemy) ? detailParticipants.team_enemy : [];
    const enemySeed = teamEnemySeeds[0];
    const enemyCheck = validateBattleSeedParticipant(snapshot, enemySeed, 'enemy');
    if (!enemyCheck.ok) return { ok: false, reason: enemyCheck.reason };
    normalizedRoster.team_enemy.push(enemyCheck.kind === 'char' ? { name: enemyCheck.normalized.name } : enemyCheck.normalized);

    const teamPlayerSeeds = Array.isArray(detailParticipants.team_player) ? detailParticipants.team_player : [];
    for (let index = 0; index < teamPlayerSeeds.length; index += 1) {
      const itemCheck = validateBattleSeedParticipant(snapshot, teamPlayerSeeds[index], `team_player_${index}`);
      if (!itemCheck.ok) return { ok: false, reason: itemCheck.reason };
      if (itemCheck.charKey && itemCheck.charKey === activeKey) continue;
      normalizedRoster.team_player.push(
        itemCheck.kind === 'char' ? { name: itemCheck.normalized.name } : itemCheck.normalized,
      );
    }
    if (soulTowerCombat) {
      const towerRosterCheck = validateSoulTowerRosterFromBattleSeeds(
        snapshot,
        activeKey,
        teamPlayerSeeds
          .map((seed, index) => {
            const itemCheck = validateBattleSeedParticipant(snapshot, seed, `team_player_${index}`);
            return itemCheck.ok ? itemCheck : null;
          })
          .filter(Boolean),
      );
      if (!towerRosterCheck.ok) return { ok: false, reason: towerRosterCheck.message };
    }

    const extraTeamEnemySeeds = teamEnemySeeds.slice(1);
    for (let index = 0; index < extraTeamEnemySeeds.length; index += 1) {
      const itemCheck = validateBattleSeedParticipant(snapshot, extraTeamEnemySeeds[index], `team_enemy_${index}`);
      if (!itemCheck.ok) return { ok: false, reason: itemCheck.reason };
      normalizedRoster.team_enemy.push(
        itemCheck.kind === 'char' ? { name: itemCheck.normalized.name } : itemCheck.normalized,
      );
    }

    return { ok: true, participants: normalizedRoster };
  }

  function isExpandedBattleParticipant(participant) {
    return !!(
      participant &&
      typeof participant === 'object' &&
      !Array.isArray(participant) &&
      String(participant.name || '').trim() &&
      participant.属性 &&
      typeof participant.属性 === 'object' &&
      participant.状态 &&
      typeof participant.状态 === 'object'
    );
  }

  function compactBattleParticipantForStorage(snapshot, participant) {
    if (participant === null || participant === undefined) return undefined;
    if (typeof participant === 'string' || typeof participant === 'number') {
      return { name: String(participant) };
    }
    if (typeof participant !== 'object' || Array.isArray(participant)) return undefined;
    const source = cloneJsonValue(participant, {});
    const participantName = toText(source.name, '');
    const resolvedKey = participantName ? resolveSnapshotCharKey(snapshot, participantName) : '';
    // A unit out of the battle stays out when the battle is carried on to the next request, whatever got it out
    // (SUBDUED, INCAPACITATED, UNCONSCIOUS, STAMINA_EXHAUSTED, SURRENDERED, WITHDRAWN …); expandBattleRosterForSnapshot puts it back.
    const 离场原因 = toText(source.__战斗失能原因, '').trim();
    if (resolvedKey) {
      const compact = { name: participantName || resolvedKey };
      if (离场原因) compact.__战斗失能原因 = 离场原因;
      if (source.势力 !== undefined) compact.势力 = toText(source.势力, '');
      const aliveCandidate =
        source.存活 !== undefined
          ? source.存活
          : source.状态 && typeof source.状态 === 'object'
            ? source.状态.存活
            : undefined;
      if (aliveCandidate !== undefined) compact.存活 = aliveCandidate !== false;
      return compact;
    }

    const compact = {};
    if (participantName) {
      compact.name = participantName;
    }
    if (离场原因) compact.__战斗失能原因 = 离场原因;
    ['来源', '单位性质', '身份', '数量', '等级', '年限', '品质', '标准物种', '具体物种', '物种品质', '级别', '标准种族', '势力'].forEach(
      key => {
        if (source[key] !== undefined) compact[key] = cloneJsonValue(source[key], source[key]);
      },
    );
    // A temporary unit that has fought has no save of its own: its live state is kept here, the fields a role gets
    // written back (构建正式战斗写回补丁) plus what it was built with, so the next request takes it up as it is
    // (buildExpandedBattleSeedParticipant takes an expanded entry as it is) instead of building it anew from the seed.
    if (isExpandedBattleParticipant(source)) {
      const attributeSource = source.属性;
      compact.属性 = {};
      战斗提交属性字段.forEach(key => {
        const value = key === '状态效果'
          ? 构建战斗状态集合落盘值(source.状态效果 && typeof source.状态效果 === 'object' ? source.状态效果 : attributeSource.状态效果)
          : attributeSource[key];
        if (value !== undefined) compact.属性[key] = cloneJsonValue(value, value);
      });
      compact.状态 = {};
      战斗提交状态字段.forEach(key => {
        if (source.状态[key] !== undefined) compact.状态[key] = cloneJsonValue(source.状态[key], source.状态[key]);
      });
      ['系别', '自创魂技', '社交', ...战斗提交角色字段].forEach(key => {
        if (source[key] !== undefined) compact[key] = cloneJsonValue(source[key], source[key]);
      });
    }
    const aliveCandidate =
      source.存活 !== undefined
        ? source.存活
        : source.状态 && typeof source.状态 === 'object'
          ? source.状态.存活
          : undefined;
    if (aliveCandidate !== undefined) compact.存活 = aliveCandidate !== false;
    return Object.keys(compact).length ? compact : undefined;
  }

  function compactBattleRosterForStorage(snapshot, participants) {
    if (!participants || typeof participants !== 'object') return null;
    const compact = {
      team_player: Array.isArray(participants.team_player)
        ? participants.team_player.map(item => compactBattleParticipantForStorage(snapshot, item)).filter(Boolean)
        : [],
      team_enemy: Array.isArray(participants.team_enemy)
        ? participants.team_enemy.map(item => compactBattleParticipantForStorage(snapshot, item)).filter(Boolean)
        : [],
    };
    return compact;
  }

  function compactCombatDataForWorldStorage(snapshot, combatData) {
    const source = cloneJsonValue(combatData, {});
    if (!source || typeof source !== 'object') return combatData;
    if (source.参战者 && typeof source.参战者 === 'object') {
      source.参战者 = compactBattleRosterForStorage(snapshot, source.参战者);
    }
    if (source.裁判 !== undefined) {
      const 裁判 = compactBattleRefereeForStorage(snapshot, source.裁判);
      if (裁判) source.裁判 = 裁判;
      else delete source.裁判;
    }
    return source;
  }

  function normalizeCombatForBattleUI(snapshot) {
    const combatData = deepGet(snapshot, 'rootData.world.战斗', {});
    if (!combatData || typeof combatData !== 'object' || !combatData.进行中) return combatData;
    const participants = combatData.参战者 && typeof combatData.参战者 === 'object' ? combatData.参战者 : null;
    if (!participants) return null;
    let nextCombat = combatData;
    const teamPlayer = Array.isArray(participants.team_player) ? participants.team_player : [];
    const teamEnemy = Array.isArray(participants.team_enemy) ? participants.team_enemy : [];
    if (!teamPlayer.every(isExpandedBattleParticipant) || !teamEnemy.every(isExpandedBattleParticipant)) {
      const expandedParticipants = expandBattleRosterForSnapshot(snapshot, combatData);
      if (!expandedParticipants) return null;
      nextCombat = cloneJsonValue(combatData, {});
      nextCombat.参战者 = expandedParticipants;
    }
    if (!Array.isArray(nextCombat.参战者?.team_player) || !Array.isArray(nextCombat.参战者?.team_enemy)) {
      nextCombat = nextCombat === combatData ? cloneJsonValue(combatData, {}) : nextCombat;
      if (!nextCombat.参战者 || typeof nextCombat.参战者 !== 'object') nextCombat.参战者 = {};
      if (!Array.isArray(nextCombat.参战者.team_player)) nextCombat.参战者.team_player = [];
      if (!Array.isArray(nextCombat.参战者.team_enemy)) nextCombat.参战者.team_enemy = [];
    }
    const nextTeamPlayer = nextCombat.参战者.team_player;
    const nextTeamEnemy = nextCombat.参战者.team_enemy;
    if (!nextTeamPlayer.length || !nextTeamEnemy.length) return null;
    // 接战链 阶段三: a referee that is a role of the save comes in with its battle data, as the fighters do.
    const expandedReferee = expandBattleRefereeForSnapshot(snapshot, nextCombat.裁判);
    if (expandedReferee) {
      nextCombat = nextCombat === combatData ? cloneJsonValue(combatData, {}) : nextCombat;
      nextCombat.裁判 = expandedReferee;
    }
    if (!nextTeamPlayer.every(isExpandedBattleParticipant) || !nextTeamEnemy.every(isExpandedBattleParticipant)) return null;
    const worldTick = deepGet(snapshot, 'rootData.world.时间.tick', undefined);
    if (worldTick !== undefined) {
      const currentTick = Number(worldTick);
      if (!Number.isFinite(currentTick) || currentTick < 0) return null;
      if (nextCombat.当前世界tick !== currentTick) {
        nextCombat = nextCombat === combatData ? cloneJsonValue(combatData, {}) : nextCombat;
        nextCombat.当前世界tick = currentTick;
      }
    }
    return nextCombat;
  }

  function buildBattleUiSnapshot(snapshot, combatData) {
    if (
      !snapshot ||
      typeof snapshot !== 'object' ||
      !snapshot.rootData ||
      !combatData ||
      typeof combatData !== 'object'
    ) {
      return snapshot;
    }
    if (deepGet(snapshot, 'rootData.world.战斗', null) === combatData) return snapshot;
    const nextSnapshot = cloneJsonValue(snapshot, {});
    if (!nextSnapshot.rootData || typeof nextSnapshot.rootData !== 'object') nextSnapshot.rootData = {};
    if (!nextSnapshot.rootData.world || typeof nextSnapshot.rootData.world !== 'object')
      nextSnapshot.rootData.world = {};
    nextSnapshot.rootData.world.战斗 = combatData;
    return nextSnapshot;
  }

  function syncBattleUiForSnapshot(snapshot, options = {}) {
    const liveCombatData = normalizeCombatForBattleUI(snapshot);
    const isCombatActive = !!(liveCombatData && liveCombatData.进行中);
    const canUseBattle = isCombatActive && isSnapshotPlayerControlled(snapshot);
    const battleUiSnapshot = canUseBattle ? buildBattleUiSnapshot(snapshot, liveCombatData) : snapshot;
    syncBattleReturnEntries(snapshot, canUseBattle && battleInlineDismissed);
    if (canUseBattle && 跳过战斗终端自动挂载 && !options.reopenBattle) {
      battleInlineDismissed = false;
      removeBattleReturnEntries();
      if (activeBattleUI && typeof activeBattleUI.destroy === 'function') activeBattleUI.destroy();
      activeBattleUI = null;
      return;
    }
    if (canUseBattle && battleInlineDismissed && !options.reopenBattle) {
      if (activeBattleUI && typeof activeBattleUI.destroy === 'function') activeBattleUI.destroy();
      activeBattleUI = null;
      scheduleBattleReturnEntrySync(snapshot, true);
      return;
    }
    if (canUseBattle) {
      const currentHost = getBattleInlineHost();
      if (
        activeBattleUI &&
        currentHost &&
        activeBattleUI.container === currentHost &&
        typeof activeBattleUI.updateData === 'function'
      ) {
        activeBattleUI.updateData(battleUiSnapshot);
        return;
      }
      if (activeBattleUI && typeof activeBattleUI.destroy === 'function') activeBattleUI.destroy();
      activeBattleUI = null;
      if (pendingBattleInlineMount) return;
      const mountToken = ++battleInlineMountToken;
      pendingBattleInlineMount = openBattleInlineSurface()
        .then(async host => {
          if (!await 确保交互模块已加载('战斗模块', 'mountBattleUI')) return;
          if (mountToken !== battleInlineMountToken) return;
          const latestSnapshot = liveSnapshot || lastRenderableSnapshot || snapshot;
          const latestCombatData = normalizeCombatForBattleUI(latestSnapshot);
          if (!latestCombatData || !latestCombatData.进行中 || !isSnapshotPlayerControlled(latestSnapshot)) return;
          const latestBattleUiSnapshot = buildBattleUiSnapshot(latestSnapshot, latestCombatData);
          if (!host || typeof window.mountBattleUI !== 'function') {
            showUiToast('战斗终端嵌入宿主未就绪，战斗模块未打开。', 'error', 4200);
            return;
          }
          activeBattleUI = window.mountBattleUI(host, latestBattleUiSnapshot, {
            onAction: actionData => {
              dispatchUiAiRequest(actionData.playerInput, actionData.systemPrompt, {
                requestKind: actionData.requestKind,
                patchOps: actionData.patchOps,
              });
            },
          });
        })
        .catch(error => {
          console.error('[DragonUI] Battle inline mount failed', error);
          showUiToast('战斗终端打开失败。', 'error', 4200);
        })
        .finally(() => {
          if (mountToken === battleInlineMountToken) pendingBattleInlineMount = null;
        });
    } else {
      battleInlineMountToken++;
      pendingBattleInlineMount = null;
      battleInlineDismissed = false;
      removeBattleReturnEntries();
      if (activeBattleUI && typeof activeBattleUI.destroy === 'function') activeBattleUI.destroy();
      activeBattleUI = null;
      关闭座舱战斗屏();
      if (getEffectiveUnifiedPreviewKey() === BATTLE_INLINE_PREVIEW_KEY) {
        clearUnifiedInlinePreview();
      }
      if (currentModalPreviewKey === BATTLE_INLINE_PREVIEW_KEY && typeof closeModal === 'function') {
        closeModal();
      }
    }
  }

  // 接战链 阶段三 (用户 2026-11-12："裁判需要接入游戏吧"；"没有填裁判就是没有裁判"; 接战链改造方案-20261112 §3.7): the referee a
  // battle request names (detail.裁判: a role's name, or { 名称, 等级 }) as the seed kept in world.战斗 — a role of the save:
  // { 名称 } (its battle data is the save's, expanded with the fighters: expandBattleRefereeForSnapshot); otherwise a level:
  // { 名称, 等级 } (the runtime gives it that level's base panel and no skill: BattleRuntime prepareBattleReferee). A name that
  // is no role and comes with no level, or nothing given: no referee.
  function 规范化开战裁判_桥接(snapshot, value) {
    const 种子 = 解析模块路由裁判(value);
    if (!种子) return null;
    const 角色键 = 种子.名称 ? resolveSnapshotCharKey(snapshot, 种子.名称) : '';
    if (角色键) return { 名称: toText(deepGet(snapshot, ['rootData', 'char', 角色键, 'name'], ''), 种子.名称).trim() || 种子.名称 };
    if (种子.等级 > 0) return { 名称: 种子.名称 || '裁判', 等级: 种子.等级 };
    console.warn('[LWCS] 裁判既不是存档角色也没有等级，本场按没有裁判处理。', value);
    return null;
  }

  // The referee seed made whole for the battle: a role of the save becomes its battle participant (as a fighter's,
  // 势力 中立), with what this battle already took from it (HP, 魂力, 精神力 and its account, kept in the seed by
  // compactBattleRefereeForStorage). A seed that is no role (a level only) stays as it is.
  function expandBattleRefereeForSnapshot(snapshot, seed = {}) {
    if (!seed || typeof seed !== 'object' || Array.isArray(seed) || isExpandedBattleParticipant(seed)) return null;
    const 名称 = toText(seed.名称 || seed.name, '').trim();
    const 角色键 = 名称 ? resolveSnapshotCharKey(snapshot, 名称) : '';
    if (!角色键) return null;
    const participant = buildCombatParticipantFromSnapshotChar(snapshot, 角色键, '中立');
    if (!participant) return null;
    participant.名称 = 名称;
    ['HP', '魂力', '精神力'].forEach(key => {
      if (!Number.isFinite(Number(seed[key]))) return;
      participant[key] = Number(seed[key]);
      if (participant.属性 && typeof participant.属性 === 'object') participant.属性[key] = Number(seed[key]);
    });
    if (seed.__referee && typeof seed.__referee === 'object') participant.__referee = cloneJsonValue(seed.__referee, {});
    return participant;
  }

  // What world.战斗 keeps of the referee: its seed, and once the battle has run, what it has left of HP, 魂力 and 精神力
  // and its account (BattleRuntime __referee), so a battle settled over several requests carries them on.
  function compactBattleRefereeForStorage(snapshot, referee) {
    if (!referee || typeof referee !== 'object' || Array.isArray(referee)) return undefined;
    const 名称 = toText(referee.名称 || referee.name, '').trim() || '裁判';
    const 角色键 = resolveSnapshotCharKey(snapshot, 名称);
    const 等级 = Math.floor(toNumber(referee.等级 ?? referee.属性?.等级, 0));
    const compact = { 名称, ...(!角色键 && 等级 > 0 ? { 等级 } : {}) };
    if (referee.__refereePrepared === true || isExpandedBattleParticipant(referee)) {
      ['HP', '魂力', '精神力'].forEach(key => {
        const value = Number(referee[key] ?? referee.属性?.[key]);
        if (Number.isFinite(value)) compact[key] = value;
      });
    } else {
      ['HP', '魂力', '精神力'].forEach(key => { if (Number.isFinite(Number(referee[key]))) compact[key] = Number(referee[key]); });
    }
    if (referee.__referee && typeof referee.__referee === 'object') compact.__referee = cloneJsonValue(referee.__referee, {});
    return compact;
  }

  // 战斗类型简化（用户 2026-11-13："擂台战算比赛 另外现在战斗类型有点多和重复，简化一下吧"；"实战和死战感觉区分度不够高？"；
  // 战斗类型简化与比赛判定方案-20261113 及其修订）: a battle request's type as BattlePreview reads it (resolveBattleType: 切磋,
  // 比赛 or 实战, the old names as aliases, the system's own as they are; nothing written, 实战), whether it was the old
  // 死战 (no way out), and the intent that type opens with. Before the battle module is loaded the name stays as written
  // (类型已读 false); buildMapBattleCombatData reads it again once it is.
  function 读取开战战斗类型_桥接(value) {
    const 原文 = toText(value, '').trim();
    const preview = window.__LWCS_BATTLE_PREVIEW__;
    if (!preview || typeof preview.resolveBattleType !== 'function') return { 原文, 类型: 原文, 类型已读: false, 系统: false, 不许撤离: false };
    const resolved = preview.resolveBattleType(原文);
    return { 原文, 类型: preview.battleTypeLabel(原文), 类型已读: true, 系统: resolved.system === true, 不许撤离: resolved.noWithdrawal === true };
  }

  // `胜负条件`: a battle whose conditions name a death opens with 必杀; so does a 生死斗 (比赛 with 允许撤离 否 and no
  // referee) — BattlePreview battleTypeDefaultIntent.
  function 开战缺省战斗意图_桥接(类型, 胜负条件 = null, 允许撤离 = true, 裁判 = null) {
    const preview = window.__LWCS_BATTLE_PREVIEW__;
    return typeof preview?.battleTypeDefaultIntent === 'function'
      ? preview.battleTypeDefaultIntent(类型, 胜负条件, { noWithdrawal: 允许撤离 === false, refereed: !!(裁判 && typeof 裁判 === 'object') })
      : '点到为止';
  }

  function buildMapBattleCombatData(snapshot, dispatchDetail) {
    const detail = dispatchDetail || {};
    const 裁判 = 规范化开战裁判_桥接(snapshot, detail.裁判);
    // 战斗类型简化: the type as written (kept in 战斗类型原文 when it reads otherwise), read as one of three. A battle with a
    // referee is a match, and so is a competition's own bout (发起赛事对局请求_桥接 left its 赛事上下文 in world.战斗); the
    // old 死战 is a real fight with no way out (允许撤离 否). With no intent given, the type's own (the player may change
    // it in the battle terminal).
    const 类型读法 = 读取开战战斗类型_桥接(detail.战斗类型原文 ?? detail.战斗类型);
    const 赛事对局 = !deepGet(snapshot, 'rootData.world.战斗.进行中', false) &&
      !!deepGet(snapshot, 'rootData.world.战斗.赛事上下文', null);
    const 战斗类型 = !类型读法.系统 && (裁判 || 赛事对局) ? '比赛' : 类型读法.类型 || '实战';
    const 写明战斗意图 = toText(detail.战斗意图, '').trim();
    const 允许撤离 = detail.允许撤离 === false || 类型读法.不许撤离 ? false : true;
    const rosterResult = buildBattleSeedRoster(snapshot, detail);
    if (!rosterResult.ok) return { ok: false, reason: rosterResult.reason };
    const arenaName = toText(detail.currentLoc, toText(detail.target, toText(snapshot.currentLoc, '未知地点')));
    const soulTowerCombat = isSoulTowerCombatType(detail);
    const activeChar = getActiveSnapshotCharacter(snapshot);
    const defaultSoulTowerFloor = Math.min(
      SOUL_TOWER_TOTAL_FLOORS,
      Math.max(1, toNumber(deepGet(activeChar, '魂灵塔记录.最高层', 0), 0) + 1),
    );
    const soulTowerFloor = soulTowerCombat
      ? Math.min(SOUL_TOWER_TOTAL_FLOORS, Math.max(1, Math.floor(toNumber(detail.floor, defaultSoulTowerFloor))))
      : 0;
    const soulTowerMeta = soulTowerCombat ? getSoulTowerGateMeta(soulTowerFloor) : null;
    const 胜负条件 = 构建战斗胜负条件(detail, rosterResult.participants, 0);
    if (!胜负条件) return { ok: false, reason: 'battle_objectives_invalid' };
    const contextRuleIds = Array.isArray(detail.动作上下文?.modifiers?.战斗?.临时规则ID)
      ? detail.动作上下文.modifiers.战斗.临时规则ID
      : [];
    const temporaryRuleSource = Array.isArray(detail.临时规则ID)
      ? detail.临时规则ID
      : Array.isArray(detail.temporaryRuleIds)
        ? detail.temporaryRuleIds
        : contextRuleIds;
    return {
      进行中: true,
      战斗类型,
      ...(类型读法.原文 && 类型读法.原文 !== 战斗类型 ? { 战斗类型原文: 类型读法.原文 } : {}),
      战斗意图: 写明战斗意图 || 开战缺省战斗意图_桥接(战斗类型, 胜负条件, 允许撤离, 裁判),
      ...(裁判 ? { 裁判 } : {}),
      先攻: '无',
      允许撤离,
      回合: 0,
      环境: {
        地点: arenaName,
        临时规则ID: Array.from(new Set(
          temporaryRuleSource
            .map(item => toText(item, '').trim())
            .filter(Boolean),
        )),
      },
      裁断结果: '',
      参战者: rosterResult.participants,
      胜负条件,
      source: toText(detail.source, 'map_action'),
      // 赛事对局 (任务卡⑥): the bout's 赛事上下文 goes on with the battle — world.战斗 is replaced at the opening, and
      // 结算赛事战斗_桥接 reads the context from it when the battle is settled.
      ...(赛事对局 ? { 赛事上下文: cloneJsonValue(deepGet(snapshot, 'rootData.world.战斗.赛事上下文', null), null) } : {}),
      ...(soulTowerCombat
        ? {
            floor: soulTowerFloor,
            大关卡: soulTowerMeta.gateIndex,
            大关标签: soulTowerMeta.gateLabel,
            关卡范围: soulTowerMeta.gateRangeLabel,
            关底战: soulTowerMeta.isGateBoss,
          }
        : {}),
      ...(detail.ascension_ticket !== undefined ? { ascension_ticket: toText(detail.ascension_ticket, '') } : {}),
      ...(detail.killed_age !== undefined
        ? { killed_age: Math.max(1, Math.floor(toNumber(detail.killed_age, 1))) }
        : {}),
      ...(detail.party_size !== undefined
        ? { party_size: Math.max(1, Math.floor(toNumber(detail.party_size, 1))) }
        : {}),
      ...(detail.试炼状态 !== undefined ? { 试炼状态: toText(detail.试炼状态, '') } : {}),
      ...(detail.升灵对手类型 !== undefined ? { 升灵对手类型: toText(detail.升灵对手类型, '') } : {}),
      ...(detail.升灵档位百分位 !== undefined
        ? { 升灵档位百分位: Math.max(0, Math.min(1, toNumber(detail.升灵档位百分位, 0))) }
        : {}),
      request: {
        action: '战斗',
        target: arenaName,
        npcTarget: toText(detail.npcTarget, ''),
      },
    };
  }

  async function openMapBattleModule(snapshot, dispatchDetail, options = {}) {
    if (!await 确保交互模块已加载('战斗模块', 'mountBattleUI')) return { ok: false, reason: '战斗模块加载失败。' };
    const contextResult = 读取世界动作上下文_桥接(snapshot, dispatchDetail || {}, 'battle');
    if (!contextResult.ok) {
      return {
        ok: false,
        reason: contextResult.reason || 'world_action_blocked',
        worldContextProjection: 读取世界动作投影_桥接(contextResult.context),
      };
    }
    const contextDetail = {
      ...(dispatchDetail && typeof dispatchDetail === 'object' ? dispatchDetail : {}),
      动作上下文: contextResult.context,
    };
    const trialContext = 读取试炼状态上下文(snapshot);
    const trialBattleDetail = trialContext
      ? buildTrialBattleDispatchDetail(snapshot, contextDetail, trialContext)
      : null;
    const combatData = buildMapBattleCombatData(snapshot, trialBattleDetail || contextDetail);
    if (!combatData || combatData.ok === false)
      return { ok: false, reason: combatData?.reason || 'combat_context_unresolved' };
    if (typeof window.mountBattleUI !== 'function') {
      return { ok: false, reason: '战斗模块加载失败。' };
    }
    const playerName = toText(combatData.参战者.team_player?.[0]?.name, '玩家');
    const enemyName = toText(combatData.参战者.team_enemy?.[0]?.name, '对手');
    const compactCombatData = compactCombatDataForWorldStorage(snapshot, combatData);
    const activeCharKey =
      resolveSnapshotCharKey(snapshot, toText(snapshot.activeName, '')) || toText(snapshot.activeName, '');
    const towerEntryTicketPatches = [];
    if (combatData.战斗类型 === '魂灵塔冲塔') {
      const alreadyConsumedTicket =
        (trialBattleDetail || dispatchDetail) && (trialBattleDetail || dispatchDetail).门票已扣除 === true;
      if (!alreadyConsumedTicket) {
        const towerTicketName = toText(
          (trialBattleDetail || dispatchDetail) &&
            ((trialBattleDetail || dispatchDetail).soulTowerTicket || (trialBattleDetail || dispatchDetail).ticketName),
          '',
        ).trim();
        if (!towerTicketName) return { ok: false, reason: '缺少魂灵塔门票。' };
        const ticketConsumeResult = buildInventoryConsumePatches(snapshot, activeCharKey, towerTicketName, 1);
        if (!ticketConsumeResult.ok) return { ok: false, reason: ticketConsumeResult.reason || '魂灵塔门票不足。' };
        towerEntryTicketPatches.push(...ticketConsumeResult.patchOps);
      }
    }
    const soulTowerText =
      combatData.战斗类型 === '魂灵塔冲塔'
        ? ` ${toText(combatData.大关标签, '魂灵塔')} 第${toNumber(combatData.floor, 1)}层`
        : '';
    battleInlineDismissed = false;
    跳过战斗终端自动挂载 = options.skipUi === true;
    await applyBattlePatchOpsByEditor([
      ...towerEntryTicketPatches,
      { op: 'replace', path: '/world/战斗', value: compactCombatData },
      {
        op: 'replace',
        path: '/sys/系统播报',
        value: `[战斗模块] ${playerName} 向 ${enemyName} 发起${combatData.战斗类型 === '魂灵塔冲塔' ? `魂灵塔挑战${soulTowerText}`
          : combatData.战斗类型 === '切磋' ? '切磋' : `战斗（${toText(combatData.战斗类型, '实战')}）`}，战斗模块已接管。`,
      },
    ]);
    await refreshLiveSnapshot({ force: true, reopenBattle: options.skipUi === true ? false : true });
    if (options.skipUi === true) showUiToast('战斗模块自动结算中。', 'info', 1800);
    else showUiToast('战斗模块已开启。', 'info', 2400);
    return {
      ok: true,
      combatData,
      worldActionContext: contextResult.context,
      worldContextProjection: 读取世界动作投影_桥接(contextResult.context),
    };
  }

  /* 楼层只留一行战果；AI 注入只使用 PLAYER 结构化摘要。 */
  function 构建自动战斗战果标题(执行结果 = {}) {
    const 标题 = toText(执行结果?.reportDto?.battleHeadline, '').trim();
    return 标题 ? `<battle_result>${标题}</battle_result>` : '';
  }

  function 构建自动战斗结构化摘要(执行结果 = {}) {
    const 摘要输入 = 执行结果?.reportDto?.aiStructuredSummary || {};
    return JSON.stringify(摘要输入);
  }

  /* AI 只读取 PLAYER 级结构化摘要；Report 内部因果链不进入 AI 消息。 */
  function 构建自动战斗战报注入(执行结果 = {}) {
    const 摘要 = 构建自动战斗结构化摘要(执行结果);
    return 摘要 ? `<battle_summary>\n${摘要}\n</battle_summary>` : '';
  }

  function 构建战斗事务输入(combatData = {}, options = {}) {
    const battleMode = options.mode === 'multi_round' ? 'multi_round' : 'single_round';
    const runtime = window.__LWCS_BATTLE_RUNTIME__;
    if (!runtime || typeof runtime.ensureCombatRuntime !== 'function') {
      throw new Error('battle_runtime_module_missing');
    }
    const worldTick = deepGet(liveSnapshot || lastRenderableSnapshot || {}, 'rootData.world.时间.tick', undefined);
    if (worldTick !== undefined) {
      const currentTick = Number(worldTick);
      if (!Number.isFinite(currentTick) || currentTick < 0) throw new Error('battle_world_tick_invalid');
      combatData = { ...combatData, 当前世界tick: currentTick };
    }
    const runtimeState = runtime.ensureCombatRuntime(combatData);
    const maxRounds = battleMode === 'multi_round'
      ? Math.max(1, Math.min(20, Math.floor(toNumber(options.rounds || combatData?.胜负条件?.maxRounds, 20))))
      : 1;
    const autoContinueSource = options.autoContinueConfig && typeof options.autoContinueConfig === 'object'
      ? options.autoContinueConfig
      : {};
    const stopDamagePercent = Math.max(0, Math.min(100, toNumber(
      autoContinueSource.stopDamagePercent,
      Number.isFinite(Number(autoContinueSource.stopDamageRatio)) ? Number(autoContinueSource.stopDamageRatio) * 100 : 25,
    )));
    const continueChancePercent = Math.max(0, Math.min(100, toNumber(
      autoContinueSource.continueChancePercent,
      Number.isFinite(Number(autoContinueSource.continueChance)) ? Number(autoContinueSource.continueChance) * 100 : 100,
    )));
    return {
      caseId: toText(options.caseId, 'battle-bridge-formal'),
      seed: Math.max(1, Math.floor(toNumber(runtimeState?.decisionSeed, 1))),
      combatData,
      ...(options.worldActionContext && typeof options.worldActionContext === 'object'
        ? { worldActionContext: options.worldActionContext }
        : {}),
      mode: battleMode,
      executionMode: 规范化战斗提交模式(options.executionMode),
      rounds: maxRounds,
      ...(battleMode === 'multi_round'
        ? {
            settings: {
              maxRounds,
              stopDamagePercent,
              stopDamageRatio: stopDamagePercent / 100,
              continueChancePercent,
              continueChance: continueChancePercent / 100,
            },
          }
        : {}),
      selectedAction: options.actionDeclaration || null,
      battleIntent: {
        mode: toText(options.intentMode || combatData?.战斗意图, '').trim(),
        objectives: cloneJsonValue(combatData?.胜负条件 || {}, {}),
      },
    };
  }

  // 战斗估值可分给后台线程并行（BattleRuntime executeBattleDraftParallel 等，结果与同步版逐项相同；线程包读不到、
  // 设备不适合或 window.__LWCS_BATTLE_PARALLEL_DISABLED__ 为真时自动走同步），所以这里是异步的。
  async function 构建战斗提交包(input = {}) {
    const runtime = window.__LWCS_BATTLE_RUNTIME__;
    const report = window.__LWCS_BATTLE_REPORT__;
    if (
      !runtime ||
      typeof runtime.executeBattleDraft !== 'function' ||
      typeof runtime.executePlayerLockedBattleSettlement !== 'function'
    ) {
      throw new Error('battle_runtime_provider_boundary_missing');
    }
    if (!report || typeof report.build !== 'function' || typeof report.auditProjection !== 'function') {
      throw new Error('battle_report_module_missing');
    }
    const source = cloneJsonValue(input, {});
    delete source.visibilityMode;
    const executionMode = 规范化战斗提交模式(source.executionMode);
    const lockedInput = { ...source, actionDeclaration: source.actionDeclaration || source.selectedAction };
    const draft = executionMode === 'auto'
      ? await (typeof runtime.executeBattleDraftParallel === 'function'
        ? runtime.executeBattleDraftParallel(source) : runtime.executeBattleDraft(source))
      : await (typeof runtime.executePlayerLockedBattleSettlementParallel === 'function'
        ? runtime.executePlayerLockedBattleSettlementParallel(lockedInput) : runtime.executePlayerLockedBattleSettlement(lockedInput));
    const reportDto = report.build({ draft, visibilityMode: 'PLAYER' });
    const reportAudit = report.auditProjection(reportDto);
    const sealedPackage = runtime.sealBattleResult({ draft, reportAudit });
    return runtime.verifySealedBattlePackage(sealedPackage);
  }

  const 战斗提交属性字段 = Object.freeze([
    '年龄',
    '等级',
    '天赋梯队',
    '邪魂师',
    'HP',
    'HP上限',
    '魂力',
    '魂力上限',
    '精神力',
    '精神力上限',
    '力量',
    '防御',
    '敏捷',
    '体力',
    '体力上限',
    '状态效果',
  ]);
  const 战斗提交状态字段 = Object.freeze([
    '存活',
    '死亡tick',
    '死亡类型',
    '受伤部位',
    '行动',
    '当前领域',
    '位置',
    '横坐标',
    '纵坐标',
  ]);
  const 战斗提交角色字段 = Object.freeze(['决策记忆', '血脉之力', '复制效果', '装备', '背包']);
  const 战斗状态倍率运行键映射 = Object.freeze({
    str: '力量',
    def: '防御',
    agi: '敏捷',
    vit_max: '体力上限',
    sp_max: '魂力上限',
    men_max: '精神力上限',
  });

  function 构建战斗状态落盘值(condition = {}) {
    const source = cloneJsonValue(condition, {});
    const duration = Math.max(0, toNumber(source.持续回合 ?? source.duration, 0));
    const ratio = {};
    const fixed = {};
    Object.entries(source.面板修改比例 || {}).forEach(([key, value]) => {
      const schemaKey = 战斗状态倍率运行键映射[key] || key;
      const parsed = Number(value);
      if (Number.isFinite(parsed)) ratio[schemaKey] = parsed;
    });
    Object.entries(source.面板倍率 || {}).forEach(([key, value]) => {
      const parsed = Number(value);
      if (Number.isFinite(parsed)) ratio[key] = parsed;
    });
    Object.entries(source.面板固定修正 || {}).forEach(([key, value]) => {
      const schemaKey = 战斗状态倍率运行键映射[key] || key;
      const parsed = Number(value);
      if (Number.isFinite(parsed) && Math.abs(parsed) >= 0.0001) fixed[schemaKey] = parsed;
    });
    Object.entries(source.面板固定值 || {}).forEach(([key, value]) => {
      const parsed = Number(value);
      if (Number.isFinite(parsed) && Math.abs(parsed) >= 0.0001) fixed[key] = parsed;
    });
    const persisted = {
      ...source,
      类型: toText(source.类型, 'buff') || 'buff',
      层数: Math.max(1, Math.floor(toNumber(source.层数, 1))),
      描述: toText(source.描述, '无') || '无',
      持续回合: duration,
      面板倍率: ratio,
      面板固定值: fixed,
      战斗效果: cloneJsonValue(source.战斗效果 || {}, {}),
    };
    delete persisted.duration;
    delete persisted.面板修改比例;
    delete persisted.面板固定修正;
    delete persisted.__previewApplicationProbability;
    return persisted;
  }

  function 构建战斗状态集合落盘值(conditionMap) {
    if (!conditionMap || typeof conditionMap !== 'object' || Array.isArray(conditionMap)) return {};
    return Object.fromEntries(
      Object.entries(conditionMap)
        .filter(([name, condition]) => name && condition && typeof condition === 'object')
        .map(([name, condition]) => [name, 构建战斗状态落盘值(condition)]),
    );
  }

  function 追加战斗提交字段补丁(patchOps, currentRoot, pathSegments, value) {
    if (value === undefined) return;
    const path = `/${pathSegments.map(escapeJsonPointerValue).join('/')}`;
    const previous = deepGet(currentRoot, pathSegments, undefined);
    patchOps.push({
      op: previous === undefined ? 'add' : 'replace',
      path,
      value: cloneJsonValue(value, value),
    });
  }

  function 构建正式战斗写回补丁(finalSnapshot = {}, createdInventoryAssets = [], postBattleCosts = []) {
    if (!finalSnapshot || typeof finalSnapshot !== 'object' || Array.isArray(finalSnapshot)) {
      throw new Error('battle_commit_final_snapshot_invalid');
    }
    const participants = finalSnapshot.参战者;
    if (
      !participants ||
      !Array.isArray(participants.team_player) ||
      !Array.isArray(participants.team_enemy)
    ) {
      throw new Error('battle_commit_final_snapshot_not_persistable');
    }
    const snapshot = liveSnapshot || lastRenderableSnapshot || {};
    const currentRoot = deepGet(snapshot, 'rootData', {});
    const compactCombatData = compactCombatDataForWorldStorage(snapshot, finalSnapshot);
    const patchOps = [{
      op: deepGet(currentRoot, ['world', '战斗'], undefined) === undefined ? 'add' : 'replace',
      path: '/world/战斗',
      value: compactCombatData,
    }];
    const createdByOwner = new Map();
    (Array.isArray(createdInventoryAssets) ? createdInventoryAssets : []).forEach(({ ownerId, assetId }) => {
      if (!ownerId || !assetId) return;
      if (!createdByOwner.has(ownerId)) createdByOwner.set(ownerId, new Set());
      createdByOwner.get(ownerId).add(assetId);
    });
    let itemDraft;
    const addedDefinitions = new Set();

    [...participants.team_player, ...participants.team_enemy].forEach(participant => {
      if (!participant || typeof participant !== 'object') return;
      if (toText(participant.来源, '').trim() === '临时单位') return;
      if (participant.实力压制?.刻意压制等级 === true) return;
      const participantName = toText(participant.name || participant.名称, '').trim();
      const charKey = resolveSnapshotCharKey(snapshot, participantName);
      if (!charKey) return;
      const attributeSource =
        participant.属性 && typeof participant.属性 === 'object' ? participant.属性 : participant;
      const statusSource =
        participant.状态 && typeof participant.状态 === 'object' ? participant.状态 : participant;
      战斗提交属性字段.forEach(key => {
        const value = key === '状态效果'
          ? 构建战斗状态集合落盘值(
              participant.状态效果 && typeof participant.状态效果 === 'object'
                ? participant.状态效果
                : attributeSource.状态效果,
            )
          : attributeSource[key];
        追加战斗提交字段补丁(
          patchOps,
          currentRoot,
          ['char', charKey, '属性', key],
          value,
        );
      });
      战斗提交状态字段.forEach(key => {
        追加战斗提交字段补丁(
          patchOps,
          currentRoot,
          ['char', charKey, '状态', key],
          statusSource[key],
        );
      });
      战斗提交角色字段.forEach(key => {
        追加战斗提交字段补丁(
          patchOps,
          currentRoot,
          ['char', charKey, key],
          participant[key],
        );
      });
      const ownerId = toText(participant.id || participant.角色ID || participant.uid || participantName, '').trim();
      (createdByOwner.get(ownerId) || []).forEach(assetId => {
        const item = participant.背包?.[assetId];
        if (!item || 读取背包总数量_桥接(item) <= 0) return;
        if (!Array.isArray(item.使用效果) || !item.使用效果.length) {
          throw new Error(`battle_created_item_definition_missing:${assetId}`);
        }
        const definition = 构建物品定义记录_桥接(assetId, {
          ...item,
          名称: toText(item.name || item.名称 || item.物品名, assetId),
        }, '魂技造物');
        itemDraft ||= { 物品: cloneJsonValue(currentRoot.物品, {}) };
        const existing = 查找物品定义_桥接(itemDraft, assetId);
        if (existing) {
          const previous = 构建物品定义记录_桥接(assetId, existing.定义, existing.分类);
          const useSemantics = value => [value.使用效果 || [], value.副作用列表 || [], value.使用后消耗 !== false,
            value.基础使用次数 || 0, value.使用次数恢复周期 || ''];
          if (existing.分类 !== '魂技造物' ||
            稳定序列化技能设计台效果(useSemantics(previous)) !== 稳定序列化技能设计台效果(useSemantics(definition))
          ) throw new Error(`battle_created_item_definition_conflict:${assetId}`);
          return;
        }
        写入分类物品定义_桥接(itemDraft, assetId, definition, '魂技造物');
        addedDefinitions.add(assetId);
      });
    });
    // 战后长期代价（用户 2026-11-12）：战斗里触发的本源损耗、重伤昏迷在这里落到角色身上。
    // 本源损耗 N% → 等级上限永久降低 N 级（属性.等级惩罚，与「灵物反噬」「生命之火熄灭」同一个字段，高阶灵物可修复），并留一条常驻说明；
    // 重伤昏迷 M 个月 → 状态「重伤昏迷」，时限 M × 30 天（每天 144 tick）。临时单位、刻意压制等级的参战者与上面一样不写回。
    const 长期代价按角色 = new Map();
    (Array.isArray(postBattleCosts) ? postBattleCosts : []).forEach(cost => {
      const 单位ID = toText(cost?.unitId, '').trim(), 单位名 = toText(cost?.unitName, '').trim();
      const participant = [...participants.team_player, ...participants.team_enemy].find(entry => entry && typeof entry === 'object' && (
        单位ID && [entry.id, entry.角色ID, entry.uid].some(value => toText(value, '').trim() === 单位ID) ||
        [单位名, 单位ID].filter(Boolean).includes(toText(entry.name || entry.名称, '').trim())));
      if (!participant || toText(participant.来源, '').trim() === '临时单位' || participant.实力压制?.刻意压制等级 === true) return;
      const charKey = resolveSnapshotCharKey(snapshot, toText(participant.name || participant.名称, '').trim());
      if (!charKey) return;
      const 数值 = Math.abs(Number(String(cost?.value ?? '').replace(/[+%-]/g, ''))) || 0;
      const 记录 = 长期代价按角色.get(charKey) || { 等级: 0, 月数: 0 };
      if (cost?.type === '本源损耗') 记录.等级 += Math.max(1, Math.round(数值 || 5));
      else if (cost?.type === '重伤昏迷') 记录.月数 += Math.max(0, 数值 || 1);
      else return;
      长期代价按角色.set(charKey, 记录);
    });
    长期代价按角色.forEach((记录, charKey) => {
      const 追加 = (pathSegments, value) => patchOps.push({ op: 'add', path: `/${pathSegments.map(escapeJsonPointerValue).join('/')}`, value });
      if (记录.等级 > 0) {
        const 当前惩罚 = Math.max(0, toNumber(deepGet(currentRoot, ['char', charKey, '属性', '等级惩罚'], 0), 0));
        追加(['char', charKey, '属性', '等级惩罚'], 当前惩罚 + 记录.等级);
        追加(['char', charKey, '属性', '状态效果', '本源损耗'], { 类型: 'debuff', 层数: 记录.等级,
          描述: `本源受损，永久扣除${记录.等级}级等级上限（高阶灵物可修复）` });
      }
      if (记录.月数 > 0) {
        const 持续tick = Math.max(1, Math.round(记录.月数 * 30 * 144));
        const 当前tick = Number(deepGet(snapshot, 'rootData.world.时间.tick', NaN));
        追加(['char', charKey, '属性', '状态效果', '重伤昏迷'], { 类型: 'debuff', 层数: 1, 描述: `战后重伤昏迷${记录.月数}个月`, 持续tick,
          ...(Number.isFinite(当前tick) && 当前tick >= 0 ? { 结束tick: 当前tick + 持续tick } : {}) });
      }
    });
    if (addedDefinitions.size) {
      if (!currentRoot.物品) {
        追加战斗提交字段补丁(patchOps, currentRoot, ['物品'], itemDraft.物品);
      } else if (!currentRoot.物品.魂技造物) {
        追加战斗提交字段补丁(patchOps, currentRoot, ['物品', '魂技造物'], itemDraft.物品.魂技造物);
      } else {
        addedDefinitions.forEach(assetId => 追加战斗提交字段补丁(
          patchOps, currentRoot, ['物品', '魂技造物', assetId], itemDraft.物品.魂技造物[assetId],
        ));
      }
    }
    return patchOps;
  }

  async function 提交战斗包(sealedPackage = {}) {
    const runtime = window.__LWCS_BATTLE_RUNTIME__;
    if (!runtime || typeof runtime.verifySealedBattlePackage !== 'function') {
      throw new Error('battle_runtime_package_verifier_missing');
    }
    const verifiedPackage = runtime.verifySealedBattlePackage(sealedPackage);
    const patchOps = 构建正式战斗写回补丁(verifiedPackage.finalSnapshot, verifiedPackage.createdInventoryAssets, verifiedPackage.postBattleCosts);
    runtime.verifySealedBattlePackage(verifiedPackage);
    await applyBattlePatchOpsByEditor(patchOps, {
      force: true,
      记录本轮模块结算路径: true,
      结算类型: 'battle',
    });
    const receipt = {
      committed: true,
      draftHash: verifiedPackage.draftHash,
      reportHash: verifiedPackage.reportHash,
      patchCount: patchOps.length,
      patchOps,
    };
    window.__LWCS_LAST_BATTLE_COMMIT_RECEIPT__ = receipt;
    return receipt;
  }

  let 正式战斗事务执行中 = false;

  async function 执行战斗事务(combatData = {}, options = {}) {
    const executionMode = 规范化战斗提交模式(options.executionMode || 读取战斗提交模式());
    if (executionMode === 'free_narrative') {
      return {
        skipped: true,
        executionMode,
        reason: 'FREE_NARRATIVE',
      };
    }
    if (!await 确保交互模块已加载('战斗模块', 'mountBattleUI')) throw new Error('BATTLE_MODULE_LOAD_FAILED');
    const shouldCommit = options.dryRun !== true && options.commit !== false;
    if (shouldCommit && 正式战斗事务执行中) throw new Error('BATTLE_TRANSACTION_IN_FLIGHT');
    if (shouldCommit) 正式战斗事务执行中 = true;
    try {
      const transactionInput = 构建战斗事务输入(cloneJsonValue(combatData, {}), { ...options, executionMode });
      const sealedPackage = await 构建战斗提交包(transactionInput);
      if (!shouldCommit) {
        return {
          ...sealedPackage,
          preview: true,
          committed: false,
          executionMode,
        };
      }
      const commitReceipt = await 提交战斗包(sealedPackage);
      return {
        ...sealedPackage,
        preview: false,
        committed: true,
        executionMode,
        commitReceipt,
        winner: toText(sealedPackage?.terminalResult?.winner, 'unfinished'),
        objectiveResolution: sealedPackage.terminalResult,
        finalBattleReport: sealedPackage.reportDto?.finalSummary || null,
        llmBattleSummary: toText(sealedPackage.reportDto?.finalSummary?.text, ''),
      };
    } finally {
      if (shouldCommit) 正式战斗事务执行中 = false;
    }
  }

  const 正式战斗桥接接口 = window.BattleUIBridge || {};
  delete 正式战斗桥接接口.buildBattlePackage;
  delete 正式战斗桥接接口.commitBattlePackage;
  window.BattleUIBridge = Object.assign(正式战斗桥接接口, {
    executeBattleTransaction(combatData = {}, options = {}) {
      return 执行战斗事务(combatData, options);
    },
    getLastBattleCommitReceipt() {
      return window.__LWCS_LAST_BATTLE_COMMIT_RECEIPT__ || null;
    },
  });

  function 战斗类型卷宗文本_桥接(combatData = {}) {
    const preview = window.__LWCS_BATTLE_PREVIEW__;
    const 写的 = toText(combatData.战斗类型, '').trim();
    if (typeof preview?.battleRules !== 'function' || preview.resolveBattleType(写的).system) return 写的;
    const 规则 = preview.battleRules(combatData, { mode: toText(combatData.战斗意图, '').trim() });
    return 规则.match ? '比赛' : 规则.deathMatch ? '比赛（生死斗）' : preview.battleTypeLabel(写的);
  }

  function 构建自动战斗裁断卷宗(combatData = {}, 执行结果 = {}) {
    const 玩家存活 = Math.max(0, toNumber(执行结果.playerAlive, 0));
    const 敌方存活 = Math.max(0, toNumber(执行结果.enemyAlive, 0));
    const 战果类型 =
      执行结果.winner === 'player'
        ? 'player_win'
        : 执行结果.winner === 'enemy'
          ? 'enemy_win'
          : 执行结果.winner === 'draw'
            ? 'draw'
            : 'unfinished';
    const 终局明细 = Array.isArray(执行结果?.objectiveResolution?.matchedDetails) ? 执行结果.objectiveResolution.matchedDetails : [];
    const 终局条件 = [...new Set(终局明细.map(item => toText(item?.condition?.type, '')).filter(Boolean))];
    const 失能单位 = 终局明细.flatMap(item => Array.isArray(item?.unitResults) ? item.unitResults : [])
      .filter(item => item?.matched === true && toText(item?.reason, ''))
      .map(item => ({ 名称: toText(item.unitName || item.unitId, '未知单位'), 原因: toText(item.reason, '') }));
    // 认输与撤离: a battle ended by the battlefield alone (a side with no one left, no condition met — e.g. all of a side
    // withdrew from a fight whose goal was a death) lists the losing side's units out of the fight, as a met condition would.
    const 败方队伍 = 执行结果.winner === 'player' ? 'team_enemy' : 执行结果.winner === 'enemy' ? 'team_player' : '';
    if (!失能单位.length && 败方队伍) {
      (Array.isArray(combatData?.参战者?.[败方队伍]) ? combatData.参战者[败方队伍] : []).forEach(unit => {
        const 原因 = toText(unit?.__战斗失能原因, '').trim();
        if (原因 && !unit?.召唤键) 失能单位.push({ 名称: toText(unit.name || unit.名称, '未知单位'), 原因 });
      });
    }
    const 失能明细 = 失能单位.map(item => `${item.名称}:${item.原因}`);
    // 认输与撤离: a side that left the field by withdrawing (every unit that counts WITHDRAWN) ends as a withdrawal; a
    // concession (SURRENDERED) is out of the fight alive, as incapacitated, its reason in 失能明细.
    const 全员撤离 = 失能单位.length > 0 && 失能单位.every(item => item.原因 === 'WITHDRAWN');
    const 终局类型 = 终局条件.some(type => ['UNIT_DEAD', 'TEAM_DEAD'].includes(type))
      ? 'death'
      : 全员撤离
        ? 'withdrawal'
      : 终局条件.some(type => ['UNIT_INCAPACITATED', 'TEAM_INCAPACITATED'].includes(type)) || (!终局条件.length && 失能单位.length)
        ? 'incapacitated'
        : 终局条件.includes('HP_RATIO_AT_OR_BELOW')
          ? 'hp_threshold'
          : 终局条件.includes('ROUND_REACHED')
            ? 'survived'
            : 终局条件.includes('WITHDRAW_SUCCESS')
              ? 'withdrawal'
              : 战果类型 === 'draw' ? 'time_limit' : 'unfinished';
    const 战果说明 =
      战果类型 === 'player_win'
        ? '玩家方取得阶段胜势'
        : 战果类型 === 'enemy_win'
          ? '敌方取得阶段胜势'
          : 战果类型 === 'draw' ? '达到最大回合，双方未分胜负' : '战斗仍在持续';
    return [
      `[前端战果类型]\n${战果类型}`,
      `[前端战果说明]\n${战果说明}`,
      // 战斗类型简化: the battle's type (BattlePreview battleTypeLabel; a battle with a referee is a match — battleRules);
      // the system's own types as they are. How hard it was fought is the intent's line.
      `[战斗类型]\n${战斗类型卷宗文本_桥接(combatData)}`,
      `[存活统计]\n我方存活:${玩家存活}；敌方存活:${敌方存活}`,
      `[战斗意图]\n${toText(combatData.战斗意图, '').trim() || 开战缺省战斗意图_桥接(combatData.战斗类型, combatData.胜负条件, combatData.允许撤离, combatData.裁判)}`,
      ...(combatData.裁判 && typeof combatData.裁判 === 'object'
        ? [`[裁判]\n${toText(combatData.裁判.名称 || combatData.裁判.name, '裁判')}${toNumber(combatData.裁判.属性?.等级 ?? combatData.裁判.等级, 0) > 0
          ? `（${Math.floor(toNumber(combatData.裁判.属性?.等级 ?? combatData.裁判.等级, 0))}级）` : ''}`]
        : []),
      `[终局类型]\n${终局类型}`,
      `[命中条件]\n${终局条件.join('、') || '无'}`,
      `[失能明细]\n${失能明细.join('；') || '无'}`,
    ].join('\n');
  }

  async function 自动执行战斗模块路由(snapshot, request = {}) {
    if (!await 确保交互模块已加载('战斗模块', 'mountBattleUI')) return { ok: false, reason: '战斗模块加载失败。' };
    let 开启结果 = null;
    let 当前快照 = snapshot;
    let 战斗已接管 = deepGet(当前快照, 'rootData.world.战斗.进行中', false) === true;
    if (deepGet(当前快照, 'rootData.world.战斗.进行中', false)) {
      if (typeof window.mountBattleUI !== 'function') {
        return { ok: false, reason: '战斗模块加载失败。', 已接管: 战斗已接管 };
      }
    } else {
      开启结果 = await openMapBattleModule(当前快照, request, { skipUi: true });
      if (!开启结果?.ok && 开启结果?.reason === 'combat_context_unresolved') {
        await refreshLiveSnapshot({ force: true });
        当前快照 = liveSnapshot || lastRenderableSnapshot || 当前快照;
        开启结果 = await openMapBattleModule(当前快照, request, { skipUi: true });
      }
      if (!开启结果?.ok) return 开启结果 || { ok: false, reason: 'battle_auto_open_failed' };
      战斗已接管 = true;
      当前快照 = liveSnapshot || lastRenderableSnapshot || 当前快照;
    }
    const 原始战斗 = deepGet(当前快照, 'rootData.world.战斗', 开启结果?.combatData || {});
    const 战斗数据 = normalizeCombatForBattleUI(buildBattleUiSnapshot(当前快照, 原始战斗)) || 原始战斗;
    if (!战斗数据 || typeof 战斗数据 !== 'object' || !战斗数据.进行中) {
      return { ok: false, reason: 'battle_context_missing', 已接管: 战斗已接管 };
    }
    const 战斗环境 = 战斗数据.环境 && typeof 战斗数据.环境 === 'object' && !Array.isArray(战斗数据.环境)
      ? 战斗数据.环境
      : {};
    const 环境地点 = toText(战斗环境.地点, toText(当前快照.currentLoc, ''));
    const 环境规则ID = Array.isArray(战斗环境.临时规则ID) ? 战斗环境.临时规则ID : [];
    const 战斗上下文请求 = {
      ...(request && typeof request === 'object' ? request : {}),
      地点: 环境地点,
      临时规则ID: 环境规则ID,
    };
    delete 战斗上下文请求.动作上下文;
    const 战斗上下文结果 = 读取世界动作上下文_桥接(当前快照, 战斗上下文请求, 'battle');
    if (!战斗上下文结果.ok) {
      return {
        ok: false,
        reason: 战斗上下文结果.reason || 'world_action_blocked',
        已接管: 战斗已接管,
        worldContextProjection: 读取世界动作投影_桥接(战斗上下文结果.context),
      };
    }
    const 执行函数 = window.BattleUIBridge?.executeBattleTransaction;
    if (typeof 执行函数 !== 'function') return { ok: false, reason: 'battle_transaction_unavailable', 已接管: 战斗已接管 };
    自动战斗延后写回次数 += 1;
    let 执行结果 = null;
    try {
      const 请求续推配置 = request?.autoContinueConfig && typeof request.autoContinueConfig === 'object'
        ? request.autoContinueConfig
        : {};
      const 回合上限 = Math.max(1, Math.min(20, Math.floor(toNumber(
        请求续推配置.maxRounds,
        toNumber(战斗数据?.胜负条件?.maxRounds, 20),
      ))));
      const 停推阈值百分比 = Math.max(0, Math.min(100, toNumber(
        请求续推配置.stopDamagePercent,
        Number.isFinite(Number(请求续推配置.stopDamageRatio))
          ? Number(请求续推配置.stopDamageRatio) * 100
          : 25,
      )));
      const 续推概率百分比 = Math.max(0, Math.min(100, toNumber(
        请求续推配置.continueChancePercent,
        Number.isFinite(Number(请求续推配置.continueChance))
          ? Number(请求续推配置.continueChance) * 100
          : 100,
      )));
      执行结果 = await 执行函数(战斗数据, {
        mode: 'multi_round',
        rounds: 回合上限,
        autoContinueConfig: {
          maxRounds: 回合上限,
          stopDamagePercent: 停推阈值百分比,
          stopDamageRatio: 停推阈值百分比 / 100,
          continueChancePercent: 续推概率百分比,
          continueChance: 续推概率百分比 / 100,
        },
        executionMode: 'auto',
        worldActionContext: 战斗上下文结果.context,
      });
    } catch (error) {
      自动战斗延后写回次数 = Math.max(0, 自动战斗延后写回次数 - 1);
      return { ok: false, reason: error && error.message ? error.message : 'battle_auto_engine_failed', 已接管: 战斗已接管 };
    }
    自动战斗延后写回次数 = 0;
    let 提交结果 = null;
    try {
      const 战果标题 = 构建自动战斗战果标题(执行结果);
      const 战报注入 = 构建自动战斗战报注入(执行结果);
      const 裁断卷宗 = 构建自动战斗裁断卷宗(战斗数据, 执行结果);
      const 登记接口 = typeof window.__LWCS_REGISTER_BATTLE_SETTLEMENT_CONTEXT__ === 'function'
        ? window.__LWCS_REGISTER_BATTLE_SETTLEMENT_CONTEXT__
        : null;
      if (登记接口) 登记接口({ 结构化摘要: 战果标题, 裁断卷宗, 来源: 'auto_battle_route' });
      提交结果 = await dispatchUiAiRequest(
        ['自动战斗推进', 战果标题].filter(Boolean).join('\n\n'),
        战报注入,
        {
          requestKind: 'battle_settlement_plot',
          skipActionLock: true,
        },
      );
    } catch (error) {
      return { ok: false, reason: error && error.message ? error.message : 'battle_auto_dispatch_failed', 已接管: 战斗已接管 };
    }
    跳过战斗终端自动挂载 = false;
    return {
      ok: 提交结果?.ok !== false,
      dispatch: 提交结果,
      result: 执行结果,
      combatData: 战斗数据,
      reason: 提交结果?.reason || '',
      已接管: 战斗已接管,
      worldContextProjection: 开启结果?.worldContextProjection || '',
    };
  }

  function buildTradeDispatchFromRequest(snapshot, tradeRequest) {
    const req = tradeRequest && typeof tradeRequest === 'object' ? tradeRequest : {};
    const actionText = toText(req.动作, '');
    let action = 'trade';
    const services = [];
    if (/竞拍|拍卖|auction|bid/i.test(actionText)) {
      action = 'bid';
      services.push('auction');
    } else if (/店铺|采购|购买|shop/i.test(actionText) && !toText(req.对象, '')) {
      action = 'shop';
      services.push('shop');
    } else if (/出售|卖出|sell/i.test(actionText) && !toText(req.对象, '')) {
      action = 'sell';
    }
    return {
      action,
      target: toText(req.目标, toText(snapshot && snapshot.currentLoc, '')),
      currentLoc: toText(snapshot && snapshot.currentLoc, ''),
      npcTarget: toText(req.对象, ''),
      services,
      tradeRequest: cloneJsonValue(req, {}),
    };
  }


  function buildMapInteractDispatchRequest(snapshot, dispatchDetail) {
    const detail = dispatchDetail || {};
    const action = toText(detail.action, '');
    let npcTarget = toText(detail.npcTarget, '');
    const npcTargets = Array.isArray(detail.npcTargets)
      ? detail.npcTargets.map(item => toText(item, '')).filter(Boolean)
      : [];
    if (!npcTarget && npcTargets.length) npcTarget = npcTargets[0];

    const interactActionMap = {
      talk: '闲聊',
      brief: '请教',
      intel: '请教',
      ask: '请教',
      gift: '送礼',
      confess: '表白',
      dual: '双修',
    };
    const interactAction = toText(interactActionMap[action], '');
    if (!snapshot || !snapshot.rootData || !npcTarget || !interactAction) return null;

    const activeKey = resolveSnapshotCharKey(snapshot, toText(snapshot.activeName, ''));
    if (!activeKey) return null;

    const chars = deepGet(snapshot, 'rootData.char', {});
    const activeChar = chars && typeof chars === 'object' ? chars[activeKey] || {} : {};
    const activeName = toText(
      activeChar && (activeChar.name || deepGet(activeChar, 'base.name', '')),
      toText(snapshot.activeName, activeKey),
    );
    const resolvedTarget = resolveSnapshotCharacter(snapshot, npcTarget);
    const targetName = toText(resolvedTarget.displayName, npcTarget);
    const relationMap = deepGet(snapshot, 'activeChar.社交.关系', {});
    const relationData =
      relationMap && typeof relationMap === 'object'
        ? relationMap[targetName] || relationMap[resolvedTarget.key] || {}
        : {};
    const arenaName = toText(detail.currentLoc, toText(detail.target, toText(snapshot.currentLoc, '未知地点')));
    const currentTick = toNumber(deepGet(snapshot, 'rootData.world.时间.tick', 0), 0);
    const itemUsed = interactAction === '送礼' ? toText(detail.itemUsed, toText(detail.item_used, '无')) || '无' : '无';
    const targetChar =
      resolvedTarget && resolvedTarget.char && typeof resolvedTarget.char === 'object' ? resolvedTarget.char : {};
    const activeIdentity = toText(deepGet(activeChar, '社交.主身份', '无'), '无');
    const targetIdentity = toText(deepGet(targetChar, '社交.主身份', '无'), '无');
    const activePersonality = toText(deepGet(activeChar, '性格', '未设定'), '未设定');
    const targetPersonality = toText(deepGet(targetChar, '性格', '未设定'), '未设定');
    const activeLoc = toText(deepGet(activeChar, '状态.位置', arenaName), arenaName || '未知地点');
    const targetLoc = toText(deepGet(targetChar, '状态.位置', '未知地点'), '未知地点');
    const activeFactions = Object.keys(deepGet(activeChar, '社交.势力', {})).filter(Boolean);
    const targetFactions = Object.keys(deepGet(targetChar, '社交.势力', {})).filter(Boolean);
    const sourceLabel = toText(detail.sourceLabel, '地图 NPC 互动');
    const actionPromptMap = {
      talk: `我想在【${arenaName}】和【${targetName}】闲聊。`,
      brief: `我想在【${arenaName}】向【${targetName}】汇报情况并请示安排。`,
      intel: `我想在【${arenaName}】向【${targetName}】请教情报。`,
      ask: `我想在【${arenaName}】向【${targetName}】请教修炼心得。`,
      gift:
        itemUsed !== '无'
          ? `我想在【${arenaName}】向【${targetName}】赠送【${itemUsed}】。`
          : `我想在【${arenaName}】向【${targetName}】送礼。`,
      confess: `我想在【${arenaName}】向【${targetName}】表白，明确彼此心意。`,
      dual: `我想在【${arenaName}】与【${targetName}】进行双修。`,
    };

    const relationSummary =
      relationData && typeof relationData === 'object'
        ? `${toText(relationData['关系'], '陌生')} / 好感 ${toNumber(relationData['好感度'], 0)}`
        : '暂无已知关系记录';

    const systemPrompt = `以下内容属于前端代发的${sourceLabel}请求，请直接承接剧情推进，不要输出 JSON 块或变量维护指令。

[社交互动] ${activeName} 在【${arenaName}】对【${targetName}】发起【${interactAction}】。

[关系参考]
当前关系：${relationSummary}

[角色补充]
发起者：${activeName} / 身份 ${activeIdentity} / 性格 ${activePersonality} / 所属势力 ${activeFactions.join(' / ') || '无'} / 所在地 ${activeLoc}
目标：${targetName} / 身份 ${targetIdentity} / 性格 ${targetPersonality} / 所属势力 ${targetFactions.join(' / ') || '无'} / 所在地 ${targetLoc}
预计耗时：${currentTick >= 0 ? '约 2 tick' : '短时互动'}

[互动裁定原则]
请综合考虑当前好感、当前关系称谓、双方性格、身份与现实压力、所属势力带来的立场影响、当前地点是否适合展开该互动。若互动无法成立，请在剧情里自然给出原因。${interactAction === '送礼' ? ` 送礼物品为【${itemUsed}】；请判断这份礼物是否对目标性格、身份、处境与当下气氛对口。` : ''}${interactAction === '表白' ? ' 表白结果必须由当前剧情与人物反应决定，不自动改变关系称谓。' : ''}${interactAction === '双修' ? ' 双修属于高亲密度互动，若人物状态、性格、场景或关系不匹配，应明确写出无法成立的理由。' : ''}${interactAction === '请教' ? ' 请教不仅看好感，也要看目标是否愿意传授、双方当前关系是否适合，以及当下场景是否便于认真交流。' : ''}`;

    return {
      playerInput: actionPromptMap[action] || `我想在【${arenaName}】与【${targetName}】互动。`,
      systemPrompt,
      requestKind: toText(detail.requestKind, 'map_interaction'),
    };
  }

  function extractBracketTokens(text) {
    const tokens = [];
    String(text || '').replace(/【([^】]{1,80})】/g, (_, token) => {
      const value = toText(token, '').trim();
      if (value) tokens.push(value);
      return _;
    });
    return tokens;
  }

  function getSnapshotActiveCharName(snapshot) {
    return resolveEffectivePlayerName(
      deepGet(snapshot, 'rootData', {}),
      toText(snapshot && snapshot.activeName, ''),
    ).trim();
  }

  function schedulePlayerNameRepair(snapshot, forcedPlayerName = '') {
    const rootData = deepGet(snapshot, 'rootData', {});
    if (!rootData || typeof rootData !== 'object') return;
    const currentPlayerName = toText(deepGet(rootData, 'sys.玩家名', ''), '').trim();
    const inferredPlayerName =
      toText(forcedPlayerName, '').trim() ||
      resolveEffectivePlayerName(rootData, toText(snapshot && snapshot.activeName, ''));
    if (!isInvalidRuntimePlayerName(currentPlayerName) && !forcedPlayerName) return;
    if (!inferredPlayerName || isInvalidRuntimePlayerName(inferredPlayerName)) return;
    const inferredChar = deepGet(rootData, ['char', inferredPlayerName], null);
    if (!inferredChar || typeof inferredChar !== 'object') return;
    const repairKey = `${toText(snapshot && snapshot.activeName, '')}::${inferredPlayerName}`;
    if (playerNameRepairInFlight === repairKey) return;
    playerNameRepairInFlight = repairKey;
    Promise.resolve()
      .then(() => replaceStatDataByEditor([{ path: ['sys', '玩家名'], value: inferredPlayerName }]))
      .catch(error => {
        console.warn('[DragonUI] 自动修正玩家名失败。', error);
      })
      .finally(() => {
        if (playerNameRepairInFlight === repairKey) playerNameRepairInFlight = '';
      });
  }

  function resolveDirectIntentCharName(snapshot, rawName) {
    const key = resolveSnapshotCharKey(snapshot, rawName);
    if (!key) return '';
    const charData = deepGet(snapshot, `rootData.char.${key}`, {});
    return toText(charData?.name || deepGet(charData, 'base.name', '') || key, key);
  }

  function findMentionedCharacterName(snapshot, text, options = {}) {
    const activeName = toText(options.activeName, getSnapshotActiveCharName(snapshot));
    const excludedNames = new Set(
      [activeName, ...(options.exclude || [])].map(item => toText(item, '').trim()).filter(Boolean),
    );
    const tokens = extractBracketTokens(text);
    for (let index = tokens.length - 1; index >= 0; index -= 1) {
      const resolvedName = resolveDirectIntentCharName(snapshot, tokens[index]);
      if (resolvedName && !excludedNames.has(resolvedName)) return resolvedName;
    }

    const chars = deepGet(snapshot, 'rootData.char', {});
    const candidates = Object.entries(chars && typeof chars === 'object' ? chars : {})
      .flatMap(([key, charData]) =>
        [toText(charData?.name, ''), toText(deepGet(charData, 'base.name', ''), ''), toText(key, '')].filter(Boolean),
      )
      .filter((name, index, list) => list.indexOf(name) === index && !excludedNames.has(name))
      .sort((a, b) => b.length - a.length);
    return candidates.find(name => name && String(text || '').includes(name)) || '';
  }

  function findBracketLocationToken(snapshot, text) {
    const tokens = extractBracketTokens(text);
    const currentLoc = toText(snapshot && snapshot.currentLoc, '');
    const normalizedLoc = toText(snapshot && snapshot.normalizedLoc, '');
    for (const token of tokens) {
      if (resolveDirectIntentCharName(snapshot, token)) continue;
      if (token.includes('-') || token === currentLoc || token === normalizedLoc) return token;
    }
    return currentLoc || normalizedLoc || '未知地点';
  }

  function parseDirectIntentCount(text, fallback = 1) {
    const digitMatch = String(text || '').match(
      /(?:数量|买|购买|买入|采购|卖|出售|卖出|竞拍|出价)?\s*(\d{1,4})\s*(?:份|个|件|枚|瓶|株|块|包|张|套)?/,
    );
    if (digitMatch) return Math.max(1, toNumber(digitMatch[1], fallback));
    const map = { 一: 1, 二: 2, 两: 2, 三: 3, 四: 4, 五: 5, 六: 6, 七: 7, 八: 8, 九: 9, 十: 10 };
    const chineseMatch = String(text || '').match(
      /([一二两三四五六七八九十]{1,3})\s*(?:份|个|件|枚|瓶|株|块|包|张|套)/,
    );
    if (!chineseMatch) return fallback;
    const raw = chineseMatch[1];
    if (raw === '十') return 10;
    if (raw.includes('十')) {
      const [tensRaw, onesRaw] = raw.split('十');
      return Math.max(1, (map[tensRaw] || 1) * 10 + (map[onesRaw] || 0));
    }
    return Math.max(1, map[raw] || fallback);
  }

  function normalizeProfessionMode(rawMode) {
    const value = toText(rawMode, '').trim().toLowerCase();
    if (/manufacture|制造|组装|总装|封装/.test(value)) return 'manufacture';
    if (/design|设计|图纸|蓝图/.test(value)) return 'design';
    if (/repair|修理|维修|维护|修复|整备/.test(value)) return 'repair';
    if (/forge|锻造|锻打|融锻|百锻|千锻|灵锻|魂锻|天锻/.test(value)) return 'forge';
    return '';
  }

  function normalizeProfessionActionLabel(mode) {
    return { forge: '锻造', manufacture: '制造', design: '设计', repair: '修理' }[mode] || '副职业操作';
  }

  function parseDirectProfessionTier(文本输入, 子类型输入 = '') {
    const 原文 = toText(文本输入, '');
    const 子类型 = toText(子类型输入, '').trim() || parseDirectProfessionSubtype(原文);
    const 下拉匹配 = 原文.match(/\b(?:mech|armor)-([1-5])\b/i);
    if (下拉匹配) return Math.max(1, Math.min(5, toNumber(下拉匹配[1], 1)));
    const 数字匹配 = 原文.match(/([1-5一二两三四五])\s*(?:阶|级)/);
    const 中文数字 = { 一: 1, 二: 2, 两: 2, 三: 3, 四: 4, 五: 5 };
    if (/mech|机甲/.test(子类型)) {
      if (/红级/.test(原文)) return 4;
      if (/黑级/.test(原文)) return 3;
      if (/紫级/.test(原文)) return 2;
      if (/黄级/.test(原文)) return 1;
      return 数字匹配 ? Math.max(1, Math.min(5, Number(数字匹配[1]) || 中文数字[数字匹配[1]] || 1)) : 1;
    }
    if (/armor|斗铠/.test(子类型)) {
      if (/四字|红级/.test(原文)) return 5;
      if (/三字/.test(原文)) return 4;
      if (/二字/.test(原文)) return 3;
      if (/一字/.test(原文)) return 2;
      return 数字匹配 ? Math.max(1, Math.min(5, Number(数字匹配[1]) || 中文数字[数字匹配[1]] || 1)) : 1;
    }
    if (/天锻|四字/.test(原文)) return 5;
    if (/魂锻|三字|红级/.test(原文)) return 4;
    if (/灵锻|二字|黑级/.test(原文)) return 3;
    if (/千锻|一字|紫级/.test(原文)) return 2;
    if (/黄级/.test(原文)) return 1;
    return 数字匹配 ? Math.max(1, Math.min(5, Number(数字匹配[1]) || 中文数字[数字匹配[1]] || 1)) : 1;
  }

  function parseDirectProfessionSubtype(文本输入) {
    const 原文 = toText(文本输入, '');
    if (/\barmor-\d\b/i.test(原文) || /斗铠|一字|二字|三字|四字/.test(原文)) return 'armor';
    if (/\bmech-\d\b/i.test(原文) || /机甲|黄级|紫级|黑级|红级/.test(原文)) return 'mech';
    return '';
  }

  function findDirectProfessionTarget(snapshot, text, npcName = '') {
    const currentLoc = toText(snapshot && snapshot.currentLoc, '');
    const normalizedLoc = toText(snapshot && snapshot.normalizedLoc, '');
    const tokens = extractBracketTokens(text);
    for (let index = tokens.length - 1; index >= 0; index -= 1) {
      const token = tokens[index];
      if (!token || token === npcName || token === currentLoc || token === normalizedLoc || token.includes('-'))
        continue;
      if (resolveDirectIntentCharName(snapshot, token)) continue;
      return token;
    }
    const match = String(text || '').match(
      /(?:锻造|锻打|制造|组装|设计|绘制|修理|维修|维护|修复|整备)\s*([^，。！？\s]{2,32})/,
    );
    return toText(match && match[1], '').trim();
  }

  function findDirectProfessionMaterials(snapshot, text, targetName = '', npcName = '') {
    const currentLoc = toText(snapshot && snapshot.currentLoc, '');
    const normalizedLoc = toText(snapshot && snapshot.normalizedLoc, '');
    return extractBracketTokens(text).filter(token => {
      if (
        !token ||
        token === targetName ||
        token === npcName ||
        token === currentLoc ||
        token === normalizedLoc ||
        token.includes('-')
      )
        return false;
      return !resolveDirectIntentCharName(snapshot, token);
    });
  }

  function buildProfessionRequestFromObject(snapshot, source) {
    const req = source && typeof source === 'object' ? source : {};
    const mode = normalizeProfessionMode(req.模式 || req.动作 || req.副职业 || req.类型);
    if (!mode) return null;
    const npc = toText(req.对象, '');
    const 目标 = toText(req.目标 || req.产物 || req.物品, '');
    if (!目标) return null;
    const 子类型 = toText(req.子类型 || req.目标类型, '').trim() || parseDirectProfessionSubtype(目标);
    const 显式阶级 = toNumber(req.阶级 || req.等级, 0);
    const 阶级文本 = [
      toText(req.阶级 || req.等级 || '', ''),
      目标,
      子类型,
    ]
      .filter(Boolean)
      .join(' ');
    return {
      模式: mode,
      动作: normalizeProfessionActionLabel(mode),
      目标,
      材料: Array.isArray(req.材料)
        ? req.材料
            .map(item => {
              if (item && typeof item === 'object') {
                return toText(item.名称 || item.name || item.材料 || item.物品, '');
              }
              return toText(item, '');
            })
            .filter(Boolean)
        : req.材料 && typeof req.材料 === 'object'
          ? Object.keys(req.材料).filter(Boolean)
          : toText(req.材料, '')
              .split(/[、,，|/]+/)
              .map(item => item.trim())
              .filter(Boolean),
      数量: Math.max(1, toNumber(req.数量 || req.耗材数量, 1)),
      阶级: 显式阶级 > 0 ? Math.max(1, Math.min(5, Math.floor(显式阶级))) : parseDirectProfessionTier(阶级文本, 子类型),
      子类型,
      对象: npc,
      执行者类型: toText(req.执行者类型 || (npc ? 'private' : ''), ''),
      目标地点: toText(req.目标地点 || req.地点, toText(snapshot && snapshot.currentLoc, '')),
      状态: toText(req.状态, req.自动执行 ? 'ready' : 'pending'),
      自动执行: req.自动执行 === true,
      来源: toText(req.来源, 'module_intent_router'),
    };
  }

  function buildDirectProfessionRequest(snapshot, textOrPlan) {
    if (!snapshot || !snapshot.rootData) return null;
    if (textOrPlan && typeof textOrPlan === 'object') return buildProfessionRequestFromObject(snapshot, textOrPlan);
    const raw = toText(textOrPlan, '').trim();
    if (!raw || raw.startsWith('/') || /<UpdateVariable|<JSONPatch/i.test(raw)) return null;
    const mode = normalizeProfessionMode(raw);
    if (!mode) return null;
    if (
      /(是什么|为什么|怎么|如何|会不会|能不能|如果|假如|规则|机制|说明|解释|讨论|听说|回忆)/.test(raw) &&
      !/(我想|我要|我准备|我打算|现在|直接|开始|发起|委托|办理|用|把|给|帮|自动)/.test(raw)
    ) {
      return null;
    }
    const npc = findMentionedCharacterName(snapshot, raw, { activeName: getSnapshotActiveCharName(snapshot) });
    const target = findDirectProfessionTarget(snapshot, raw, npc);
    if (!target && !/打开|进入|办理|工坊|协会|委托/.test(raw)) return null;
    const materials = findDirectProfessionMaterials(snapshot, raw, target, npc);
    const 子类型 = parseDirectProfessionSubtype(`${raw} ${target}`);
    return {
      模式: mode,
      动作: normalizeProfessionActionLabel(mode),
      目标: target,
      材料: materials,
      数量: parseDirectIntentCount(raw, 1),
      阶级: parseDirectProfessionTier(`${raw} ${target}`, 子类型),
      子类型,
      对象: npc,
      执行者类型: /协会|官方/.test(raw) ? 'official' : npc || /委托|代工|帮/.test(raw) ? 'private' : 'self',
      目标地点: findBracketLocationToken(snapshot, raw),
      状态: /直接|立即|确认|开始|自动|执行/.test(raw) ? 'ready' : 'pending',
      自动执行: /直接|立即|确认|开始|自动|执行/.test(raw),
      来源: 'direct_input_guard',
    };
  }

  function buildCraftDispatchFromRequest(snapshot, professionRequest) {
    const req = professionRequest && typeof professionRequest === 'object' ? professionRequest : {};
    return {
      action: 'craft',
      target: toText(req.目标地点 || req.目标, toText(snapshot && snapshot.currentLoc, '')),
      currentLoc: toText(snapshot && snapshot.currentLoc, ''),
      npcTarget: toText(req.对象, ''),
      executorType: toText(req.执行者类型, toText(req.对象, '') ? 'private' : 'self'),
      services: ['craft'],
      professionRequest: cloneJsonValue(req, {}),
    };
  }

  function 执行交易预填路由(快照, 交易请求) {
    const contextResult = 读取世界动作上下文_桥接(快照, 交易请求 || {}, 'trade');
    if (!contextResult.ok) {
      return 构建模块路由失败结果('trade', 交易请求, contextResult.reason || 'world_action_blocked', {
        worldContextProjection: 读取世界动作投影_桥接(contextResult.context),
      });
    }
    const 待确认请求 = {
      ...cloneJsonValue(交易请求, {}),
      动作上下文: contextResult.context,
      状态: 'pending',
      自动执行: false,
    };
    mapDispatchContext = buildTradeDispatchFromRequest(快照, 待确认请求);
    mapDispatchContext.tradeRequest = 待确认请求;
    打开地图交易面板();
    showUiToast('交易流程已打开，请确认后成交。', 'info', 2200);
    return 构建模块路由成功结果('trade', 待确认请求, {
      dispatchMode: 'pending_confirmation',
      skipped: true,
      reason: 'prefill_only',
      worldContextProjection: 读取世界动作投影_桥接(contextResult.context),
    });
  }

  function normalizeInlineModuleAction(actionData, moduleKind, request) {
    const data = actionData && typeof actionData === 'object' ? actionData : {};
    const playerInput = toText(data.playerInput, '').trim();
    const systemPrompt = toText(data.systemPrompt, '').trim();
    const requestKind = toText(data.requestKind, moduleKind ? `module_${moduleKind}` : 'module_inline');
    const patchOps = Array.isArray(data.patchOps) ? cloneJsonValue(data.patchOps, []) : [];
    if (!playerInput || !systemPrompt) return null;
    return {
      playerInput,
      systemPrompt,
      requestKind,
      patchOps,
      privilegeID: toText(data.privilegeID, '').trim(),
      privilegeCost: Math.max(0, Math.floor(toNumber(data.privilegeCost, 0))),
      交易参数: cloneJsonValue(data.交易参数, {}),
      moduleKind: toText(moduleKind, ''),
      request: cloneJsonValue(request, {}),
    };
  }

  async function captureInlineModuleAction(mountRunner, options = {}) {
    const timeoutMs = Math.max(200, Math.min(3000, toNumber(options.timeoutMs, 1200)));
    const container = document.createElement('div');
    container.className = 'mvu-inline-module-capture';
    container.style.cssText =
      'position:fixed;left:-10000px;top:-10000px;width:1px;height:1px;overflow:hidden;opacity:0;pointer-events:none;';
    let component = null;

    try {
      document.body.appendChild(container);
      const result = await new Promise(resolve => {
        let settled = false;
        const finish = value => {
          if (settled) return;
          settled = true;
          resolve(value);
        };
        const timer = window.setTimeout(() => {
          finish({ ok: false, reason: 'inline_action_timeout' });
        }, timeoutMs);
        const 内联失败 = 详情 => {
          window.clearTimeout(timer);
          const 失败原因 = toText(详情 && 详情.原因 ? 详情.原因 : 详情, '模块校验未通过。');
          finish({ ok: false, reason: 失败原因, detail: 详情 });
        };
        try {
          component = mountRunner(
            container,
            actionData => {
              window.clearTimeout(timer);
              finish({ ok: true, actionData });
            },
            内联失败,
          );
        } catch (error) {
          window.clearTimeout(timer);
          finish({ ok: false, reason: error && error.message ? error.message : 'inline_mount_failed', error });
        }
      });
      if (result && result.ok && result.actionData) return result;
      return {
        ok: false,
        reason: (result && result.reason) || 'inline_action_unavailable',
        error: result && result.error,
        detail: result && result.detail,
      };
    } finally {
      try {
        if (component && typeof component.destroy === 'function') component.destroy();
      } catch (error) {}
      try {
        if (container.parentNode) container.parentNode.removeChild(container);
      } catch (error) {}
    }
  }

  async function buildInlineTradeAction(snapshot, tradeRequest) {
    if (!await 确保交互模块已加载('交易模块', 'mountTradeUI')) return { ok: false, reason: 'trade_ui_unavailable' };
    if (typeof window.mountTradeUI !== 'function') {
      return { ok: false, reason: 'trade_ui_unavailable' };
    }
    const dispatchDetail = buildTradeDispatchFromRequest(snapshot, tradeRequest);
    const launchOptions = buildMapTradeModalOptions(snapshot, dispatchDetail);
    const capture = await captureInlineModuleAction(
      (容器, 完成, 失败) =>
        window.mountTradeUI(容器, snapshot, {
          actionType: launchOptions.actionType,
          initialTab: launchOptions.initialTab,
          prefillNpc: launchOptions.prefillNpc,
          lockNpc: launchOptions.lockNpc,
          preferredStore: launchOptions.preferredStore,
          prefillAction: launchOptions.prefillAction,
          prefillItem: launchOptions.prefillItem,
          prefillQty: launchOptions.prefillQty,
          prefillPrice: launchOptions.prefillPrice,
          prefillBatch: tradeRequest && tradeRequest.批次索引,
          autoExecute: true,
          onTradeAction: 完成,
          内联动作失败: 失败,
        }),
      { timeoutMs: 1400 },
    );
    if (!capture.ok) return capture;
    const inlineAction = normalizeInlineModuleAction(capture.actionData, 'trade', tradeRequest);
    return inlineAction ? { ok: true, inlineAction } : { ok: false, reason: 'trade_action_invalid' };
  }

  function 执行副职业工坊打开路由(快照, 副职业请求) {
    const contextResult = 读取世界动作上下文_桥接(快照, 副职业请求 || {}, 'profession');
    if (!contextResult.ok) {
      return 构建模块路由失败结果('profession', 副职业请求, contextResult.reason || 'world_action_blocked', {
        worldContextProjection: 读取世界动作投影_桥接(contextResult.context),
      });
    }
    const 待确认请求 = {
      ...cloneJsonValue(副职业请求, {}),
      动作上下文: contextResult.context,
      状态: 'pending',
      自动执行: false,
    };
    mapDispatchContext = buildCraftDispatchFromRequest(快照, 待确认请求);
    mapDispatchContext.professionRequest = 待确认请求;
    打开地图工坊面板();
    showUiToast('工坊流程已打开，请确认后执行。', 'info', 2200);
    return 构建模块路由成功结果('profession', 待确认请求, {
      dispatchMode: 'pending_confirmation',
      skipped: true,
      reason: 'prefill_only',
      worldContextProjection: 读取世界动作投影_桥接(contextResult.context),
    });
  }

  function buildTradeRequestFromObject(snapshot, source) {
    const req = source && typeof source === 'object' ? source : {};
    const action = toText(req.动作 || req.模式 || req.类型, '交易');
    const npc = toText(req.对象 || req.目标对象, '');
    const rawItem = req.物品 || req.目标物品 || req.目标;
    const item =
      rawItem && typeof rawItem === 'object'
        ? toText(rawItem.名称 || rawItem.name || rawItem.物品, '')
        : toText(rawItem, '');
    if (!item) return null;
    return {
      动作: action,
      目标: toText(req.目标地点 || req.地点 || req.目标, toText(snapshot && snapshot.currentLoc, '')),
      对象: npc,
      物品: item,
      数量: Math.max(1, toNumber(req.数量, 1)),
      价格: Math.max(0, toNumber(req.价格 || 0, 0)),
      货币: toText(req.货币, /金魂币|金币/.test(toText(req.货币文本 || req.text, '')) ? 'gold_coin' : 'fed_coin'),
      状态: toText(req.状态, req.自动执行 ? 'ready' : 'pending'),
      自动执行: req.自动执行 === true,
      来源: toText(req.来源, 'module_intent_router'),
    };
  }

  function 解析模块路由布尔值(value) {
    const 文本 = toText(value, '').trim();
    if (/^(是|true|yes|y|1|开启|启用|允许)$/i.test(文本)) return true;
    if (/^(否|false|no|n|0|关闭|禁用|不允许)$/i.test(文本)) return false;
    return value;
  }

  function 解析模块路由数值(value) {
    const 文本 = toText(value, '').trim();
    if (!/^-?\d+(?:\.\d+)?$/.test(文本)) return value;
    const 数值 = Number(文本);
    return Number.isFinite(数值) ? 数值 : value;
  }

  const 战斗目标条件字段模式 = '(?:类型|type|作用方|阵营|side|目标|targets?|targetIds|阈值|threshold|目标回合|回合数|回合|rounds?|判定|scope|存活要求|requireActive)';

  function 解析战斗目标条件字段(value) {
    const 文本 = toText(value, '').replace(/\r/g, ' ').trim();
    if (!文本) return {};
    const 字段 = {};
    const 匹配列表 = [...文本.matchAll(new RegExp(`(?:^|[\\s|_,，;；、]+)(${战斗目标条件字段模式})(?:\\s*[=:：_]\\s*|\\s+)`, 'giu'))];
    if (!匹配列表.length) return { 类型: 文本 };
    匹配列表.forEach((匹配, index) => {
      const 字段名 = toText(匹配[1], '').trim();
      const 值起点 = Number(匹配.index || 0) + 匹配[0].length;
      const 值终点 = index + 1 < 匹配列表.length ? Number(匹配列表[index + 1].index || 文本.length) : 文本.length;
      const 字段值 = 文本.slice(值起点, 值终点).replace(/^[\s|_,，;；、]+|[\s|_,，;；、]+$/gu, '').trim();
      if (字段名 && 字段值) 字段[字段名] = 字段值;
    });
    return 字段;
  }

  function 推断战斗目标默认阵营(type = '', group = 'victory') {
    if (['ROUND_REACHED', 'WITHDRAW_SUCCESS'].includes(type)) return group === 'defeat' ? 'ENEMY' : 'PLAYER';
    return group === 'defeat' ? 'PLAYER' : 'ENEMY';
  }

  function 解析战斗目标条件项(value, group = 'victory') {
    const 是对象 = value && typeof value === 'object' && !Array.isArray(value);
    const 文本 = 是对象 ? '' : toText(value, '').trim();
    if (!是对象 && !文本) return null;
    const 字段 = 是对象 ? cloneJsonValue(value, {}) : 解析战斗目标条件字段(文本);
    const 类型文本 = toText(字段.类型 || 字段.type, '').trim();
    const 类型 = /敌方全员死亡|我方全员死亡|全员死亡|TEAM_DEAD/i.test(类型文本)
      ? 'TEAM_DEAD'
      : /敌方全员失能|我方全员失能|全员失能|TEAM_INCAPACITATED/i.test(类型文本)
      ? 'TEAM_INCAPACITATED'
      : /生命阈值|HP_THRESHOLD|HP_RATIO_AT_OR_BELOW/i.test(类型文本)
        ? 'HP_RATIO_AT_OR_BELOW'
        : /坚持回合|生存回合|SURVIVE_ROUNDS|ROUND_REACHED/i.test(类型文本)
          ? 'ROUND_REACHED'
          : /成功撤离|WITHDRAW_SUCCESS/i.test(类型文本)
            ? 'WITHDRAW_SUCCESS'
          : /受伤|UNIT_DAMAGED/i.test(类型文本)
            ? 'UNIT_DAMAGED'
            : /死亡|UNIT_DEAD/i.test(类型文本)
              ? 'UNIT_DEAD'
              : /失能|UNIT_INCAPACITATED/i.test(类型文本)
              ? 'UNIT_INCAPACITATED'
              : '';
    if (!类型) return null;
    const 原始目标 = 字段.目标 ?? 字段.targets ?? 字段.targetIds ?? '';
    const 目标文本 = Array.isArray(原始目标) ? 原始目标.map(item => toText(item, '').trim()).filter(Boolean).join('、') : toText(原始目标, '').trim();
    const 目标阵营 = /敌方|对方|ENEMY/i.test(目标文本) ? 'ENEMY' : /我方|己方|友方|PLAYER|ALLY/i.test(目标文本) ? 'PLAYER' : '';
    const 阵营文本 = toText(字段.作用方 || 字段.阵营 || 字段.side, 目标阵营 || 推断战斗目标默认阵营(类型, group)).trim();
    const side = /敌方|对方|ENEMY/i.test(阵营文本) ? 'ENEMY' : /我方|己方|友方|PLAYER|ALLY/i.test(阵营文本) ? 'PLAYER' : '';
    const 目标名称文本 = 目标文本.replace(/^(?:敌方|对方|我方|己方|友方)\s*/u, '').trim();
    const targetIds = Array.isArray(原始目标)
      ? 原始目标.map(item => toText(item, '').trim()).filter(Boolean)
      : /^(?:全体|全员|任一|任意|ALL|ANY)$/i.test(目标名称文本) || !目标名称文本
        ? []
        : 目标名称文本.split(/[、,，]/u).map(item => item.trim()).filter(Boolean);
    const 阈值文本 = toText(字段.阈值 || 字段.threshold, '').trim();
    const 阈值数值 = Number.parseFloat(阈值文本.replace('%', ''));
    const 回合 = Math.max(0, Math.floor(toNumber(字段.目标回合 || 字段.回合 || 字段.回合数 || 字段.round || 字段.rounds, 0)));
    return {
      type: 类型,
      side,
      targetIds,
      scope: /全部|全体|全员|ALL/i.test(toText(字段.目标要求 || 字段.targetScope || 字段.判定 || 字段.scope, 目标文本)) ? 'ALL' : 'ANY',
      ...(Number.isFinite(阈值数值) ? { threshold: 阈值文本.includes('%') || 阈值数值 > 1 ? 阈值数值 / 100 : 阈值数值 } : {}),
      ...(回合 > 0 ? { round: 回合 } : {}),
      requireActive: !/否|false|无需/i.test(toText(字段.存活要求 || 字段.requireActive, '是')),
    };
  }

  function 拆分战斗目标条件列表(value) {
    if (Array.isArray(value)) return value;
    const 文本 = toText(value, '').trim();
    if (!文本) return [];
    const 类型匹配 = [...文本.matchAll(new RegExp(`(^|[\\s|_,，;；、]+)(?:类型|type)(?=\\s*(?:[=:：_]|\\s))`, 'giu'))];
    if (类型匹配.length <= 1) return [文本];
    const 起点 = 类型匹配.map(匹配 => Number(匹配.index || 0) + toText(匹配[1], '').length);
    return 起点.map((位置, index) => 文本.slice(位置, 起点[index + 1] ?? 文本.length).replace(/^[\s|_,，;；、]+|[\s|_,，;；、]+$/gu, '').trim()).filter(Boolean);
  }

  function 解析战斗目标条件列表(value, group = 'victory') {
    return 拆分战斗目标条件列表(value).map(item => 解析战斗目标条件项(item, group)).filter(Boolean);
  }

  function 归一战斗条件关系(value, fallback = 'ANY') {
    const 文本 = toText(value, '').trim().toUpperCase();
    if (!文本) return fallback;
    if (/^(AND|ALL|全部|同时)$/.test(文本)) return 'ALL';
    if (/^(OR|ANY|任一|任意)$/.test(文本)) return 'ANY';
    return '';
  }

  function 构建战斗胜负条件(detail = {}, participants = {}, currentRound = 0) {
    const existing = detail?.胜负条件 && typeof detail.胜负条件 === 'object' ? cloneJsonValue(detail.胜负条件, {}) : null;
    const victoryConditions = existing?.victory?.conditions || existing?.胜利?.条件 || 解析战斗目标条件列表(detail?.胜利条件, 'victory');
    const defeatConditions = existing?.defeat?.conditions || existing?.失败?.条件 || 解析战斗目标条件列表(detail?.失败条件, 'defeat');
    const explicitContract = !!existing || 战斗条件输入存在(detail?.胜利条件) || 战斗条件输入存在(detail?.失败条件);
    const units = [
      ...(Array.isArray(participants?.team_player) ? participants.team_player : []).filter(Boolean).map(unit => ({ unit, side: 'PLAYER' })),
      ...(Array.isArray(participants?.team_enemy) ? participants.team_enemy : []).filter(Boolean).map(unit => ({ unit, side: 'ENEMY' })),
    ];
    const 查找目标单位 = target => units.find(({ unit }) => [unit?.id, unit?.角色ID, unit?.name, unit?.名称].map(item => toText(item, '').trim()).filter(Boolean).includes(toText(target, '').trim()));
    const allowedTypes = new Set(['TEAM_INCAPACITATED', 'TEAM_DEAD', 'HP_RATIO_AT_OR_BELOW', 'ROUND_REACHED', 'UNIT_DAMAGED', 'UNIT_INCAPACITATED', 'UNIT_DEAD', 'WITHDRAW_SUCCESS']);
    const conditionIsValid = condition => {
      const type = toText(condition?.type || condition?.类型, '').trim();
      if (!allowedTypes.has(type)) return false;
      const side = toText(condition?.side || condition?.阵营, '').trim();
      if (!['PLAYER', 'ENEMY'].includes(side)) return false;
      const targetIds = Array.isArray(condition?.targetIds) ? condition.targetIds.map(item => toText(item, '').trim()).filter(Boolean) : [];
      if (targetIds.some(target => {
        const matched = 查找目标单位(target);
        return !matched || matched.side !== side;
      })) return false;
      if (type === 'HP_RATIO_AT_OR_BELOW') return Number(condition?.threshold ?? condition?.阈值) > 0 && Number(condition?.threshold ?? condition?.阈值) <= 1;
      if (type === 'ROUND_REACHED') return Number(condition?.round ?? condition?.回合 ?? condition?.回合数) > 0;
      if (['UNIT_DAMAGED', 'UNIT_INCAPACITATED', 'UNIT_DEAD'].includes(type)) {
        return targetIds.length > 0;
      }
      return true;
    };
    if (explicitContract && (
      !Array.isArray(victoryConditions) || !victoryConditions.length || victoryConditions.some(condition => !conditionIsValid(condition)) ||
      !Array.isArray(defeatConditions) || !defeatConditions.length || defeatConditions.some(condition => !conditionIsValid(condition))
    )) return null;
    const safeVictory = Array.isArray(victoryConditions) && victoryConditions.length
      ? victoryConditions
      : [{ type: 'TEAM_INCAPACITATED', side: 'ENEMY', targetIds: [], scope: 'ALL' }];
    const safeDefeat = Array.isArray(defeatConditions) && defeatConditions.length
      ? defeatConditions
      : [{ type: 'TEAM_INCAPACITATED', side: 'PLAYER', targetIds: [], scope: 'ALL' }];
    const bindDamageBaselines = condition => {
      const normalized = cloneJsonValue(condition, {});
      if (normalized.type !== 'UNIT_DAMAGED') return normalized;
      const targets = new Set(Array.isArray(normalized.targetIds) ? normalized.targetIds.map(String) : []);
      normalized.baselineHp = Object.fromEntries(units
        .map(entry => entry.unit)
        .filter(unit => !targets.size || targets.has(toText(unit?.id || unit?.角色ID || unit?.name || unit?.名称, '')) || targets.has(toText(unit?.name || unit?.名称, '')))
        .map(unit => {
          const id = toText(unit?.id || unit?.角色ID || unit?.name || unit?.名称, '');
          const hp = Math.max(0, toNumber(unit?.hp ?? unit?.HP ?? unit?.生命 ?? unit?.vit ?? unit?.体力, unit?.hp_max ?? unit?.HP上限 ?? unit?.生命上限 ?? unit?.vit_max ?? unit?.体力上限 ?? 0));
          return [id, hp];
        }).filter(([id]) => id));
      return normalized;
    };
    const maxRounds = Math.max(1, Math.min(20, Math.floor(toNumber(existing?.maxRounds ?? existing?.回合上限 ?? detail?.最大回合 ?? detail?.回合上限, 20))));
    if ([...safeVictory, ...safeDefeat].some(condition => condition?.type === 'ROUND_REACHED' && Number(condition?.round || 0) > maxRounds)) return null;
    const victoryLogicInput = existing?.victory?.logic || existing?.胜利?.逻辑 || detail?.胜利条件关系;
    const defeatLogicInput = existing?.defeat?.logic || existing?.失败?.逻辑 || detail?.失败条件关系;
    const victoryLogic = 归一战斗条件关系(victoryLogicInput, 'ANY');
    const defeatLogic = 归一战斗条件关系(defeatLogicInput, 'ANY');
    if (!victoryLogic || !defeatLogic) return null;
    return {
      version: 1,
      startRound: Math.max(0, Math.floor(toNumber(existing?.startRound ?? existing?.起始回合, currentRound))),
      maxRounds,
      resolutionPriority: toText(existing?.resolutionPriority || existing?.冲突处理, 'DEFEAT_FIRST'),
      victory: { logic: victoryLogic, conditions: safeVictory.map(bindDamageBaselines) },
      defeat: { logic: defeatLogic, conditions: safeDefeat.map(bindDamageBaselines) },
    };
  }

  function 解析模块路由字段值(字段名, value) {
    const 字段 = toText(字段名, '').trim();
    if (/^(允许撤离|自动模式|自动执行|启用|启用地点拟态|拟态修炼)$/u.test(字段)) return 解析模块路由布尔值(value);
    if (/^(数量|阶级|层数|耗时tick|等级|年限|最大回合|回合上限)$/u.test(字段)) return 解析模块路由数值(value);
    return toText(value, '').trim();
  }

  function 读取模块路由等级(value) {
    const 数值 = Number(value);
    if (!Number.isFinite(数值) || 数值 <= 0) return 0;
    return Math.max(1, Math.floor(数值));
  }

  function 按模块路由等级换算魂兽年限(value) {
    const 等级 = 读取模块路由等级(value);
    if (等级 <= 0) return 0;
    if (等级 >= 90) return Math.max(100000, Math.floor(100000 + (等级 - 90) * 100000));
    if (等级 >= 50) return Math.max(10000, Math.floor(10000 + (等级 - 50) * 2250));
    if (等级 >= 30) return Math.max(1000, Math.floor(1000 + (等级 - 30) * 450));
    if (等级 >= 10) return Math.max(100, Math.floor(100 + (等级 - 10) * 45));
    return Math.max(1, 等级 * 10);
  }

  function 按模块路由等级换算深渊级别(value) {
    const 等级 = 读取模块路由等级(value);
    if (等级 <= 0) return '';
    if (等级 >= 90) return '深渊帝君';
    if (等级 >= 70) return '深渊王者';
    if (等级 >= 50) return '高阶生物';
    if (等级 >= 30) return '中阶生物';
    return '低阶生物';
  }

  function 推断模块路由魂兽标准物种(value = '') {
    const 文本 = toText(value, '').trim();
    if (BATTLE_SOUL_BEAST_STANDARD_SPECIES.includes(文本)) return 文本;
    if (/龙|蛟|蜥/.test(文本)) return '龙类';
    if (/蛛|蜘蛛/.test(文本)) return '蛛类';
    if (/熊/.test(文本)) return '熊类';
    if (/草|花|藤|树|木|植物/.test(文本)) return '植物系';
    if (/海|水|鱼|鲨|鲸|龟/.test(文本)) return '海魂兽';
    if (/鸟|鹰|隼|鸦|雀|鹤|凤/.test(文本)) return '鸟类';
    if (/猫|虎|豹|狮|狼|狐|幽冥/.test(文本)) return '猫科';
    if (/蛇|蟒|蚺/.test(文本)) return '蛇类';
    return '猫科';
  }

  function 推断模块路由深渊标准种族(value = '') {
    const 文本 = toText(value, '').trim();
    if (BATTLE_ABYSS_STANDARD_RACES.includes(文本)) return 文本;
    const 命中 = BATTLE_ABYSS_STANDARD_RACES.find(种族 => 文本.includes(种族) || 种族.includes(文本));
    return 命中 || '四爪蝙蝠';
  }

  function 归一化模块路由参战者通用字段(单位) {
    if (!单位 || typeof 单位 !== 'object') return 单位;
    const 单位性质 = toText(单位.单位性质, '').trim();
    const 等级 = 读取模块路由等级(单位.等级);
    const 名称 = toText(单位.name, '').trim();
    const 类型 = toText(单位.类型, '').trim();
    const 亚型 = toText(单位.亚型, '').trim();
    const 品质 = toText(单位.品质, '').trim();
    if (单位性质 === '人类') {
      if (!toText(单位.身份, '').trim()) 单位.身份 = ['普通人', '魂师', '军人'].includes(类型) ? 类型 : 等级 > 0 ? '魂师' : '普通人';
      if (单位.等级 !== undefined) 单位.等级 = 等级;
    } else if (单位性质 === '魂兽') {
      if (toNumber(单位.年限, 0) <= 0 && 等级 > 0) 单位.年限 = 按模块路由等级换算魂兽年限(等级);
      if (!toText(单位.标准物种, '').trim()) 单位.标准物种 = 推断模块路由魂兽标准物种(类型 || 名称);
      if (!toText(单位.具体物种, '').trim()) 单位.具体物种 = 亚型 || 名称 || '魂兽';
      if (!toText(单位.物种品质, '').trim()) 单位.物种品质 = normalizeSoulBeastQualityTier(品质 || '普通');
      if (单位.品质 !== undefined && !normalizeSoulSpiritQuality(单位.品质)) delete 单位.品质;
    } else if (单位性质 === '深渊') {
      if (!toText(单位.级别, '').trim() && 等级 > 0) 单位.级别 = 按模块路由等级换算深渊级别(等级);
      if (!toText(单位.标准种族, '').trim()) 单位.标准种族 = 推断模块路由深渊标准种族(类型 || 名称);
    }
    return 单位;
  }

  function 解析模块路由参战者项(value) {
    const 文本 = toText(value, '').trim();
    if (!文本) return null;
    const 片段列表 = 文本
      .split('|')
      .map(片段 => 片段.trim())
      .filter(Boolean);
    const 单位 = {};
    const 首段 = 片段列表.shift() || '';
    if (/[=:：]/.test(首段)) {
      片段列表.unshift(首段);
    } else {
      单位.name = 首段;
    }
    for (const 片段 of 片段列表) {
      const 匹配 = 片段.match(/^\s*([^=:：]+)\s*[=:：]\s*(.*?)\s*$/u);
      if (!匹配) continue;
      const 字段 = toText(匹配[1], '').trim();
      const 字段值 = 解析模块路由字段值(字段, 匹配[2]);
      if (字段 === '名称' || 字段 === '名字' || /^name$/i.test(字段)) 单位.name = toText(字段值, '');
      else 单位[字段] = 字段值;
    }
    return 单位.name ? 归一化模块路由参战者通用字段(单位) : null;
  }

  function 解析模块路由参战者列表(value) {
    const 文本 = toText(value, '').trim();
    if (!文本) return [];
    const 粗分列表 = /[；;\n]/.test(文本)
      ? 文本.split(/[；;\n]+/u)
      : 文本.includes('|')
        ? [文本]
        : 文本.split(/[、,，]+/u);
    return 粗分列表.map(解析模块路由参战者项).filter(Boolean);
  }

  function 设置模块路由字段(payload, 字段名, value) {
    const 字段 = toText(字段名, '').trim();
    if (!字段) return;
    if (字段 === '我方' || 字段 === '己方') {
      if (!payload.参战者 || typeof payload.参战者 !== 'object') payload.参战者 = {};
      payload.参战者.team_player = 解析模块路由参战者列表(value);
      return;
    }
    if (字段 === '敌方') {
      if (!payload.参战者 || typeof payload.参战者 !== 'object') payload.参战者 = {};
      payload.参战者.team_enemy = 解析模块路由参战者列表(value);
      return;
    }
    if (/^参战者\.(team_player|team_enemy)$/i.test(字段)) {
      const 队伍名 = 字段.match(/^参战者\.(team_player|team_enemy)$/i)[1];
      if (!payload.参战者 || typeof payload.参战者 !== 'object') payload.参战者 = {};
      payload.参战者[队伍名] = 解析模块路由参战者列表(value);
      return;
    }
    const 字段值 = 解析模块路由字段值(字段, value);
    payload[字段] = 字段值;
    if (字段 === '模块') {
      payload.module = 字段值;
      payload.kind = 字段值;
    } else if (字段 === '地点') {
      payload.location = 字段值;
      payload.targetLocation = 字段值;
      payload.目标地点 = payload.目标地点 || 字段值;
    } else if (字段 === '自动模式') {
      payload.自动模式 = 字段值;
    }
  }

  function 解析模块路由字段块(文本) {
    const payload = {};
    let 当前条件字段 = '';
    let 当前条件项 = null;
    String(文本 || '').split(/\r?\n/u).forEach(行文本 => {
      const 条件组匹配 = 行文本.match(/^\s*(胜利条件|失败条件)\s*[:：]\s*(.*?)\s*$/u);
      if (条件组匹配) {
        当前条件字段 = 条件组匹配[1];
        当前条件项 = null;
        const 行内值 = toText(条件组匹配[2], '').trim();
        if (行内值) {
          设置模块路由字段(payload, 当前条件字段, 行内值);
          当前条件字段 = '';
        } else {
          payload[当前条件字段] = [];
        }
        return;
      }
      if (当前条件字段) {
        const 列表项匹配 = 行文本.match(/^\s*[-*]\s*(类型|type)\s*[:：=_]\s*(.*?)\s*$/iu);
        if (列表项匹配) {
          当前条件项 = { [列表项匹配[1]]: toText(列表项匹配[2], '').trim() };
          payload[当前条件字段].push(当前条件项);
          return;
        }
        const 子字段匹配 = 行文本.match(/^\s+(作用方|阵营|side|目标|targets?|targetIds|阈值|threshold|目标回合|回合数|回合|rounds?|目标要求|targetScope|存活要求|requireActive)\s*[:：=_]\s*(.*?)\s*$/iu);
        if (子字段匹配 && 当前条件项) {
          当前条件项[子字段匹配[1]] = toText(子字段匹配[2], '').trim();
          return;
        }
        if (!行文本.trim()) return;
        当前条件字段 = '';
        当前条件项 = null;
      }
      const 匹配 = 行文本.match(/^\s*([^:：]+?)\s*[:：]\s*(.*?)\s*$/u);
      if (!匹配) return;
      设置模块路由字段(payload, 匹配[1], 匹配[2]);
    });
    return Object.keys(payload).length ? payload : null;
  }

  function 解析模块路由字段块列表(文本) {
    const blocks = [];
    let current = [];
    String(文本 || '')
      .split(/\r?\n/u)
      .forEach(行文本 => {
        if (/^\s*模块\s*[:：]/u.test(行文本) && current.length) {
          blocks.push(current.join('\n'));
          current = [];
        }
        if (行文本.trim() || current.length) current.push(行文本);
      });
    if (current.length) blocks.push(current.join('\n'));
    return blocks
      .map(blockText => {
        const payload = 解析模块路由字段块(blockText);
        return payload ? { ...payload, raw: blockText } : null;
      })
      .filter(Boolean);
  }

  // 接战链 阶段三: the referee a module intent names — a role's name, "名称|等级=60", or { 名称, 等级 } — as { 名称, 等级? };
  // nothing given (or 无): null.
  function 解析模块路由裁判(value) {
    if (value === undefined || value === null) return null;
    if (typeof value === 'object' && !Array.isArray(value)) {
      const 名称 = toText(value.名称 || value.name, '').trim(), 等级 = Math.floor(toNumber(value.等级 ?? value.level, 0));
      return 名称 || 等级 > 0 ? { 名称: 名称 || '裁判', ...(等级 > 0 ? { 等级 } : {}) } : null;
    }
    const 文本 = toText(value, '').trim();
    if (!文本 || /^(无|没有|否|none|null)$/i.test(文本)) return null;
    const 单位 = 解析模块路由参战者项(文本);
    if (!单位) return null;
    const 等级 = Math.floor(toNumber(单位.等级, 0));
    return { 名称: toText(单位.name, '裁判').trim() || '裁判', ...(等级 > 0 ? { 等级 } : {}) };
  }

  function 战斗条件输入存在(value) {
    if (Array.isArray(value)) return value.length > 0;
    if (value && typeof value === 'object') return Object.keys(value).length > 0;
    return !!toText(value, '').trim();
  }

  function 克隆战斗条件输入(value) {
    return value && typeof value === 'object' ? cloneJsonValue(value, Array.isArray(value) ? [] : {}) : toText(value, '').trim();
  }

  function 读取模块路由最大回合(payload = {}) {
    return Number(payload?.最大回合 ?? payload?.回合上限);
  }

  function resolveModuleIntentPayload(input) {
    let parsedInput = input;
    if (typeof input === 'string') {
      const routeMatch = input.match(/<module_routing>\s*([\s\S]*?)\s*<\/module_routing>/i);
      if (routeMatch) {
        try {
          parsedInput = JSON.parse(routeMatch[1]);
        } catch (error) {}
        if (typeof parsedInput === 'string') {
          const 字段块列表 = 解析模块路由字段块列表(routeMatch[1]);
          if (字段块列表.length > 1) {
            parsedInput = {
              moduleQueue: 字段块列表.map(item => ({ ...item, text: input })),
              text: input,
              raw: routeMatch[1],
            };
          } else if (字段块列表.length === 1) {
            parsedInput = { ...字段块列表[0], text: input, raw: routeMatch[1] };
          }
        }
      }
    }
    const outerPayload = parsedInput && typeof parsedInput === 'object' ? parsedInput : {};
    const nestedRequest =
      outerPayload.request && typeof outerPayload.request === 'object'
        ? outerPayload.request
        : outerPayload.请求 && typeof outerPayload.请求 === 'object'
          ? outerPayload.请求
          : null;
    const payload = nestedRequest
      ? {
          ...nestedRequest,
          module: outerPayload.module || outerPayload.模块 || nestedRequest.module || nestedRequest.模块,
          kind:
            outerPayload.kind ||
            outerPayload.module ||
            outerPayload.模块 ||
            nestedRequest.kind ||
            nestedRequest.module ||
            nestedRequest.模块,
          type: outerPayload.type || nestedRequest.type,
          action_type: outerPayload.action_type || nestedRequest.action_type,
          自动执行: outerPayload.自动执行 === true || nestedRequest.自动执行 === true,
          autoExecute: outerPayload.autoExecute === true || nestedRequest.autoExecute === true,
          source: outerPayload.source || nestedRequest.source,
        }
      : outerPayload;
    const text =
      typeof parsedInput === 'string'
        ? parsedInput
        : toText(
            outerPayload.text ||
              outerPayload.plan ||
              outerPayload.message ||
              outerPayload.narrative ||
              outerPayload.intent ||
              outerPayload.raw ||
              payload.text ||
              payload.plan ||
              payload.message ||
              payload.narrative ||
              payload.intent ||
              payload.raw,
            '',
          );
    const kind = toText(
      outerPayload.kind ||
        outerPayload.type ||
        outerPayload.module ||
        outerPayload.模块 ||
        outerPayload.action_type ||
        payload.kind ||
        payload.type ||
        payload.module ||
        payload.模块 ||
        payload.action_type ||
        payload.动作,
      '',
    ).toLowerCase();
    return { payload, text, kind };
  }

  function 构建模块路由失败结果(moduleKind = '', request = null, reason = 'module_route_failed', extra = {}) {
    const kind = moduleKind || '';
    const safeReason = toText(reason, 'module_route_failed');
    const publicRequest = request && typeof request === 'object' ? { ...request } : request;
    if (publicRequest && typeof publicRequest === 'object') delete publicRequest.动作上下文;
    if (kind && kind !== '未命中') {
      return {
        handled: true,
        kind,
        request: publicRequest || null,
        reason: safeReason,
        dispatchMode: toText(extra && extra.dispatchMode, 'failed_summary') || 'failed_summary',
        runtimeEvent: 构建模块路由运行事件文本(kind, extra && extra.request ? extra.request : publicRequest, {
          ...extra,
          dispatchMode: toText(extra && extra.dispatchMode, 'failed_summary') || 'failed_summary',
          status: '执行失败',
          reason: safeReason,
        }),
        ...extra,
      };
    }
    return {
      handled: false,
      kind,
      request: publicRequest || null,
      reason: safeReason,
      ...extra,
    };
  }

  function 解析新技能获得模块意图请求(snapshot, payload = {}) {
    const 角色名 = toText(payload.角色 || payload.char || payload.character || snapshot?.activeName, '').trim();
    const 技能名称 = toText(payload.技能名称 || payload.名称 || payload.name || payload.label, '待命名技能').trim() || '待命名技能';
    const 技能类型 = /武魂融合技/.test(toText(payload.技能类型 || payload.type || payload.category, '')) ? '武魂融合技' : '自创魂技';
    const 角色 = resolveSnapshotCharacter(snapshot, 角色名 || snapshot?.activeName);
    if (!角色.key || !角色.char) return { invalid: true, reason: 'skill_gain_character_unresolved', 角色: 角色名, 技能名称, 技能类型 };
    return {
      角色: 角色.displayName || 角色.key,
      charKey: 角色.key,
      技能名称,
      技能类型,
      来源: toText(payload.来源 || payload.source, '非传授来源'),
    };
  }

  function 构建模块路由成功结果(moduleKind = '', request = null, extra = {}) {
    const kind = moduleKind || '';
    const publicRequest = request && typeof request === 'object' ? { ...request } : request;
    if (publicRequest && typeof publicRequest === 'object') delete publicRequest.动作上下文;
    return {
      handled: true,
      kind,
      request: publicRequest || null,
      runtimeEvent: extra && extra.runtimeEvent ? extra.runtimeEvent : 构建模块路由运行事件文本(kind, publicRequest, extra),
      ...extra,
    };
  }


  function 格式化模块路由资源消耗(cost = {}) {
    if (!cost || typeof cost !== 'object') return '';
    const parts = [];
    const currency = toText(cost.currency, '').trim();
    const coin = toNumber(cost.coin, 0);
    const sp = toNumber(cost.sp, 0);
    const vit = toNumber(cost.vit, 0);
    if (coin > 0 && currency) parts.push(`${currency}${formatNumber(coin)}`);
    if (sp > 0) parts.push(`魂力${formatNumber(sp)}`);
    if (vit > 0) parts.push(`体力${formatNumber(vit)}`);
    return parts.join('、');
  }

  function 格式化模块路由耗时(extra = {}, request = {}) {
    const 文本 = toText(extra && (extra.durationText || extra.duration), '').trim();
    if (文本) return 文本;
    const ticks = toNumber(extra && extra.durationTicks, toNumber(request && request.耗时tick, 0));
    return 格式化tick时长文本_桥接(ticks);
  }

  function 拼接事实片段(片段列表 = []) {
    return (Array.isArray(片段列表) ? 片段列表 : [])
      .map(片段 => toText(片段, '').trim())
      .filter(Boolean)
      .join('，');
  }

  function 格式化模块原因文本(reason = '') {
    const 文本 = toText(reason, '').trim();
    return 文本 ? `原因：${文本}` : '原因未记录';
  }

  function 构建模块路由运行事件文本(moduleKind = '', request = {}, extra = {}) {
    const 模块 = toText(moduleKind, 'unknown');
    if (!模块 || 模块 === '未命中') return '';
    const 模式 = toText(extra && extra.dispatchMode, 'settled_summary');
    const 状态 =
      toText(extra && extra.status, '') ||
      (模式 === 'failed_summary'
        ? '执行失败'
        : 模式 === 'pending_confirmation' || /opened_.*panel/.test(模式)
          ? '待确认'
          : /battle_takeover|battle_continuation/.test(模式)
            ? '实时接管'
            : '执行成功');
    const 原因 = toText(extra && extra.reason, '');
    let 事实 = '';
    if (模块 === 'trial_entry') {
      const 试炼类型 = toText(request && request.试炼类型, '试炼');
      const 层数 = Math.max(0, Math.floor(toNumber(request && request.floor, toNumber(extra?.result?.context?.当前层, 0))));
      const 地点 = toText(extra?.trialLocation || extra?.result?.context?.试炼内地点, '');
      if (状态 === '执行失败') {
        事实 = `${试炼类型}入场未结算，${拼接事实片段([request?.ticketName ? `门票：${toText(request.ticketName, '')}` : '', 地点 ? `地点：${地点}` : '', 格式化模块原因文本(原因)])}。`;
      } else {
        事实 = `${试炼类型}入场成功，已消耗门票${request?.ticketName ? `【${toText(request.ticketName, '')}】` : ''}${层数 > 0 ? `，进入第${层数}层` : ''}${地点 ? `，当前位置已更新为${地点}` : ''}。`;
      }
    } else if (模块 === 'travel') {
      const 角色 = toText(request && request.角色, '');
      const 起点 = toText(extra && extra.startLoc, '');
      const 终点 = toText(extra && extra.finalLocName, toText(request && request.目标地点, '目标地点'));
      const 消耗 = 格式化模块路由资源消耗(extra && extra.cost);
      const 耗时 = 格式化模块路由耗时(extra, request);
      const 未解析 = Array.isArray(request?.未解析角色)
        ? request.未解析角色
        : Array.isArray(extra?.unresolvedCharacters)
          ? extra.unresolvedCharacters
          : [];
      const 未解析文本 = 未解析.length ? `未解析同行角色：${未解析.join('、')}` : '';
      if (状态 === '执行失败') {
        事实 = `移动未结算，${拼接事实片段([角色 ? `角色：${角色}` : '', 终点 ? `目标：${终点}` : '', 未解析文本, 格式化模块原因文本(原因)])}。`;
      } else if (extra && extra.alreadyThere) {
        事实 = `移动无需结算，${拼接事实片段([角色 ? `角色：${角色}` : '', `当前位置：${终点}`, 未解析文本])}。`;
      } else {
        事实 = `移动完成，${拼接事实片段([角色 ? `角色：${角色}` : '', 起点 ? `起点：${起点}` : '', `终点：${终点}`, 耗时 ? `用时：${耗时}` : '', 消耗 ? `消耗：${消耗}` : '', 未解析文本])}。`;
      }
    } else if (模块 === 'trade') {
      const 动作 = toText(request && request.动作, '交易');
      const 物品 = toText(request && request.物品, '物品');
      const 对象 = toText(request && (request.对象 || request.目标), '');
      const 数量 = Math.max(1, Math.floor(toNumber(request && request.数量, 1)));
      if (状态 === '待确认') {
        事实 = `交易待确认，${拼接事实片段([`动作：${动作}`, 对象 ? `对象：${对象}` : '', `物品：${物品}`, `数量：${数量}`])}，尚未成交。`;
      } else if (状态 === '执行失败') {
        事实 = `交易未结算，${拼接事实片段([`动作：${动作}`, 对象 ? `对象：${对象}` : '', `物品：${物品}`, `数量：${数量}`, 格式化模块原因文本(原因)])}。`;
      } else {
        事实 = `交易已结算，${拼接事实片段([`动作：${动作}`, 对象 ? `对象：${对象}` : '', `物品：${物品}`, `数量：${数量}`])}。`;
      }
    } else if (模块 === 'profession') {
      const 动作 = toText(request && (request.动作 || request.模式), '工坊');
      const 目标 = toText(request && request.目标, '');
      const 材料 = Array.isArray(request?.材料) ? request.材料.map(item => toText(item?.名称 || item, '')).filter(Boolean).join('、') : toText(request && request.材料, '');
      if (状态 === '待确认') {
        事实 = `工坊待确认，${拼接事实片段([`动作：${动作}`, 目标 ? `目标：${目标}` : '', 材料 ? `材料：${材料}` : ''])}，尚未执行。`;
      } else if (状态 === '执行失败') {
        事实 = `工坊未结算，${拼接事实片段([`动作：${动作}`, 目标 ? `目标：${目标}` : '', 材料 ? `材料：${材料}` : '', 格式化模块原因文本(原因)])}。`;
      } else {
        事实 = `工坊已结算，${拼接事实片段([`动作：${动作}`, 目标 ? `目标：${目标}` : '', 材料 ? `材料：${材料}` : ''])}。`;
      }
    } else if (模块 === 'battle') {
      if (/battle_takeover|battle_continuation/.test(模式) || 状态 === '实时接管') {
        事实 = `战斗模块已接管${原因 ? `，原因：${原因}` : ''}。`;
      } else if (模式 === 'battle_auto_arbitration') {
        const 战报轮数 = toNumber(extra?.result?.result?.roundsExecuted, 0);
        const 战果 = toText(extra?.result?.result?.winner, '');
        const 战报列表 = Array.isArray(extra?.result?.result?.logs) ? extra.result.result.logs.slice(-6).map(item => toText(item, '')).filter(Boolean) : [];
        事实 = `自动战斗已完成前端推演${战报轮数 > 0 ? `，实际推演${战报轮数}回合` : ''}${战果 ? `，结果标记：${战果}` : ''}${战报列表.length ? `。\n战报摘要：${战报列表.join('；')}` : '。'}`;
      } else if (状态 === '执行失败') {
        const 敌方 = toText(deepGet(request, '参战者.team_enemy.0.name', ''), '');
        事实 = `战斗未开启，${拼接事实片段([敌方 ? `敌方：${敌方}` : '', 格式化模块原因文本(原因)])}。`;
      } else {
        const 敌方 = toText(deepGet(request, '参战者.team_enemy.0.name', ''), '');
        事实 = `战斗模块已开启${敌方 ? `，敌方：${敌方}` : ''}。`;
      }
    } else if (模块 === 'routine') {
      const 角色 = toText(request && request.角色, toText(extra && extra.charName, '角色'));
      const 动作 = toText(request && request.动作, toText(extra && extra.actionMode, '日常'));
      const 地点 = toText(request && (request.地点 || request.位置), toText(extra && extra.location, ''));
      const 耗时 = 格式化模块路由耗时(extra, request);
      const 摘要 = toText(extra && extra.summary, '');
      const 世界投影 = toText(extra && extra.worldContextProjection, '').trim();
      if (状态 === '执行失败') {
        事实 = `${角色}的${动作}未结算，${拼接事实片段([地点 ? `地点：${地点}` : '', 耗时 ? `计划用时：${耗时}` : '', 格式化模块原因文本(原因)])}。`;
      } else {
        事实 = `${角色}完成${动作}${地点 ? `，地点：${地点}` : ''}${耗时 ? `，用时：${耗时}` : ''}${世界投影 ? `，${世界投影}` : ''}${摘要 ? `，${摘要}` : '，本次结算无可见数值变化'}。`;
      }
    } else if (模块 === 'teaching') {
      const 老师 = toText(request && request.老师, '');
      const 学生 = toText(request && request.学生, '');
      const 内容 = toText(request && (request.内容名称 || request.内容 || request.技能), '');
      事实 = 状态 === '执行失败'
        ? `传授未结算，${拼接事实片段([老师 ? `老师：${老师}` : '', 学生 ? `学生：${学生}` : '', 内容 ? `内容：${内容}` : '', 格式化模块原因文本(原因)])}。`
        : `传授已处理，${拼接事实片段([老师 ? `老师：${老师}` : '', 学生 ? `学生：${学生}` : '', 内容 ? `内容：${内容}` : '', extra?.reason ? `结果：${toText(extra.reason, '')}` : ''])}。`;
    } else if (模块 === 'skill_gain') {
      const 角色 = toText(request && request.角色, '');
      const 技能名称 = toText(request && request.技能名称, '待命名技能');
      const 技能类型 = toText(request && request.技能类型, '自创魂技');
      事实 = 状态 === '执行失败'
        ? `新技能确认未开启，${拼接事实片段([角色 ? `角色：${角色}` : '', `技能：${技能名称}`, 格式化模块原因文本(原因)])}。`
        : `新技能待确认，${拼接事实片段([角色 ? `角色：${角色}` : '', `类型：${技能类型}`, `技能：${技能名称}`])}。`;
    } else {
      事实 = 状态 === '执行失败' ? `模块执行失败${原因 ? `，原因：${原因}` : ''}。` : `模块已处理，模式：${模式}。`;
    }
    return `<module_routing_result>\n模块：${模块}\n状态：${状态}\n事实：${事实}\n</module_routing_result>`;
  }

  function 读取快照当前位置(snapshot) {
    return toText(
      deepGet(snapshot, 'activeChar.状态.位置', snapshot && snapshot.currentLoc),
      snapshot && snapshot.currentLoc,
    );
  }

  function 归一化模块意图类型(kind = '') {
    const 文本 = toText(kind, '').toLowerCase();
    if (/^time_advance$|时间推进|时间结算/.test(文本)) return 'time_advance';
    if (/battle|combat|战斗|切磋|单挑/.test(文本)) return 'battle';
    if (/trade|交易|购买|出售|竞拍|拍卖/.test(文本)) return 'trade';
    if (/craft|profession|job|副职业|工坊|锻造|制造|设计|修理|维修/.test(文本)) return 'profession';
    if (/teaching|teach|传授|授课|教学|指点/.test(文本)) return 'teaching';
    if (/skill_gain|技能获得|新技能/.test(文本)) return 'skill_gain';
    if (/travel|move|移动|前往|赶往|抵达|出发|启程|赶路|去往/.test(文本)) return 'travel';
    if (/routine|daily|修炼|冥想|拟态|探索|搜索|调查|侦察|勘察/.test(文本)) return 'routine';
    if (/trial_entry|trial|升灵台|魂灵塔|试炼/.test(文本)) return 'trial_entry';
    if (/未命中|none|no_module|no module/.test(文本)) return '未命中';
    return '';
  }

  function 读取任务时间推进tick_桥接(options = {}) {
    const tick增量 = Number(options?.时间推进上下文?.tick增量);
    return Number.isFinite(tick增量) && tick增量 > 0 ? tick增量 : 0;
  }

  function 读取移动请求文本(payload = {}, 字段列表 = [], 回退值 = '') {
    for (const 字段 of 字段列表) {
      if (payload && payload[字段] !== undefined && payload[字段] !== null && payload[字段] !== '') {
        return toText(payload[字段], 回退值).trim();
      }
    }
    return toText(回退值, '').trim();
  }

  function 读取移动请求数值(payload = {}, 字段列表 = [], 回退值 = 0) {
    for (const 字段 of 字段列表) {
      if (payload && payload[字段] !== undefined && payload[字段] !== null && payload[字段] !== '') {
        return toNumber(payload[字段], 回退值);
      }
    }
    return toNumber(回退值, 0);
  }

  function 规范地点键名(名称 = '') {
    return toText(名称, '')
      .replace(/^斗罗大陆-/, '')
      .replace(/^斗灵大陆-/, '')
      .trim();
  }

  function 取地点叶名(名称 = '') {
    const 清理名 = 规范地点键名(名称);
    const 片段 = 清理名
      .split('-')
      .map(item => item.trim())
      .filter(Boolean);
    return 片段[片段.length - 1] || 清理名;
  }

  function 取地点路径片段(名称 = '') {
    return 规范地点键名(名称)
      .split('-')
      .map(片段 => 片段.trim())
      .filter(Boolean);
  }

  function 推导移动父级上下文(snapshot, request = {}) {
    const 显式父级 = 规范地点键名(request && request.归属父节点);
    if (显式父级) return 显式父级;
    const 目标片段 = 取地点路径片段(request && (request.原始目标地点 || request.目标地点));
    if (目标片段.length > 1) return 目标片段.slice(0, -1).join('-');
    const 当前位置 = 读取快照当前位置(snapshot);
    const 当前信息 = 查找世界地点数据(snapshot, 当前位置);
    if (Array.isArray(当前信息.path) && 当前信息.path.length) return 当前信息.path.join('-');
    const 当前片段 = 取地点路径片段(当前位置);
    if (当前片段.length > 1) return 当前片段.slice(0, -1).join('-');
    const 动态父级 = toText(当前信息?.data?.归属父节点, '').trim();
    return 规范地点键名(动态父级);
  }

  function 查找世界地点数据(snapshot, 名称 = '') {
    const rootData = deepGet(snapshot, 'rootData', {});
    const 候选名列表 = [];
    const 清理名 = 规范地点键名(名称);
    const 叶名 = 取地点叶名(名称);
    [名称, 清理名, 叶名].forEach(item => {
      const 文本 = toText(item, '').trim();
      if (文本 && !候选名列表.includes(文本)) 候选名列表.push(文本);
    });
    const 静态地点 = deepGet(rootData, 'world.地点', {});
    const 动态地点 = deepGet(rootData, 'world.动态地点', {});
    const 查找静态路径 = 路径名 => {
      const 片段列表 = 规范地点键名(路径名)
        .split('-')
        .map(片段 => 片段.trim())
        .filter(Boolean);
      if (!片段列表.length) return null;
      let 当前 = 静态地点?.[片段列表[0]];
      if (!当前) return null;
      for (let 序号 = 1; 序号 < 片段列表.length; 序号 += 1) {
        当前 = 当前?.子节点?.[片段列表[序号]];
        if (!当前) return null;
      }
      return {
        name: 片段列表.join('-'),
        leafName: 片段列表[片段列表.length - 1],
        path: 片段列表,
        data: 当前,
        source: 'world.地点',
      };
    };
    for (const 候选名 of 候选名列表) {
      if (静态地点 && typeof 静态地点 === 'object' && 静态地点[候选名]) {
        return { name: 候选名, data: 静态地点[候选名], source: 'world.地点' };
      }
      const 静态路径命中 = 查找静态路径(候选名);
      if (静态路径命中) return 静态路径命中;
      if (动态地点 && typeof 动态地点 === 'object' && 动态地点[候选名]) {
        return { name: 候选名, data: 动态地点[候选名], source: 'world.动态地点' };
      }
    }
    return { name: 清理名 || 叶名, data: null, source: '' };
  }

  function 查找父级限定世界地点数据(snapshot, 目标名称 = '', 父节点 = '') {
    const rootData = deepGet(snapshot, 'rootData', {});
    const 父级名 = 规范地点键名(父节点);
    const 目标名 = 规范地点键名(目标名称) || 取地点叶名(目标名称);
    const 目标叶名 = 取地点叶名(目标名);
    if (!目标名) return { name: '', data: null, source: '' };
    const 完整路径命中 = 查找世界地点数据(snapshot, 目标名);
    if (完整路径命中.data && (目标名.includes('-') || !父级名)) return 完整路径命中;
    const 直接路径 = 父级名 && !目标名.startsWith(`${父级名}-`) ? `${父级名}-${目标名}` : 目标名;
    const 精确命中 = 查找世界地点数据(snapshot, 直接路径);
    if (精确命中.data) return 精确命中;
    if (!父级名) return { name: 目标名, data: null, source: '' };
    const 接口 = 获取运行时实体命中接口_桥接();
    if (接口 && typeof 接口.收集运行时地点命中 === 'function') {
      try {
        const 命中 = 接口.收集运行时地点命中(rootData, 目标叶名 || 目标名, {
          归属父节点: 父级名,
          父节点: 父级名,
          当前地点: toText(deepGet(snapshot, 'activeChar.状态.位置', ''), ''),
          阈值: 1,
          上限: 1,
        })?.[0];
        if (命中?.名称) {
          const 命中数据 = 查找世界地点数据(snapshot, 命中.名称);
          const 命中叶名 = 取地点叶名(命中数据.name || 命中.名称);
          if (命中数据.data && (!目标名.includes('-') || 命中叶名 === 目标叶名)) return 命中数据;
        }
      } catch (错误) {}
    }
    const 动态地点 = deepGet(rootData, 'world.动态地点', {});
    for (const [动态名, 动态数据] of safeEntries(动态地点)) {
      if (!动态数据 || typeof 动态数据 !== 'object') continue;
      if (规范地点键名(动态数据.归属父节点) !== 父级名) continue;
      const 匹配文本 = `${动态名}\n${动态数据.势力 || ''}\n${动态数据.归属父节点 || ''}`;
      if (匹配文本.includes(目标名) || 目标名.includes(toText(动态名, ''))) {
        return { name: 动态名, data: 动态数据, source: 'world.动态地点' };
      }
    }
    return { name: 目标名, data: null, source: '' };
  }

  function 构建移动绝对位置(snapshot, 目标地点 = '', 父节点 = '') {
    const 原始目标 = toText(目标地点, '').trim();
    if (/^(斗罗大陆|斗灵大陆)-/.test(原始目标)) return 原始目标;
    const 当前位置 = toText(deepGet(snapshot, 'activeChar.状态.位置', ''), '');
    const 大陆前缀 = 当前位置.startsWith('斗灵大陆-') ? '斗灵大陆' : '斗罗大陆';
    const 目标清理名 = 规范地点键名(原始目标);
    const 父清理名 = 规范地点键名(父节点);
    if (!父清理名 || 父清理名 === 大陆前缀) return `${大陆前缀}-${目标清理名}`;
    if (目标清理名 === 父清理名 || 目标清理名.startsWith(`${父清理名}-`)) return `${大陆前缀}-${目标清理名}`;
    return `${大陆前缀}-${父清理名}-${目标清理名}`;
  }

  function 取移动目标父节点名(targetInfo = {}, request = {}) {
    if (Array.isArray(targetInfo?.path) && targetInfo.path.length >= 2) return targetInfo.path.slice(0, -1).join('-');
    return toText(targetInfo?.data?.归属父节点, toText(request && request.归属父节点, ''));
  }

  function 查找当前路径相关移动地点(snapshot, 目标名称 = '') {
    const 目标片段 = 取地点路径片段(目标名称);
    const 目标名 = 规范地点键名(目标名称);
    const 目标叶名 = 取地点叶名(目标名称);
    if (!目标名 && !目标叶名) return { name: '', data: null, source: '' };
    const 当前片段 = 取地点路径片段(读取快照当前位置(snapshot));
    for (let 长度 = 当前片段.length; 长度 >= 1; 长度 -= 1) {
      const 候选片段 = 当前片段.slice(0, 长度);
      const 候选名 = 候选片段.join('-');
      const 候选叶名 = 候选片段[候选片段.length - 1] || '';
      if (候选名 !== 目标名 && 候选叶名 !== 目标叶名) continue;
      const 命中 = 查找世界地点数据(snapshot, 候选名);
      if (命中.data) return 命中;
    }
    if (目标片段.length > 当前片段.length && 当前片段.length) {
      const 当前前缀 = 当前片段.join('-');
      if (目标名.startsWith(`${当前前缀}-`)) {
        const 命中 = 查找世界地点数据(snapshot, 目标名);
        if (命中.data) return 命中;
      }
    }
    return { name: 目标名 || 目标叶名, data: null, source: '' };
  }

  function 解析移动已有地点目标(snapshot, request = {}) {
    const 目标名称 = request && (request.原始目标地点 || request.目标地点);
    const 显式父级 = 规范地点键名(request && request.归属父节点);
    const 直接命中 = 查找世界地点数据(snapshot, 目标名称);
    if (直接命中.data) return 直接命中;
    if (显式父级) {
      const 父级命中 = 查找父级限定世界地点数据(snapshot, 目标名称, 显式父级);
      if (父级命中.data) return 父级命中;
    }
    const 当前路径命中 = 查找当前路径相关移动地点(snapshot, 目标名称);
    if (当前路径命中.data) return 当前路径命中;
    const 父级上下文 = 推导移动父级上下文(snapshot, request);
    return 查找父级限定世界地点数据(snapshot, 目标名称, 父级上下文);
  }

  function 推导新动态地点父级(snapshot, request = {}) {
    const 显式父级 = 规范地点键名(request && request.归属父节点);
    if (显式父级 && 查找世界地点数据(snapshot, 显式父级).data) return 显式父级;
    const 目标片段 = 取地点路径片段(request && (request.原始目标地点 || request.目标地点));
    if (目标片段.length > 1) {
      const 路径父级 = 目标片段.slice(0, -1).join('-');
      if (查找世界地点数据(snapshot, 路径父级).data) return 路径父级;
    }
    const 当前片段 = 取地点路径片段(读取快照当前位置(snapshot));
    for (let 长度 = 当前片段.length; 长度 >= 1; 长度 -= 1) {
      const 候选父级 = 当前片段.slice(0, 长度).join('-');
      if (查找世界地点数据(snapshot, 候选父级).data) return 候选父级;
    }
    return 显式父级 || 推导移动父级上下文(snapshot, request);
  }

  function 推导移动动态地点坐标(snapshot, request = {}) {
    const mapBridge = window.__sheepMapBridge;
    if (mapBridge && typeof mapBridge.deriveDynamicLocationCoord === 'function') {
      try {
        const result = mapBridge.deriveDynamicLocationCoord(request.归属父节点, {
          targetName: request.目标地点,
          direction: request.方位,
          ticks: request.耗时tick,
          method: request.移动方式,
        });
        if (
          result &&
          result.ok &&
          Number.isFinite(toNumber(result.x, NaN)) &&
          Number.isFinite(toNumber(result.y, NaN))
        ) {
          return {
            ok: true,
            x: Math.round(toNumber(result.x, 0)),
            y: Math.round(toNumber(result.y, 0)),
            source: result.source || 'map_bridge',
          };
        }
      } catch (error) {}
    }

    const rootData = deepGet(snapshot, 'rootData', {});
    const 父级 = 查找世界地点数据(snapshot, request.归属父节点);
    const 父坐标 =
      父级.data && Number.isFinite(toNumber(父级.data.x, NaN)) && Number.isFinite(toNumber(父级.data.y, NaN))
        ? { x: toNumber(父级.data.x, 0), y: toNumber(父级.data.y, 0) }
        : null;
    const 同级坐标 = safeEntries(deepGet(rootData, 'world.动态地点', {}))
      .filter(([, item]) => item && typeof item === 'object' && toText(item.归属父节点, '') === 父级.name)
      .map(([, item]) => ({ x: toNumber(item.x, NaN), y: toNumber(item.y, NaN) }))
      .filter(coord => Number.isFinite(coord.x) && Number.isFinite(coord.y) && coord.x >= 0 && coord.y >= 0);
    const 基准 = 父坐标 || 同级坐标[同级坐标.length - 1] || null;
    if (!基准) return { ok: false, reason: 'parent_coord_unavailable' };
    const 方位 = toText(request.方位, '');
    const 向量 = {
      x: /东/.test(方位) ? 1 : /西/.test(方位) ? -1 : 0,
      y: /南/.test(方位) ? 1 : /北/.test(方位) ? -1 : 0,
    };
    if (!向量.x && !向量.y) {
      向量.x = 1;
      向量.y = 1;
    }
    const 步长 = Math.max(12, Math.min(60, 14 + Math.floor(toNumber(request.耗时tick, 1) * 4)));
    const 偏移序号 = 同级坐标.length + 1;
    let x = Math.round(基准.x + 向量.x * 步长 + (偏移序号 % 3) * 7);
    let y = Math.round(基准.y + 向量.y * 步长 + Math.floor(偏移序号 / 3) * 7);
    const 已占用 = new Set(同级坐标.map(coord => `${Math.round(coord.x)},${Math.round(coord.y)}`));
    while (已占用.has(`${x},${y}`)) {
      x += 9;
      y += 6;
    }
    return { ok: true, x, y, source: 父坐标 ? 'parent_coord' : 'sibling_coord' };
  }

  function 计算移动基础消耗(snapshot, request = {}) {
    const 角色数据 = request.charData || {};
    const 属性 = 角色数据.属性 || {};
    const 财富 = 角色数据.财富 || {};
    const tick = Math.max(0.1, toNumber(request.耗时tick, 1));
    const 方式 = toText(request.移动方式, '步行');
    const 钱包 = 读取当前时代钱包配置_桥接(snapshot?.rootData || {});
    const 飞行能力 = 读取旅行飞行能力_桥接(角色数据);
    const 合法方式 = {
      dldl: ['步行', '马车', '远洋海船', '斗铠飞行', '飞行魂导器', '肉身飞行', '空间传送(极限斗罗)'],
      jueshitangmen: ['步行', '魂导蒸汽车', '魂导列车', '远洋巨轮', '斗铠飞行', '飞行魂导器', '肉身飞行', '空间传送(极限斗罗)'],
      current: ['步行', '校园短驳车', '魂导汽车', '魂导列车', '远洋巨轮', '斗铠飞行', '飞行魂导器', '机甲飞行', '肉身飞行', '空间传送(极限斗罗)'],
      zjdl: ['步行', '校园短驳车', '飞机', '宇宙飞船', '宇宙飞船跃迁', '斗铠飞行', '飞行魂导器', '机甲飞行', '肉身飞行'],
    }[钱包.eraId] || [];
    if (!合法方式.includes(方式)) return { ok: false, reason: `${钱包.eraId || '未知时代'}不可使用交通方式：${方式}` };
    const 地点上下文 = [角色数据?.状态?.位置, request.目标地点, request.归属父节点].map(值 => toText(值, '')).filter(Boolean).join(' ');
    const 法币 = 读取当前时代法定货币_桥接(snapshot?.rootData || {}, 地点上下文);
    let 货币数 = 0;
    let 魂力 = 0;
    let 体力 = 0;
    if (/步行|跑|徒步/.test(方式)) {
      体力 = Math.max(1, Math.round(tick * 3));
    } else if (/短驳|校车|公交/.test(方式)) {
      货币数 = Math.max(1, Math.round(tick * 2));
    } else if (方式 === '马车') {
      货币数 = Math.max(1, Math.ceil(tick / 12));
    } else if (方式 === '魂导蒸汽车') {
      货币数 = Math.max(1, Math.ceil(tick / 6));
    } else if (/魂导汽车|魂导列车|远洋巨轮|远洋海船/.test(方式)) {
      货币数 = 钱包.eraId === 'jueshitangmen'
        ? Math.max(1, Math.ceil(tick / 3))
        : Math.max(1, Math.round(tick * 10));
    } else if (/飞机/.test(方式)) {
      货币数 = Math.max(1, Math.round(tick * 15));
    } else if (/宇宙飞船/.test(方式)) {
      货币数 = Math.max(1, Math.round(tick * (方式.includes('跃迁') ? 40 : 20)));
    } else if (方式 === '飞行魂导器') {
      if (飞行能力.等级 < 30) return { ok: false, reason: '飞行魂导器至少需要30级魂力修为' };
      if (飞行能力.飞行魂导器等级 <= 0) return { ok: false, reason: '需装配可用的飞行魂导器' };
      魂力 = Math.max(1, Math.ceil(tick * Math.max(3, 13 - 飞行能力.飞行魂导器等级)));
    } else if (方式 === '斗铠飞行') {
      if (!飞行能力.有斗铠) return { ok: false, reason: '需拥有可用斗铠' };
      魂力 = Math.max(1, Math.round(tick * 8));
      体力 = Math.max(1, Math.round(tick * 2));
    } else if (方式 === '机甲飞行') {
      if (!飞行能力.有机甲) return { ok: false, reason: '需拥有可用机甲' };
      魂力 = Math.max(1, Math.round(tick * 8));
      体力 = Math.max(1, Math.round(tick * 2));
    } else if (方式 === '肉身飞行') {
      if (飞行能力.等级 < 70) return { ok: false, reason: '肉身飞行至少需要70级魂力修为' };
      魂力 = Math.max(1, Math.round(tick * 8));
      体力 = Math.max(1, Math.round(tick * 2));
    } else if (/传送|空间/.test(方式)) {
      魂力 = Math.max(1, Math.round(tick * 20));
    } else {
      体力 = Math.max(1, Math.round(tick * 2));
    }
    if (货币数 > 0 && 法币.status !== 'resolved') return { ok: false, reason: '当前时代货币未就绪' };
    const 货币 = 法币.status === 'resolved' ? 法币.currency : '';
    const 当前货币 = toNumber(财富[货币], 0);
    const 当前魂力 = toNumber(属性.魂力, 0);
    const 当前体力 = toNumber(属性.体力, 0);
    if (货币数 > 当前货币) return { ok: false, reason: `${货币}不足`, 货币, 货币数, 魂力, 体力 };
    if (魂力 > 当前魂力) return { ok: false, reason: '魂力不足', 货币, 货币数, 魂力, 体力 };
    if (体力 > 当前体力) return { ok: false, reason: '体力不足', 货币, 货币数, 魂力, 体力 };
    return {
      ok: true,
      货币,
      货币数,
      魂力,
      体力,
      消耗文本:
        [货币数 > 0 ? `${货币数}${货币}` : '', 魂力 > 0 ? `${魂力}魂力` : '', 体力 > 0 ? `${体力}体力` : '']
          .filter(Boolean)
          .join(' / ') || '无额外消耗',
    };
  }

  function 读取旅行飞行能力_桥接(角色数据 = {}) {
    return 读取旅行能力运行时_桥接()?.读取旅行能力(角色数据) || {
      等级: 0,
      有斗铠: false,
      有机甲: false,
      有神级机甲: false,
      飞行魂导器等级: 0,
      飞行魂导器名称: '',
    };
  }

  function 是自主移动方式_桥接(方式 = '') {
    const 文本 = toText(方式, '步行').trim().toLowerCase() || '步行';
    if (/公共交通|列车|地铁|公交|航班|飞船客运|客运飞船|渡船|轮渡|校车|短驳|火车|train|subway|metro|bus|flight|ferry|passenger[\s_-]*ship|space[\s_-]*(flight|shuttle)|自有|自驾|私人|载具|汽车|飞行器|机甲|斗铠|vehicle|private|personal|own/.test(文本)) return false;
    return /步行|徒步|攀爬|游泳|跑步|奔跑|walk|hike|climb|swim|run/.test(文本);
  }

  function 应用旅行环境修正_桥接(request = {}, mapRequest = {}) {
    const source = mapRequest && typeof mapRequest === 'object' && !Array.isArray(mapRequest)
      ? cloneJsonValue(mapRequest, {})
      : {};
    const method = toText(source.method, toText(request.移动方式 || request.method || request.travelMethod, '步行')).trim() || '步行';
    const travel = request?.动作上下文?.modifiers?.旅行;
    const autonomous = 是自主移动方式_桥接(method);
    const timeMultiplier = autonomous
      ? Math.max(1, Math.min(1.3, toNumber(travel?.耗时倍率, 1)))
      : 1;
    const vitMultiplier = autonomous
      ? Math.max(1, Math.min(1.5, toNumber(travel?.体力倍率, 1)))
      : 1;
    const baseTicks = Math.max(0, toNumber(source.est_ticks, toNumber(request.耗时tick, 0)));
    let estTicks = autonomous
      ? Math.max(baseTicks > 0 ? 0.1 : 0, Math.round(baseTicks * timeMultiplier * 10) / 10)
      : baseTicks;
    let costs = source.costs && typeof source.costs === 'object' && !Array.isArray(source.costs)
      ? { ...source.costs }
      : null;
    const 飞行能力 = 读取旅行飞行能力_桥接(request.charData || {});
    const 旅行运行时 = 读取旅行能力运行时_桥接();
    const 精确字段 = ['start_x', 'start_y', 'target_x', 'target_y', 'distance'].map(字段 => toNumber(source[字段], NaN));
    const 有精确地图上下文 = toText(source.map_id, '').trim() && 精确字段.every(Number.isFinite);
    let 运行时已接管 = false;
    if (有精确地图上下文 && 旅行运行时) {
      const [startX, startY, targetX, targetY, suppliedDistance] = 精确字段;
      let 地图快照 = null;
      for (const host of [globalThis, globalThis.window, globalThis.parent, globalThis.top]) {
        try {
          if (host?.__sheepMapSnapshot) { 地图快照 = host.__sheepMapSnapshot; break; }
        } catch (_) {}
      }
      const mapId = toText(source.map_id, '').trim();
      const 当前X = toNumber(request?.charData?.状态?.横坐标, NaN);
      const 当前Y = toNumber(request?.charData?.状态?.纵坐标, NaN);
      const 起点已变化 = Number.isFinite(当前X) && Number.isFinite(当前Y) && 当前X >= 0 && 当前Y >= 0
        && (Math.abs(当前X - startX) > 1 || Math.abs(当前Y - startY) > 1);
      if (地图快照?.currentMapId && toText(地图快照.currentMapId, '') !== mapId) {
        costs = { currency: '', coin: 0, sp: 0, vit: 0, canAfford: false, reason: '地图已切换，请重新规划路线' };
        运行时已接管 = true;
      } else if (起点已变化) {
        costs = { currency: '', coin: 0, sp: 0, vit: 0, canAfford: false, reason: '角色位置已变化，请重新规划路线' };
        运行时已接管 = true;
      } else {
        const bounds = 地图快照?.bounds && typeof 地图快照.bounds === 'object' ? 地图快照.bounds : null;
        const width = Math.max(1, toNumber(bounds?.width, 1));
        const height = Math.max(1, toNumber(bounds?.height, width));
        const actualDistance = Math.hypot(targetX - startX, (targetY - startY) * width / height);
        const tolerance = Math.max(1, actualDistance * 0.01);
        if (Math.abs(actualDistance - suppliedDistance) > tolerance) {
          costs = { currency: '', coin: 0, sp: 0, vit: 0, canAfford: false, reason: '路线距离校验失败，请重新规划路线' };
          运行时已接管 = true;
        } else {
          const 钱包 = 读取当前时代钱包配置_桥接(request?.rootData || request?.snapshot?.rootData || {});
          const runtimeResult = 旅行运行时.计算旅行参数({
            method,
            distance: actualDistance,
            distanceScale: Math.max(0.003, Math.min(100, toNumber(source.distance_scale, 1))),
            mapId,
            eraId: 钱包.eraId,
            character: request.charData || {},
          });
          if (runtimeResult?.recognized) {
            运行时已接管 = true;
            if (!runtimeResult.ok) {
              costs = { currency: '', coin: 0, sp: 0, vit: 0, canAfford: false, reason: runtimeResult.reason || '当前旅行方式不可用' };
            } else {
              estTicks = runtimeResult.ticks;
              costs = {
                currency: '',
                coin: 0,
                sp: Math.max(0, Math.floor(toNumber(runtimeResult.costs?.sp, 0))),
                vit: Math.max(0, Math.floor(toNumber(runtimeResult.costs?.vit, 0))),
                canAfford: true,
                note: toText(runtimeResult.note, method),
              };
            }
          }
        }
      }
    }
    if (!有精确地图上下文 && method === '机甲飞行' && toText(source.map_id, '') === 'map_zjdl_stellar') {
      costs = { currency: '', coin: 0, sp: 0, vit: 0, canAfford: false, reason: '星际机甲移动缺少精确路线，请重新规划' };
      运行时已接管 = true;
    }
    const 飞行阻碍 = 运行时已接管 ? '' : method === '斗铠飞行' && !飞行能力.有斗铠
      ? '需拥有可用斗铠'
      : method === '机甲飞行' && !飞行能力.有机甲
        ? '需拥有可用机甲'
        : method === '肉身飞行' && 飞行能力.等级 < 70
          ? '肉身飞行至少需要70级魂力修为'
          : method === '飞行魂导器' && 飞行能力.等级 < 30
            ? '飞行魂导器至少需要30级魂力修为'
            : method === '飞行魂导器' && 飞行能力.飞行魂导器等级 <= 0
              ? '需装配可用的飞行魂导器'
              : '';
    if (!运行时已接管 && (飞行阻碍 || method === '飞行魂导器')) {
      costs ||= { currency: '', coin: 0, sp: 0, vit: 0 };
      if (飞行阻碍) {
        costs.canAfford = false;
        costs.reason = 飞行阻碍;
      } else {
        costs.sp = Math.max(1, Math.ceil(estTicks * Math.max(3, 13 - 飞行能力.飞行魂导器等级)));
        costs.note = `${飞行能力.飞行魂导器等级}级飞行魂导器${飞行能力.飞行魂导器名称 ? `·${飞行能力.飞行魂导器名称}` : ''}`;
      }
    }
    if (costs) {
      if (autonomous && vitMultiplier > 1 && toNumber(costs.vit, 0) > 0) {
        costs.vit = Math.max(1, Math.ceil(toNumber(costs.vit, 0) * vitMultiplier));
      }
      const charData = request.charData || {};
      const currency = toText(costs.currency, '').trim();
      const coin = toNumber(costs.coin, 0);
      const wealth = toNumber(charData?.财富?.[currency], 0);
      const soulPower = toNumber(charData?.属性?.魂力, 0);
      const vitality = toNumber(charData?.属性?.体力, 0);
      const insufficient = coin > 0 && !currency
        ? '当前时代货币未就绪'
        : coin > wealth
          ? `${currency}不足`
        : toNumber(costs.sp, 0) > soulPower
          ? '魂力不足'
          : toNumber(costs.vit, 0) > vitality ? '体力不足' : '';
      if (costs.canAfford === false || insufficient) {
        costs.canAfford = false;
        costs.reason = toText(costs.reason, insufficient || '资源不足，无法前往该节点。');
      } else {
        costs.canAfford = true;
      }
      costs.text = [
        coin > 0 ? `${coin}${currency}` : '',
        toNumber(costs.sp, 0) > 0 ? `${toNumber(costs.sp, 0)}魂力` : '',
        toNumber(costs.vit, 0) > 0 ? `${toNumber(costs.vit, 0)}体力` : '',
      ].filter(Boolean).join(' / ') || '无额外消耗';
    }
    return {
      ...source,
      method,
      est_ticks: estTicks,
      est_duration: autonomous || !toText(source.est_duration, '').trim()
        ? 格式化tick时长文本_桥接(estTicks)
        : source.est_duration,
      ...(costs ? { costs } : {}),
    };
  }

  function 解析移动模块意图请求(snapshot, payload = {}, narrativeText = '') {
    const 角色名 = 读取移动请求文本(
      payload,
      ['角色', 'char', 'character', '人物', '对象'],
      toText(snapshot && snapshot.activeName, ''),
    );
    const 目标地点 = 读取移动请求文本(
      payload,
      ['目标地点', 'targetLoc', 'targetLocation', 'location', 'destination', 'target', '地点'],
      '',
    );
    if (!目标地点) return null;
    const 角色解析 = 解析移动角色列表(snapshot, 角色名);
    const 主角色 = 角色解析.角色列表[0];
    if (!主角色)
      return { invalid: true, reason: 'travel_character_unresolved', 角色: 角色解析.原文 || 角色名, 目标地点, 未解析角色: 角色解析.未解析角色 };
    return {
      角色: 角色解析.角色列表.map(角色 => 角色.displayName || 角色.key).join('、'),
      原始角色: 角色解析.原文 || 角色名,
      角色列表: 角色解析.角色列表,
      未解析角色: 角色解析.未解析角色,
      charKey: 主角色.key,
      charData: 主角色.char,
      目标地点: 规范地点键名(目标地点) || 取地点叶名(目标地点),
      原始目标地点: 目标地点,
      归属父节点: 读取移动请求文本(payload, ['归属父节点', '父节点', 'parent', 'parentNode'], ''),
      移动方式:
        读取移动请求文本(
          payload,
          ['移动方式', 'method', 'travelMethod'],
          /飞行|车|列车|船|传送/.test(narrativeText) ? '' : '步行',
        ) || '步行',
      耗时tick: Math.max(0.1, 读取移动请求数值(payload, ['耗时tick', 'ticks', 'est_ticks', 'durationTicks'], 1)),
      方位: 读取移动请求文本(payload, ['方位', 'direction'], ''),
      描述: 读取移动请求文本(payload, ['描述', 'desc', 'description'], `${取地点叶名(目标地点)}。`),
    };
  }

  function 构建新动态地点移动补丁(snapshot, request = {}) {
    if (!request || request.invalid)
      return { ok: false, reason: request?.reason || 'travel_request_invalid', patchOps: [] };
    const 父级名 = 推导新动态地点父级(snapshot, request);
    const 父级 = 查找世界地点数据(snapshot, 父级名);
    if (!父级名 || !父级.data) return { ok: false, reason: 'travel_parent_missing', patchOps: [] };
    const 已有目标 = 查找父级限定世界地点数据(snapshot, request.原始目标地点 || request.目标地点, 父级.name || request.归属父节点);
    if (已有目标.data) return { ok: false, reason: 'travel_target_already_exists', patchOps: [] };
    const 目标短名 = 取地点叶名(request.原始目标地点 || request.目标地点);
    const 基础消耗 = 计算移动基础消耗(snapshot, request);
    if (!基础消耗.ok) return { ok: false, reason: 基础消耗.reason || 'travel_cost_unavailable', patchOps: [] };
    const 最终移动请求 = 应用旅行环境修正_桥接(request, {
      method: request.移动方式,
      est_ticks: request.耗时tick,
      est_duration: 格式化tick时长文本_桥接(request.耗时tick),
      costs: {
        currency: 基础消耗.货币,
        coin: 基础消耗.货币数,
        sp: 基础消耗.魂力,
        vit: 基础消耗.体力,
        canAfford: true,
      },
    });
    if (最终移动请求.costs?.canAfford === false) {
      return { ok: false, reason: 最终移动请求.costs.reason || 'travel_cost_unavailable', patchOps: [] };
    }
    const 坐标 = 推导移动动态地点坐标(snapshot, {
      ...request,
      目标地点: 目标短名,
      归属父节点: 父级.name,
      移动方式: 最终移动请求.method,
      耗时tick: 最终移动请求.est_ticks,
    });
    if (!坐标.ok) return { ok: false, reason: 坐标.reason || 'travel_coord_unavailable', patchOps: [] };
    const activePath = escapeJsonPointerValue(request.charKey);
    const targetPath = escapeJsonPointerValue(目标短名);
    const finalLocName = 构建移动绝对位置(snapshot, 目标短名, 父级.name);
    const 未解析文本 = Array.isArray(request.未解析角色) && request.未解析角色.length ? `；未解析同行角色：${request.未解析角色.join('、')}` : '';
    const patchOps = [
      {
        op: 'insert',
        path: `/world/动态地点/${targetPath}`,
        value: {
          归属父节点: 父级.name,
          描述: request.描述,
          x: 坐标.x,
          y: 坐标.y,
          状态: 'intact',
        },
      },
      ...构建移动角色位置补丁(request.角色列表, finalLocName, 坐标.x, 坐标.y),
      {
        op: 'replace',
        path: '/sys/系统播报',
        value: `[移动完成] ${request.角色} 经${最终移动请求.method}抵达 ${finalLocName}，耗时 ${最终移动请求.est_ticks} tick${未解析文本}。`,
      },
    ];
    const 消耗 = 最终移动请求.costs;
    if (消耗.coin > 0)
      patchOps.push({
        op: 'replace',
        path: `/char/${activePath}/财富/${escapeJsonPointerValue(消耗.currency)}`,
        value: Math.max(0, toNumber(request.charData?.财富?.[消耗.currency], 0) - 消耗.coin),
      });
    if (消耗.sp > 0)
      patchOps.push({
        op: 'replace',
        path: `/char/${activePath}/属性/魂力`,
        value: Math.max(0, toNumber(deepGet(request.charData, '属性.魂力', 0), 0) - 消耗.sp),
      });
    if (消耗.vit > 0)
      patchOps.push({
        op: 'replace',
        path: `/char/${activePath}/属性/体力`,
        value: Math.max(0, toNumber(deepGet(request.charData, '属性.体力', 0), 0) - 消耗.vit),
      });
    return { ok: true, patchOps, finalLocName, coord: 坐标, cost: 消耗, mapRequest: 最终移动请求 };
  }

  function 构建已有地点移动补丁(snapshot, request = {}, targetInfo = {}, travelPreview = {}) {
    if (!request || request.invalid)
      return { ok: false, reason: request?.reason || 'travel_request_invalid', patchOps: [] };
    const targetName = toText(targetInfo && targetInfo.name, toText(request.目标地点, ''));
    const parentName = 取移动目标父节点名(targetInfo, request);
    const finalLocName = 构建移动绝对位置(snapshot, targetName, parentName);
    const 当前所在 = 读取快照当前位置(snapshot);
    const 是层级切换 = 判断移动为层级切换(当前所在, finalLocName);
    const 预览请求 =
      !是层级切换 && travelPreview && travelPreview.request && typeof travelPreview.request === 'object' ? travelPreview.request : {};
    const 基础消耗 = Object.keys(预览请求).length || 是层级切换 ? null : 计算移动基础消耗(snapshot, request);
    if (基础消耗 && !基础消耗.ok) return { ok: false, reason: 基础消耗.reason || 'travel_cost_unavailable', patchOps: [] };
    const 目标坐标 = targetInfo && targetInfo.data && typeof targetInfo.data === 'object'
      ? {
        x: toNumber(targetInfo.data.x, NaN),
        y: toNumber(targetInfo.data.y, NaN),
      }
      : { x: NaN, y: NaN };
    const 当前坐标 = {
      x: toNumber(deepGet(request.charData, '状态.横坐标', -1), -1),
      y: toNumber(deepGet(request.charData, '状态.纵坐标', -1), -1),
    };
    const 层级切换耗时 = Math.max(0.1, Math.min(toNumber(request.耗时tick, 0.5), 0.5));
    const 原始地图请求 = Object.keys(预览请求).length ? 预览请求 : {
      method: request.移动方式,
      est_ticks: 是层级切换 ? 层级切换耗时 : request.耗时tick,
      est_duration: 是层级切换 ? 格式化tick时长文本_桥接(层级切换耗时) : 格式化tick时长文本_桥接(request.耗时tick),
      target_loc: targetInfo.name || request.目标地点,
      target_x: Number.isFinite(目标坐标.x) ? 目标坐标.x : 当前坐标.x,
      target_y: Number.isFinite(目标坐标.y) ? 目标坐标.y : 当前坐标.y,
      costs: {
        currency: 基础消耗 ? 基础消耗.货币 : '',
        coin: 基础消耗 ? 基础消耗.货币数 : 0,
        sp: 基础消耗 ? 基础消耗.魂力 : 0,
        vit: 基础消耗 ? 基础消耗.体力 : 0,
        canAfford: true,
        text: 基础消耗 ? 基础消耗.消耗文本 : '无额外消耗',
      },
    };
    const mapRequest = 应用旅行环境修正_桥接(request, 原始地图请求);
    if (mapRequest.costs && mapRequest.costs.canAfford === false) {
      return { ok: false, reason: toText(mapRequest.costs.reason, '资源不足，无法前往该节点。'), patchOps: [] };
    }
    const activePath = escapeJsonPointerValue(request.charKey);
    const targetX = Number.isFinite(toNumber(mapRequest.target_x, NaN))
      ? Math.round(toNumber(mapRequest.target_x, -1))
      : -1;
    const targetY = Number.isFinite(toNumber(mapRequest.target_y, NaN))
      ? Math.round(toNumber(mapRequest.target_y, -1))
      : -1;
    const 耗时tick = Math.max(0, toNumber(mapRequest.est_ticks, 0));
    const 出行方式 = toText(mapRequest.method, '步行');
    const 耗时文本 = toText(mapRequest.est_duration, 耗时tick > 0 ? `${耗时tick} tick` : '一段时间');
    const 未解析文本 = Array.isArray(request.未解析角色) && request.未解析角色.length ? `；未解析同行角色：${request.未解析角色.join('、')}` : '';
    const patchOps = [
      ...构建移动角色位置补丁(request.角色列表, finalLocName, targetX, targetY),
      {
        op: 'replace',
        path: '/sys/系统播报',
        value: `[地图移动完成] ${request.角色} 经${出行方式}抵达 ${finalLocName}，历时 ${耗时文本}${未解析文本}。`,
      },
    ];
    const costs = mapRequest.costs && typeof mapRequest.costs === 'object' ? mapRequest.costs : {};
    if (toNumber(costs.coin, 0) > 0)
      patchOps.push({
        op: 'replace',
        path: `/char/${activePath}/财富/${escapeJsonPointerValue(costs.currency)}`,
        value: Math.max(0, toNumber(request.charData?.财富?.[costs.currency], 0) - toNumber(costs.coin, 0)),
      });
    if (toNumber(costs.sp, 0) > 0)
      patchOps.push({
        op: 'replace',
        path: `/char/${activePath}/属性/魂力`,
        value: Math.max(0, toNumber(deepGet(request.charData, '属性.魂力', 0), 0) - toNumber(costs.sp, 0)),
      });
    if (toNumber(costs.vit, 0) > 0)
      patchOps.push({
        op: 'replace',
        path: `/char/${activePath}/属性/体力`,
        value: Math.max(0, toNumber(deepGet(request.charData, '属性.体力', 0), 0) - toNumber(costs.vit, 0)),
      });
    return { ok: true, patchOps, finalLocName, mapRequest, moveKind: 是层级切换 ? 'local_scope_shift' : 'travel' };
  }

  function 构建地图移动请求结算补丁(snapshot, request = {}, options = {}) {
    const 角色名 = toText(options.角色, toText(snapshot && snapshot.activeName, ''));
    const 角色解析 = 解析移动角色列表(snapshot, 角色名);
    const 角色 = 角色解析.角色列表[0];
    if (!角色 || !角色.key || !角色.char) return { ok: false, reason: 'travel_character_unresolved', patchOps: [], unresolvedCharacters: 角色解析.未解析角色 };
    const 原始地图请求 = request && typeof request === 'object' ? request : {};
    if (!Object.keys(原始地图请求).length) return { ok: false, reason: 'travel_request_missing', patchOps: [] };
    const mapRequest = 应用旅行环境修正_桥接({
      ...原始地图请求,
      charData: 角色.char,
      rootData: snapshot?.rootData || {},
    }, 原始地图请求);
    if (mapRequest.costs && mapRequest.costs.canAfford === false) {
      return { ok: false, reason: toText(mapRequest.costs.reason, '资源不足，无法前往该节点。'), patchOps: [] };
    }
    const activePath = escapeJsonPointerValue(角色.key);
    const 耗时tick = Math.max(0, toNumber(mapRequest.est_ticks, 0));
    const 出行方式 = toText(mapRequest.method, '步行');
    const 耗时文本 = toText(mapRequest.est_duration, 耗时tick > 0 ? `${耗时tick} tick` : '一段时间');
    const 最终位置 = toText(options.finalLocName, toText(mapRequest.target_loc, '未知地点'));
    const 目标显示名 = toText(options.移动显示目标, 最终位置);
    const 角色显示 = 角色解析.角色列表.map(项 => 项.displayName || 项.key).join('、');
    const 未解析文本 = 角色解析.未解析角色.length ? `；未解析同行角色：${角色解析.未解析角色.join('、')}` : '';
    const targetX = Number.isFinite(toNumber(mapRequest.target_x, NaN))
      ? Math.round(toNumber(mapRequest.target_x, -1))
      : -1;
    const targetY = Number.isFinite(toNumber(mapRequest.target_y, NaN))
      ? Math.round(toNumber(mapRequest.target_y, -1))
      : -1;
    const 地形名 = toText(options.terrainName, '');
    const patchOps = [
      ...构建移动角色位置补丁(角色解析.角色列表, 最终位置, targetX, targetY),
      {
        op: 'replace',
        path: '/sys/系统播报',
        value: `[地图移动完成] ${角色显示} 经${出行方式}抵达 ${目标显示名}${地形名 ? `（${地形名}）` : ''}，历时 ${耗时文本}${未解析文本}。`,
      },
    ];
    const costs = mapRequest.costs && typeof mapRequest.costs === 'object' ? mapRequest.costs : {};
    if (toNumber(costs.coin, 0) > 0)
      patchOps.push({
        op: 'replace',
        path: `/char/${activePath}/财富/${escapeJsonPointerValue(costs.currency)}`,
        value: Math.max(0, toNumber(角色.char?.财富?.[costs.currency], 0) - toNumber(costs.coin, 0)),
      });
    if (toNumber(costs.sp, 0) > 0)
      patchOps.push({
        op: 'replace',
        path: `/char/${activePath}/属性/魂力`,
        value: Math.max(0, toNumber(deepGet(角色.char, '属性.魂力', 0), 0) - toNumber(costs.sp, 0)),
      });
    if (toNumber(costs.vit, 0) > 0) {
      const 下一体力 = Math.max(0, toNumber(deepGet(角色.char, '属性.体力', 0), 0) - toNumber(costs.vit, 0));
      patchOps.push({ op: 'replace', path: `/char/${activePath}/属性/体力`, value: 下一体力 });
      if (下一体力 <= 1) {
        patchOps.push({
          op: 'replace',
          path: `/char/${activePath}/属性/状态效果/疲劳`,
          value: { 类型: 'debuff', 层数: 1, 描述: '长途跋涉导致极度疲劳' },
        });
      }
    }
    return { ok: true, patchOps, finalLocName: 最终位置, mapRequest, cost: costs };
  }

  async function 结算地图移动请求(detail = {}) {
    const snapshot = liveSnapshot && liveSnapshot.rootData ? liveSnapshot : await refreshLiveSnapshot({ force: true });
    if (!snapshot || !snapshot.rootData) return { ok: false, reason: 'snapshot_unavailable' };
    const request = detail && detail.request && typeof detail.request === 'object' ? detail.request : {};
    const contextResult = 读取世界动作上下文_桥接(snapshot, request, 'travel');
    if (!contextResult.ok) {
      return {
        ok: false,
        reason: contextResult.reason || 'world_action_blocked',
        worldContextProjection: 读取世界动作投影_桥接(contextResult.context),
      };
    }
    const contextualRequest = { ...request, 动作上下文: contextResult.context };
    const 补丁结果 = 构建地图移动请求结算补丁(snapshot, contextualRequest, detail);
    if (!补丁结果.ok || !补丁结果.patchOps.length) return 补丁结果;
    const 当前位置 = 读取快照当前位置(snapshot);
    if (
      toText(request.target_loc, '') !== '无' &&
      补丁结果.finalLocName &&
      当前位置 &&
      移动目标是否已到达(当前位置, 补丁结果.finalLocName)
    ) {
      return {
        ok: true,
        alreadyThere: true,
        patchOps: [],
        finalLocName: 补丁结果.finalLocName,
        request,
        worldContextProjection: 读取世界动作投影_桥接(contextResult.context),
      };
    }
    const 准入扣除 = 构建准入凭证扣除补丁_桥接(snapshot, contextResult.context);
    if (!准入扣除.ok) return { ok: false, reason: 准入扣除.reason || '准入凭证不足' };
    补丁结果.patchOps = [...准入扣除.patchOps, ...补丁结果.patchOps];
    await applyJsonPatchOpsByEditor(补丁结果.patchOps, { force: true });
    登记本轮移动结算路径(补丁结果.patchOps.map(patch => decodeJsonPointerPath(patch.path)).filter(path => path.length));
    await refreshLiveSnapshot({ force: true });
    return { ok: true, settled: true, ...补丁结果, worldContextProjection: 读取世界动作投影_桥接(contextResult.context) };
  }

  // options.dryRun：只构建补丁与消耗、不写回（座舱出发前预演用）
  async function 执行移动模块意图路由(snapshot, request = {}, options = {}) {
    if (!request || request.invalid)
      return 构建模块路由失败结果('travel', request, request?.reason || 'travel_request_invalid');
    const contextResult = 读取世界动作上下文_桥接(snapshot, request, 'travel');
    if (!contextResult.ok) {
      return 构建模块路由失败结果('travel', request, contextResult.reason || 'world_action_blocked', {
        worldContextProjection: 读取世界动作投影_桥接(contextResult.context),
      });
    }
    request = { ...request, 动作上下文: contextResult.context };
    const worldContextProjection = 读取世界动作投影_桥接(contextResult.context);
    const mapBridge = window.__sheepMapBridge;
    const 已有目标 = 解析移动已有地点目标(snapshot, request);
    const 当前所在 = 读取快照当前位置(snapshot);
    const 父级上下文 = 推导移动父级上下文(snapshot, request);
    const 已有目标父级 = 取移动目标父节点名(已有目标, { ...request, 归属父节点: 父级上下文 });
    if (已有目标.data && 当前所在 && 移动目标是否已到达(当前所在, 构建移动绝对位置(snapshot, 已有目标.name || request.目标地点, 已有目标父级))) {
      return 构建模块路由成功结果('travel', request, {
        dispatchMode: 'settled_summary',
        alreadyThere: true,
        patchOps: [],
        startLoc: 当前所在,
        finalLocName: 当前所在,
        worldContextProjection,
      });
    }
    if (已有目标.data) {
      let result = null;
      if (mapBridge && typeof mapBridge.describeTravelToNode === 'function') {
        const 候选节点名 = [已有目标.name, 取地点叶名(已有目标.name), request.目标地点]
          .map(名称 => toText(名称, '').trim())
          .filter(Boolean);
        for (const 节点名 of 候选节点名) {
          result = mapBridge.describeTravelToNode(节点名);
          if (result?.ok) break;
        }
      }
      if (result?.alreadyThere) {
        return 构建模块路由成功结果('travel', request, {
          dispatchMode: 'settled_summary',
          alreadyThere: true,
          patchOps: [],
          startLoc: 当前所在,
          finalLocName: 当前所在 || 构建移动绝对位置(snapshot, 已有目标.name || request.目标地点, 已有目标父级),
          result,
          worldContextProjection,
        });
      }
      const 补丁结果 = 构建已有地点移动补丁(snapshot, request, 已有目标, result);
      if (!补丁结果.ok || !补丁结果.patchOps.length) {
        return 构建模块路由失败结果('travel', request, 补丁结果.reason || 'travel_patch_unavailable', { result });
      }
      const 准入扣除 = 构建准入凭证扣除补丁_桥接(snapshot, contextResult.context);
      if (!准入扣除.ok) {
        return 构建模块路由失败结果('travel', request, 准入扣除.reason || '准入凭证不足', { result });
      }
      补丁结果.patchOps = [...准入扣除.patchOps, ...补丁结果.patchOps];
      if (options && options.dryRun) {
        return 构建模块路由成功结果('travel', request, {
          dryRun: true,
          patchOps: 补丁结果.patchOps,
          finalLocName: 补丁结果.finalLocName,
          cost: 补丁结果.cost || 补丁结果.mapRequest?.costs,
          durationText: 补丁结果.mapRequest?.est_duration,
          moveKind: 补丁结果.moveKind,
        });
      }
      try {
        await applyJsonPatchOpsByEditor(补丁结果.patchOps, { force: true });
        登记本轮移动结算路径(补丁结果.patchOps.map(patch => decodeJsonPointerPath(patch.path)).filter(path => path.length));
        await refreshLiveSnapshot({ force: true });
      } catch (error) {
        return 构建模块路由失败结果('travel', request, error && error.message ? error.message : 'travel_patch_failed', {
          result,
        });
      }
      return 构建模块路由成功结果('travel', request, {
        dispatchMode: 'settled_summary',
        patchOps: 补丁结果.patchOps,
        startLoc: 当前所在,
        finalLocName: 补丁结果.finalLocName,
        cost: 补丁结果.cost || 补丁结果.mapRequest?.costs,
        durationTicks: 补丁结果.mapRequest?.est_ticks,
        durationText: 补丁结果.mapRequest?.est_duration,
        moveKind: 补丁结果.moveKind,
        result,
        worldContextProjection,
      });
    }

    const 补丁结果 = 构建新动态地点移动补丁(snapshot, request);
    if (!补丁结果.ok || !补丁结果.patchOps.length) {
      if (['travel_parent_missing', 'travel_coord_unavailable', 'travel_target_already_exists'].includes(toText(补丁结果.reason, ''))) {
        return { handled: false, kind: 'travel', request, reason: 补丁结果.reason || 'travel_target_unresolved_technical' };
      }
      return 构建模块路由失败结果('travel', request, 补丁结果.reason || 'travel_patch_unavailable');
    }
    const 准入扣除 = 构建准入凭证扣除补丁_桥接(snapshot, contextResult.context);
    if (!准入扣除.ok) {
      return 构建模块路由失败结果('travel', request, 准入扣除.reason || '准入凭证不足');
    }
    补丁结果.patchOps = [...准入扣除.patchOps, ...补丁结果.patchOps];
    if (options && options.dryRun) {
      return 构建模块路由成功结果('travel', request, {
        dryRun: true,
        patchOps: 补丁结果.patchOps,
        finalLocName: 补丁结果.finalLocName,
        cost: 补丁结果.cost,
        durationText: 格式化tick时长文本_桥接(request.耗时tick),
      });
    }
    try {
      await applyJsonPatchOpsByEditor(补丁结果.patchOps, { force: true });
      登记本轮移动结算路径(补丁结果.patchOps.map(patch => decodeJsonPointerPath(patch.path)).filter(path => path.length));
      await refreshLiveSnapshot({ force: true });
    } catch (error) {
      return 构建模块路由失败结果('travel', request, error && error.message ? error.message : 'travel_patch_failed');
    }
    return 构建模块路由成功结果('travel', request, {
      dispatchMode: 'settled_summary',
      patchOps: 补丁结果.patchOps,
      startLoc: 当前所在,
      finalLocName: 补丁结果.finalLocName,
      cost: 补丁结果.cost,
      durationTicks: request.耗时tick,
      durationText: 格式化tick时长文本_桥接(request.耗时tick),
      coord: 补丁结果.coord,
      worldContextProjection,
    });
  }

  function 归一化日常动作模式(动作 = '', narrativeText = '') {
    const 匹配动作 = 文本 => {
      const 内容 = toText(文本, '');
      if (/探索|搜索|调查|侦察|勘察/.test(内容)) return '探索';
      if (/肉体训练|身体训练|体能训练|锻体|炼体/.test(内容)) return '肉体训练';
      if (/精神训练|精神修炼|精神锻炼|识海|紫极魔瞳/.test(内容)) return '精神训练';
      if (/冥想|修炼|打坐|凝聚魂核/.test(内容)) return '冥想';
      return '';
    };
    const 显式动作 = 匹配动作(动作);
    if (显式动作) return 显式动作;
    return 匹配动作(narrativeText);
  }

  function 读取日常动作候选列表(文本 = '') {
    const 内容 = toText(文本, '');
    return [
      [/探索|搜索|调查|侦察|勘察/, '探索'],
      [/肉体训练|身体训练|体能训练|锻体|炼体/, '肉体训练'],
      [/精神训练|精神修炼|精神锻炼|识海|紫极魔瞳/, '精神训练'],
      [/冥想|修炼|打坐|凝聚魂核/, '冥想'],
    ]
      .filter(([规则]) => 规则.test(内容))
      .map(([, 动作]) => 动作);
  }

  function 解析日常模块意图请求(snapshot, payload = {}, narrativeText = '') {
    const 动作文本 = toText(payload.动作 || payload.action || payload.模式 || payload.训练方式, '');
    if (读取日常动作候选列表(动作文本).length > 1) {
      return { ...payload, invalid: true, reason: 'routine_action_ambiguous', 动作: 动作文本 };
    }
    const 动作 = 归一化日常动作模式(动作文本, narrativeText);
    if (!动作) return null;
    const 角色 = toText(payload.角色 || payload.角色名 || payload.name, toText(snapshot && snapshot.activeName, ''));
    const 耗时tick = toNumber(payload.耗时tick ?? payload.durationTicks ?? payload.ticks, 0);
    return {
      难度: toNumber(payload.难度 ?? payload.difficulty, 0),
      线索: toText(payload.线索 || payload.情报 || payload.clue || payload.intel, ''),
      事务ID: toText(payload.事务ID || payload.transactionId || payload.transaction_id, ''),
      动作,
      角色,
      耗时tick,
      理由: toText(payload.理由, ''),
      位置: toText(payload.地点, 读取快照当前位置(snapshot)),
    };
  }

  function 读取日常结算接口() {
    const 运行时接口 = 读取MVUSchema运行时接口_桥接();
    return 运行时接口 && typeof 运行时接口.按动作模式结算变量根时间流逝 === 'function'
      ? 运行时接口.按动作模式结算变量根时间流逝
      : null;
  }

  function 计算日常数值变化(beforeChar = {}, afterChar = {}) {
    const beforeAttr = beforeChar?.属性 || {};
    const afterAttr = afterChar?.属性 || {};
    const parts = [];
    [
      ['魂力', '魂力'],
      ['魂力上限', '魂力上限'],
      ['精神力', '精神力'],
      ['精神力上限', '精神力上限'],
      ['体力', '体力'],
      ['体力上限', '体力上限'],
      ['HP', 'HP'],
      ['HP上限', 'HP上限'],
    ].forEach(([label, field]) => {
      const delta = Number(afterAttr[field] || 0) - Number(beforeAttr[field] || 0);
      if (Math.abs(delta) >= 0.0001) parts.push(`${label}${delta > 0 ? '+' : ''}${formatNumber(Number(delta.toFixed(4)))}`);
    });
    ['力量', '防御', '敏捷', '体力上限', '精神力上限'].forEach(field => {
      const delta = Number(afterAttr?.训练加成?.[field] || 0) - Number(beforeAttr?.训练加成?.[field] || 0);
      if (Math.abs(delta) >= 0.0001) parts.push(`${field}永久加成${delta > 0 ? '+' : ''}${formatNumber(Number(delta.toFixed(4)))}`);
    });
    const beforeCore = Number(beforeChar?.魂核?.核心?.进度 || 0);
    const afterCore = Number(afterChar?.魂核?.核心?.进度 || 0);
    const beforeCoreCount = Number(beforeChar?.魂核?.核心?.数量 || 0);
    const afterCoreCount = Number(afterChar?.魂核?.核心?.数量 || 0);
    if (afterCoreCount !== beforeCoreCount) parts.push(`魂核数量${afterCoreCount > beforeCoreCount ? '+' : ''}${afterCoreCount - beforeCoreCount}`);
    else if (Math.abs(afterCore - beforeCore) >= 0.0001) parts.push(`魂核进度${afterCore > beforeCore ? '+' : ''}${formatNumber(Number((afterCore - beforeCore).toFixed(4)))}`);
    return parts.join('，');
  }

  function 计算探索结算结果_桥接(charData = {}, request = {}, context = {}) {
    const 属性 = charData && typeof charData === 'object' ? charData.属性 || {} : {};
    const 等级 = Math.max(1, toNumber(属性.等级, 1));
    const 精神上限 = Math.max(1, toNumber(属性.精神力上限, 1));
    const 精神状态 = Math.max(0, Math.min(1, toNumber(属性.精神力, 精神上限) / 精神上限));
    const 有效能力 = Math.max(1, 等级 * (0.75 + 精神状态 * 0.25));
    const 标准难度 = Math.max(1, Math.min(1000, toNumber(request.难度, context?.modifiers?.探索?.标准难度 || 30)));
    const 成功率 = Math.max(0.1, Math.min(0.9, 有效能力 / (有效能力 + 标准难度)));
    const 地点键 = context?.location?.active?.path?.join('-') || request.地点 || request.位置 || '';
    const 事务键 = toText(request.事务ID, '').trim() || [
      charData?.身份 || charData?.姓名 || '',
      地点键,
      request.线索 || '',
      context?.time?.tick ?? '',
      request.耗时tick ?? '',
    ].join('|');
    const 成功 = 读取稳定随机数_桥接(`explore|${事务键}`) < 成功率;
    return {
      成功,
      情报: 成功 ? toText(request.线索, '').trim() : '',
    };
  }

  const 日常动作允许写回角色字段 = Object.freeze(['属性', '魂核', '状态', '财富', '我的任务', '已掌握情报']);

  function 构建日常动作字段级写回补丁(charKey = '', settledRoot = {}, options = {}) {
    const 角色名 = toText(charKey, '').trim();
    if (!角色名) throw new Error('routine_character_missing');
    const afterChar = deepGet(settledRoot, ['char', 角色名], null);
    if (!afterChar || typeof afterChar !== 'object' || Array.isArray(afterChar)) throw new Error('routine_result_missing');
    const activePath = escapeJsonPointerValue(角色名);
    const patches = [];
    日常动作允许写回角色字段.forEach(字段 => {
      if (afterChar[字段] !== undefined) {
        patches.push({
          op: 'replace',
          path: `/char/${activePath}/${escapeJsonPointerValue(字段)}`,
          value: cloneJsonValue(afterChar[字段], {}),
        });
      }
    });
    const systemText = toText(
      options.systemText !== undefined ? options.systemText : deepGet(settledRoot, 'sys.系统播报', ''),
      '',
    ).trim();
    if (systemText && systemText !== '初始化') patches.push({ op: 'replace', path: '/sys/系统播报', value: systemText });
    return patches;
  }

  function 构建日常结算临时根(snapshot = {}, charKey = '', charData = {}, request = {}) {
    const rootData = cloneJsonValue(deepGet(snapshot, 'rootData', {}), {});
    const 当前tick = Math.max(0, Math.round(toNumber(deepGet(rootData, 'world.时间.tick', 0), 0) * 10) / 10);
    const 耗时tick = Math.max(0, Math.round(toNumber(request && request.耗时tick, 0) * 10) / 10);
    const 临时根 = cloneJsonValue(rootData, {});
    临时根.char = { [charKey]: cloneJsonValue(charData, {}) };
    if (!临时根.world || typeof 临时根.world !== 'object' || Array.isArray(临时根.world)) 临时根.world = {};
    if (!临时根.world.时间 || typeof 临时根.world.时间 !== 'object' || Array.isArray(临时根.world.时间)) 临时根.world.时间 = {};
    临时根.world.时间.tick = 当前tick + 耗时tick;
    临时根.world.时间._上次结算tick = 当前tick;
    return { 临时根, 当前tick, 结束tick: 当前tick + 耗时tick };
  }

  function 日常动作资源足够(charData = {}, actionMode = '') {
    const 属性 = charData && typeof charData === 'object' ? charData.属性 || {} : {};
    if (actionMode === '肉体训练') return Number(属性.体力 || 0) >= Math.max(1, Number(属性.体力上限 || 1)) * 0.3;
    if (actionMode === '精神训练') return Number(属性.精神力 || 0) > Math.max(1, Number(属性.精神力上限 || 1)) * 0.1;
    return true;
  }

  function 读取日常动作恢复模式(actionMode = '') {
    if (actionMode === '肉体训练') return '睡眠';
    if (actionMode === '精神训练') return '冥想';
    return actionMode || '冥想';
  }

  async function 分段执行日常结算(settleRuntime, snapshot = {}, charKey = '', beforeChar = {}, request = {}) {
    const actionMode = toText(request && request.动作, '');
    const durationTicks = Math.max(0, Math.round(toNumber(request && request.耗时tick, 0) * 10) / 10);
    const { 临时根, 当前tick } = 构建日常结算临时根(snapshot, charKey, beforeChar, { ...request, 耗时tick: 0 });
    const equipmentPassive = typeof window?.EquipmentManager?.结算装备被动战斗外效果 === 'function'
      ? await window.EquipmentManager.结算装备被动战斗外效果(临时根, charKey, 当前tick, [])
      : null;
    let cursor = 当前tick;
    let remaining = durationTicks;
    let actionTicks = 0;
    let recoveryTicks = 0;
    while (remaining > 0) {
      const currentChar = deepGet(临时根, ['char', charKey], {});
      const shouldRecover = actionMode !== '冥想' && !日常动作资源足够(currentChar, actionMode);
      const mode = shouldRecover ? 读取日常动作恢复模式(actionMode) : actionMode;
      const segment = actionMode === '冥想' ? remaining : Math.min(remaining, 6);
      const settled = settleRuntime(临时根, charKey, cursor, cursor + segment, mode, {
        动作上下文: request.动作上下文,
      });
      Object.keys(临时根).forEach(key => delete 临时根[key]);
      Object.assign(临时根, settled);
      cursor += segment;
      remaining -= segment;
      if (shouldRecover) recoveryTicks += segment;
      else actionTicks += segment;
    }
    if (!临时根.world || typeof 临时根.world !== 'object' || Array.isArray(临时根.world)) 临时根.world = {};
    if (!临时根.world.时间 || typeof 临时根.world.时间 !== 'object' || Array.isArray(临时根.world.时间)) 临时根.world.时间 = {};
    临时根.world.时间.tick = 当前tick + durationTicks;
    临时根.world.时间._上次结算tick = 当前tick;
    return { settledRoot: 临时根, 当前tick, 结束tick: 当前tick + durationTicks, actionTicks, recoveryTicks, equipmentPassive };
  }

  async function 执行日常模块真实结算(snapshot = {}, request = {}) {
    if (request && request.invalid) return 构建模块路由失败结果('routine', request, request.reason || 'routine_request_invalid');
    const charKey = resolveSnapshotCharKey(snapshot, toText(request && request.角色, toText(snapshot && snapshot.activeName, '')));
    if (!charKey) return 构建模块路由失败结果('routine', request, 'active_character_unresolved');
    const actionMode = 归一化日常动作模式(request && request.动作, '');
    if (!actionMode) return 构建模块路由失败结果('routine', request, 'routine_action_invalid', { charName: charKey });
    const durationTicks = Math.max(0, Math.round(toNumber(request && request.耗时tick, 0) * 10) / 10);
    if (!(durationTicks > 0)) return 构建模块路由失败结果('routine', request, 'routine_duration_missing', { charName: charKey, actionMode });
    const settleRuntime = 读取日常结算接口();
    if (typeof settleRuntime !== 'function') return 构建模块路由失败结果('routine', request, 'routine_runtime_unavailable', { charName: charKey, actionMode, durationTicks });
    const beforeChar = cloneJsonValue(deepGet(snapshot, ['rootData', 'char', charKey], {}), {});
    if (!beforeChar || !Object.keys(beforeChar).length) return 构建模块路由失败结果('routine', request, 'routine_character_missing', { charName: charKey, actionMode, durationTicks });
    const contextResult = 读取世界动作上下文_桥接(
      snapshot,
      { ...request, 角色: charKey, 动作: actionMode, 耗时tick: durationTicks },
      `routine|${actionMode}`,
    );
    if (!contextResult.ok) {
      return 构建模块路由失败结果('routine', request, contextResult.reason || 'world_action_blocked', {
        charName: charKey,
        actionMode,
        durationTicks,
        worldContextProjection: 读取世界动作投影_桥接(contextResult.context),
      });
    }
    const actionRequest = { ...request, 角色: charKey, 动作: actionMode, 耗时tick: durationTicks, 动作上下文: contextResult.context };
    let segmentStats = null;
    let settledRoot = null;
    try {
      segmentStats = await 分段执行日常结算(settleRuntime, snapshot, charKey, beforeChar, actionRequest);
      settledRoot = segmentStats.settledRoot;
    } catch (error) {
      console.error('[LWCS routine settle failed]', {
        charName: charKey,
        actionMode,
        durationTicks,
        error,
      });
      return 构建模块路由失败结果('routine', request, error && error.message ? error.message : 'routine_runtime_failed', {
        charName: charKey,
        actionMode,
        durationTicks,
        errorStack: error && error.stack ? String(error.stack) : '',
      });
    }
    let afterChar = cloneJsonValue(deepGet(settledRoot, ['char', charKey], null), null);
    if (!afterChar) return 构建模块路由失败结果('routine', request, 'routine_result_missing', { charName: charKey, actionMode, durationTicks });
    const exploration = actionMode === '探索' ? 计算探索结算结果_桥接(beforeChar, actionRequest, contextResult.context) : null;
    if (exploration?.成功 && exploration.情报) {
      const intel = Array.isArray(settledRoot.char[charKey].已掌握情报) ? settledRoot.char[charKey].已掌握情报 : [];
      if (!intel.some(item => toText(item, '').trim() === exploration.情报)) intel.push(exploration.情报);
      settledRoot.char[charKey].已掌握情报 = intel;
      afterChar = cloneJsonValue(deepGet(settledRoot, ['char', charKey], null), null);
    }
    const systemText = toText(deepGet(settledRoot, 'sys.系统播报', ''), '').trim();
    const patches = 构建日常动作字段级写回补丁(charKey, settledRoot, { systemText });
    await applyJsonPatchOpsByEditor(patches, { force: true, 记录本轮模块结算路径: true, 结算类型: 'routine' });
    await refreshLiveSnapshot({ force: true });
    return 构建模块路由成功结果('routine', actionRequest, {
      dispatchMode: 'settled_summary',
      patchOps: patches,
      charName: charKey,
      actionMode,
      durationTicks,
      durationText: 格式化tick时长文本_桥接(durationTicks),
      location: toText(request && request.位置, toText(beforeChar?.状态?.位置, '')),
      worldContextProjection: 读取世界动作投影_桥接(contextResult.context),
      explorationSuccess: exploration?.成功 === true,
      equipmentPassive: segmentStats?.equipmentPassive
        ? {
            routeCount: Number(segmentStats.equipmentPassive.路由数 || 0),
            appliedCount: Number(segmentStats.equipmentPassive.已结算数 || 0),
            skippedCount: Number(segmentStats.equipmentPassive.跳过路由数 || 0),
          }
        : null,
      summary: [
        计算日常数值变化(beforeChar, afterChar),
        segmentStats?.recoveryTicks > 0 ? `其中恢复${格式化tick时长文本_桥接(segmentStats.recoveryTicks)}` : '',
        exploration ? (exploration.成功 ? (exploration.情报 ? '探索获得新情报' : '探索完成') : '探索未发现新情报') : '',
      ].filter(Boolean).join('，'),
    });
  }

  function 解析试炼入场意图请求(snapshot, payload = {}, kind = '', narrativeText = '') {
    const 动作文本 = toText(
      payload.action ||
        payload.动作 ||
        payload.action_type ||
        payload.module ||
        payload.type ||
        payload.kind ||
        payload.requestKind ||
        payload.request_kind ||
        payload.试炼类型 ||
        payload.trialType ||
        payload.trial,
      '',
    ).toLowerCase();
    const 试炼类型文本 = toText(payload.试炼类型 || payload.trialType || payload.trial, '').toLowerCase();
    const 识别文本 =
      `${toText(kind, '').toLowerCase()}|${动作文本}|${试炼类型文本}|${toText(narrativeText, '').toLowerCase()}`.trim();
    let 试炼类型 = '';
    if (/tower|魂灵塔/.test(识别文本)) 试炼类型 = '魂灵塔';
    else if (/ascension|升灵台/.test(识别文本)) 试炼类型 = '升灵台';
    if (!试炼类型) return null;

    const 当前地点 = toText(
      payload.currentLoc ||
        payload.current_loc ||
        payload.location ||
        payload.entryLocation ||
        payload.entry_location ||
        payload.targetLocation,
      toText(deepGet(snapshot, 'activeChar.状态.位置', snapshot.currentLoc), snapshot.currentLoc),
    );
    const 读取门票名称 = 默认门票 =>
      toText(
        payload.ticketName ||
          payload.ticket_name ||
          payload.ascensionTicket ||
          payload.ascension_ticket ||
          payload.soulTowerTicket ||
          payload.soul_tower_ticket ||
          payload.ticket ||
          payload.门票名,
        默认门票 || '',
      ).trim();
    if (试炼类型 === '升灵台') {
      const 可用门票 = listAscensionTicketNames(snapshot);
      const ticketName = 读取门票名称(可用门票[0] || '');
      return {
        试炼类型,
        ticketName,
        entryLocation: 当前地点,
      };
    }

    const 可用门票 = listSoulTowerTicketNames(snapshot);
    const ticketName = 读取门票名称(可用门票[0] || '');
    const 文本层数匹配 = toText(narrativeText, '').match(/第\s*(\d+)\s*层/);
    const 文本层数 = 文本层数匹配 ? toNumber(文本层数匹配[1], 0) : 0;
    return {
      试炼类型,
      ticketName,
      floor: Math.max(
        1,
        Math.floor(
          toNumber(
            payload.floor || payload.层数 || payload.layer || 文本层数,
            getDefaultSoulTowerChallengeFloor(snapshot),
          ),
        ),
      ),
      entryLocation: 当前地点,
    };
  }


  async function 执行模块路由队列(moduleQueue = [], options = {}) {
    const 队列 = (Array.isArray(moduleQueue) ? moduleQueue : []).filter(item => item && typeof item === 'object');
    const 结果列表 = [];
    for (const item of 队列) {
      const result = await routeModuleIntentPayload(item, options);
      结果列表.push(result);
      登记模块结果动作角色_桥接(result, options);
      const 失败 = !result?.handled || result.dispatchMode === 'failed_summary' || /状态：执行失败/.test(toText(result.runtimeEvent, ''));
      if (失败) break;
      if (!(result?.dryRun === true || result?.dispatchMode === 'settled_summary')) break;
      if (!(options && options.dryRun === true)) await refreshLiveSnapshot({ force: true });
    }
    const runtimeEvent = 结果列表.map(result => toText(result && result.runtimeEvent, '').trim()).filter(Boolean).join('\n');
    return {
      handled: 结果列表.some(result => result && result.handled),
      kind: 'module_queue',
      results: 结果列表,
      runtimeEvent,
      dispatchMode: 结果列表.some(result => result?.dispatchMode === 'failed_summary') ? 'failed_summary' : 'settled_summary',
    };
  }

  async function routeModuleIntentPayload(input, options = {}) {
    const snapshot = liveSnapshot || lastRenderableSnapshot;
    const { payload, text, kind } = resolveModuleIntentPayload(input);
    if (!snapshot || !snapshot.rootData) return { handled: false, reason: 'snapshot_unavailable' };
    if (Array.isArray(payload.moduleQueue) && payload.moduleQueue.length) return 执行模块路由队列(payload.moduleQueue, options);

    const dryRun = options.dryRun === true || payload.dryRun === true;
    let moduleKind = '';
    let request = null;

    if (归一化模块意图类型(kind) === 'time_advance') {
      const 时间推进上下文 = payload.时间推进上下文 || payload.timeAdvanceContext || options.时间推进上下文;
      if (dryRun) {
        return 构建模块路由成功结果('time_advance', 时间推进上下文 || {}, {
          dryRun: true,
          dispatchMode: 'settled_summary',
        });
      }
      const result = await Promise.resolve(暂存任务时间推进_桥接(时间推进上下文, options));
      return result?.ok
        ? 构建模块路由成功结果('time_advance', 时间推进上下文 || {}, {
            dispatchMode: 'settled_summary',
            result,
          })
        : 构建模块路由失败结果('time_advance', 时间推进上下文 || {}, result?.reason || 'time_advance_stage_failed', { result });
    }

    if (归一化模块意图类型(kind) === '未命中') {
      return 构建模块路由成功结果('未命中', payload && typeof payload === 'object' ? payload : {}, {
        dryRun,
        skipped: true,
        reason: 'no_special_module_hit',
      });
    }

    const 原始试炼识别文本 = `${kind}|${text}|${JSON.stringify(payload || {})}`.toLowerCase();
    if (/trial_entry|trial|升灵台|魂灵塔|试炼/.test(原始试炼识别文本)) {
      const 当前地点 = toText(
        payload.currentLoc ||
          payload.current_loc ||
          payload.location ||
          payload.entryLocation ||
          payload.entry_location ||
          payload.targetLocation,
        toText(deepGet(snapshot, 'activeChar.状态.位置', snapshot.currentLoc), snapshot.currentLoc),
      );
      if (/tower|魂灵塔/.test(原始试炼识别文本)) {
        const 可用门票 = listSoulTowerTicketNames(snapshot);
        request = {
          试炼类型: '魂灵塔',
          ticketName: toText(
            payload.ticketName ||
              payload.ticket_name ||
              payload.soulTowerTicket ||
              payload.soul_tower_ticket ||
              payload.ticket ||
              payload.门票名,
            可用门票[0] || '',
          ).trim(),
          floor: Math.max(
            1,
            Math.floor(
              toNumber(payload.floor || payload.层数 || payload.layer, getDefaultSoulTowerChallengeFloor(snapshot)),
            ),
          ),
          entryLocation: 当前地点,
        };
        moduleKind = 'trial_entry';
      } else if (/ascension|升灵台/.test(原始试炼识别文本)) {
        const 可用门票 = listAscensionTicketNames(snapshot);
        request = {
          试炼类型: '升灵台',
          ticketName: toText(
            payload.ticketName ||
              payload.ticket_name ||
              payload.ascensionTicket ||
              payload.ascension_ticket ||
              payload.ticket ||
              payload.门票名,
            可用门票[0] || '',
          ).trim(),
          entryLocation: 当前地点,
        };
        moduleKind = 'trial_entry';
      }
    }

    const 试炼请求 = 解析试炼入场意图请求(snapshot, payload, kind, text);
    if (!request && 试炼请求) {
      request = 试炼请求;
      moduleKind = 'trial_entry';
    } else if (!moduleKind) {
      moduleKind = 归一化模块意图类型(kind);
    }

    if (moduleKind === 'trial_entry' && !request) {
      request = 解析试炼入场意图请求(snapshot, payload, 'trial_entry', text);
      if (!request) {
        const 试炼识别文本 = `${kind}|${text}|${JSON.stringify(payload || {})}`.toLowerCase();
        const 当前地点 = toText(
          payload.currentLoc ||
            payload.current_loc ||
            payload.location ||
            payload.entryLocation ||
            payload.entry_location ||
            payload.targetLocation,
          toText(deepGet(snapshot, 'activeChar.状态.位置', snapshot.currentLoc), snapshot.currentLoc),
        );
        if (/tower|魂灵塔/.test(试炼识别文本)) {
          const 可用门票 = listSoulTowerTicketNames(snapshot);
          request = {
            试炼类型: '魂灵塔',
            ticketName: toText(
              payload.ticketName ||
                payload.ticket_name ||
                payload.soulTowerTicket ||
                payload.soul_tower_ticket ||
                payload.ticket ||
                payload.门票名,
              可用门票[0] || '',
            ).trim(),
            floor: Math.max(
              1,
              Math.floor(
                toNumber(payload.floor || payload.层数 || payload.layer, getDefaultSoulTowerChallengeFloor(snapshot)),
              ),
            ),
            entryLocation: 当前地点,
          };
        } else if (/ascension|升灵台/.test(试炼识别文本)) {
          const 可用门票 = listAscensionTicketNames(snapshot);
          request = {
            试炼类型: '升灵台',
            ticketName: toText(
              payload.ticketName ||
                payload.ticket_name ||
                payload.ascensionTicket ||
                payload.ascension_ticket ||
                payload.ticket ||
                payload.门票名,
              可用门票[0] || '',
            ).trim(),
            entryLocation: 当前地点,
          };
        }
      }
    }

    if (moduleKind === 'battle') {
      const trialContext = 读取试炼状态上下文(snapshot);
      const 允许撤离值 = 解析模块路由布尔值(payload.允许撤离);
      const 自动模式值 = 解析模块路由布尔值(payload.自动模式);
      const 胜负条件已结构化 = !!(
        payload.胜负条件 && typeof payload.胜负条件 === 'object' &&
        Array.isArray(payload.胜负条件?.victory?.conditions || payload.胜负条件?.胜利?.条件) &&
        (payload.胜负条件?.victory?.conditions || payload.胜负条件?.胜利?.条件).length > 0 &&
        Array.isArray(payload.胜负条件?.defeat?.conditions || payload.胜负条件?.失败?.条件) &&
        (payload.胜负条件?.defeat?.conditions || payload.胜负条件?.失败?.条件).length > 0 &&
        Number(payload.胜负条件?.maxRounds ?? payload.胜负条件?.回合上限) > 0 &&
        Number(payload.胜负条件?.maxRounds ?? payload.胜负条件?.回合上限) <= 20
      );
      const 胜负条件字段完整 = 胜负条件已结构化 || (
        战斗条件输入存在(payload.胜利条件) &&
        战斗条件输入存在(payload.失败条件) &&
        读取模块路由最大回合(payload) > 0 && 读取模块路由最大回合(payload) <= 20
      );
      if (deepGet(snapshot, 'rootData.world.战斗.进行中', false)) {
        request = {};
      } else if (
        !trialContext &&
        (!payload.参战者 ||
          typeof payload.参战者 !== 'object' ||
          !Array.isArray(payload.参战者.team_player) ||
          !Array.isArray(payload.参战者.team_enemy) ||
          payload.参战者.team_enemy.length < 1 ||
          typeof 允许撤离值 !== 'boolean')
      ) {
        return 构建模块路由失败结果(moduleKind, payload, 'battle_seed_invalid');
      }
      if (!deepGet(snapshot, 'rootData.world.战斗.进行中', false) && !trialContext && !胜负条件字段完整) {
        return 构建模块路由失败结果(moduleKind, payload, 'battle_objectives_missing');
      }
      if (!request && trialContext) {
        const 指定层数 = Math.max(0, Math.floor(toNumber(payload.floor, 0)));
        request = buildTrialBattleDispatchDetail(
          snapshot,
          {
            source: toText(payload.source, 'module_intent_router_trial'),
            ...(payload.参战者 && typeof payload.参战者 === 'object' ? { 参战者: cloneJsonValue(payload.参战者, {}) } : {}),
            ...(指定层数 > 0 ? { floor: 指定层数 } : {}),
            ...(胜负条件已结构化 ? { 胜负条件: cloneJsonValue(payload.胜负条件, {}) } : {}),
            ...(战斗条件输入存在(payload.胜利条件) ? { 胜利条件: 克隆战斗条件输入(payload.胜利条件) } : {}),
            ...(战斗条件输入存在(payload.失败条件) ? { 失败条件: 克隆战斗条件输入(payload.失败条件) } : {}),
            ...(toText(payload.胜利条件关系, '').trim() ? { 胜利条件关系: toText(payload.胜利条件关系, '') } : {}),
            ...(toText(payload.失败条件关系, '').trim() ? { 失败条件关系: toText(payload.失败条件关系, '') } : {}),
            ...(读取模块路由最大回合(payload) > 0 ? { 最大回合: Math.floor(读取模块路由最大回合(payload)) } : {}),
          },
          trialContext,
        );
        if (request && request.invalid) {
          return 构建模块路由失败结果(moduleKind, request, request.reason || 'battle_seed_invalid');
        }
      }
      if (!request) {
        const explicitParticipants =
          payload.参战者 && typeof payload.参战者 === 'object' ? cloneJsonValue(payload.参战者, {}) : null;
        if (explicitParticipants) {
          request = {
            action: 'battle',
            target: toText(
              payload.location || payload.targetLocation || payload.arena || payload.target,
              findBracketLocationToken(snapshot, text),
            ),
            currentLoc: toText(payload.currentLoc || payload.location, toText(snapshot && snapshot.currentLoc, '')),
            // 战斗类型简化: as written (战斗类型原文), read as one of three when the battle module is already loaded
            // (buildMapBattleCombatData reads it again); nothing written, 实战 there. The old 死战: no way out.
            战斗类型: 读取开战战斗类型_桥接(payload.战斗类型 || payload.combatType).类型,
            ...(toText(payload.战斗类型 || payload.combatType, '').trim()
              ? { 战斗类型原文: toText(payload.战斗类型 || payload.combatType, '').trim() } : {}),
            source: toText(payload.source, 'module_intent_router'),
            允许撤离: 读取开战战斗类型_桥接(payload.战斗类型 || payload.combatType).不许撤离 ? false
              : typeof 允许撤离值 === 'boolean' ? 允许撤离值 : true,
            自动模式: typeof 自动模式值 === 'boolean' ? 自动模式值 : undefined,
            参战者: explicitParticipants,
            ...(胜负条件已结构化 ? { 胜负条件: cloneJsonValue(payload.胜负条件, {}) } : {}),
            胜利条件: 克隆战斗条件输入(payload.胜利条件),
            失败条件: 克隆战斗条件输入(payload.失败条件),
            胜利条件关系: toText(payload.胜利条件关系, 'OR'),
            失败条件关系: toText(payload.失败条件关系, 'OR'),
            最大回合: Math.max(1, Math.min(20, Math.floor(toNumber(payload.最大回合 ?? payload.回合上限, 20)))),
            // 接战链 阶段三: "裁判：角色名" or "裁判：名称|等级=60" (解析模块路由裁判); none given, no referee.
            ...(解析模块路由裁判(payload.裁判) ? { 裁判: 解析模块路由裁判(payload.裁判) } : {}),
          };
        }
      }
      if (request && typeof 自动模式值 === 'boolean') request.自动模式 = 自动模式值;
    } else if (moduleKind === 'trade') {
      request = buildTradeRequestFromObject(snapshot, payload);
    } else if (moduleKind === 'profession') {
      request = buildDirectProfessionRequest(snapshot, payload);
    } else if (moduleKind === 'teaching') {
      request = 解析传授模块意图请求(snapshot, payload);
    } else if (moduleKind === 'skill_gain') {
      request = 解析新技能获得模块意图请求(snapshot, payload);
    } else if (moduleKind === 'travel') {
      request = 解析移动模块意图请求(snapshot, payload, text);
      const 任务时间tick = 读取任务时间推进tick_桥接(options);
      if (request && 任务时间tick > 0) request.耗时tick = 任务时间tick;
    } else if (moduleKind === 'routine') {
      request = 解析日常模块意图请求(snapshot, payload, text);
      const 任务时间tick = 读取任务时间推进tick_桥接(options);
      if (request && 任务时间tick > 0) request.耗时tick = 任务时间tick;
    } else if (moduleKind === 'trial_entry') {
      request = request || 解析试炼入场意图请求(snapshot, payload, kind, text);
    } else {
      request = null;
      moduleKind = '';
    }

    if (!moduleKind) return { handled: false, reason: 'no_module_intent' };
    if (!request) {
      const 请求缺失原因 =
        {
          battle: 'battle_request_invalid',
          trade: 'trade_request_invalid',
          profession: 'profession_request_invalid',
          teaching: 'teaching_request_invalid',
          skill_gain: 'skill_gain_request_invalid',
          travel: 'travel_request_invalid',
          routine: 'routine_request_invalid',
          trial_entry: 'trial_entry_request_invalid',
        }[moduleKind] || 'module_request_invalid';
      return 构建模块路由失败结果(
        moduleKind,
        payload && typeof payload === 'object' ? payload : {},
        请求缺失原因,
      );
    }
    if (['travel', 'routine'].includes(moduleKind) && 读取任务时间推进tick_桥接(options) <= 0) {
      return 构建模块路由失败结果(moduleKind, request, 'time_advance_missing');
    }
    const 战斗提交模式 =
      moduleKind === 'battle'
        ? request && request.自动模式 === true
          ? 'auto'
          : request && request.自动模式 === false
            ? 'manual'
            : 读取战斗提交模式()
        : '';
    if (dryRun) return { handled: true, dryRun: true, kind: moduleKind, request };

    if (moduleKind === 'trial_entry') {
      let result = null;
      try {
        result = await 登记试炼入场并推进剧情(snapshot, { ...(request || {}), 跳过正文派发: true });
      } catch (error) {
        return 构建模块路由失败结果(moduleKind, request, error && error.message ? error.message : 'trial_entry_failed');
      }
      await refreshLiveSnapshot({ force: true });
      return 构建模块路由成功结果(moduleKind, request, {
        dispatchMode: 'settled_summary',
        result,
        trialLocation: result && result.trialLocation,
      });
    }

    if (moduleKind === 'battle') {
      if (战斗提交模式 === 'free_narrative') {
        return 构建模块路由成功结果(moduleKind, request, {
          dispatchMode: 'settled_summary',
          skipped: true,
          reason: 'battle_free_narrative',
        });
      }
      if (战斗提交模式 === 'auto') {
        const result = await 自动执行战斗模块路由(snapshot, request);
        if (!result?.ok) {
          if (result?.已接管) {
            showUiToast(`自动战斗失败：${result.reason || 'battle_auto_failed'}`, 'error', 4200);
            return 构建模块路由成功结果(moduleKind, request, {
              dispatchMode: 'battle_auto_failed_after_takeover',
              reason: result.reason || 'battle_auto_failed',
              result,
              worldContextProjection: result?.worldContextProjection || '',
            });
          }
          return 构建模块路由失败结果(moduleKind, request, result?.reason || 'battle_auto_failed', { result });
        }
        return 构建模块路由成功结果(moduleKind, request, {
          dispatchMode: 'battle_auto_arbitration',
          result,
          worldContextProjection: result?.worldContextProjection || '',
        });
      }
      跳过战斗终端自动挂载 = false;
      if (deepGet(snapshot, 'rootData.world.战斗.进行中', false)) {
        await refreshLiveSnapshot({ force: true, reopenBattle: true });
        return 构建模块路由成功结果(moduleKind, request || {}, {
          dispatchMode: 'battle_continuation',
          reason: 'battle_continuation',
        });
      }
      let result = await openMapBattleModule(snapshot, request);
      if (!result?.ok && result?.reason === 'combat_context_unresolved') {
        await refreshLiveSnapshot({ force: true });
        result = await openMapBattleModule(liveSnapshot || lastRenderableSnapshot || snapshot, request);
      }
      if (!result?.ok) {
        return 构建模块路由失败结果(moduleKind, request, result?.reason || 'battle_open_failed', { result });
      }
      return 构建模块路由成功结果(moduleKind, request, {
        dispatchMode: 'battle_takeover',
        result,
        worldContextProjection: result?.worldContextProjection || '',
      });
    }

    if (moduleKind === 'trade') {
      const privateTradeNpc = toText(request && request.对象, '');
      if (privateTradeNpc && !resolveSnapshotCharKey(snapshot, privateTradeNpc)) {
        return 构建模块路由失败结果(moduleKind, request, 'trade_target_unresolved');
      }
      return 执行交易预填路由(snapshot, request);
    }

    if (moduleKind === 'travel') {
      return await 执行移动模块意图路由(snapshot, request);
    }

    if (moduleKind === 'teaching') {
      return await 执行传授模块意图路由(snapshot, request);
    }

    if (moduleKind === 'skill_gain') {
      return await 执行新技能获得模块意图路由(snapshot, request);
    }

    if (moduleKind === 'routine') {
      return await 执行日常模块真实结算(snapshot, request);
    }

    return 执行副职业工坊打开路由(snapshot, request);
  }

  function 登记模块结果动作角色_桥接(路由结果 = {}, options = {}) {
    const 动作模式表 = {};
    const snapshot = liveSnapshot || lastRenderableSnapshot;
    const 登记角色 = (候选, 模式) => {
      const 原名 = toText(候选?.key || 候选?.charKey || 候选?.name || 候选?.名称 || 候选?.角色 || 候选, '').trim();
      if (!原名) return;
      const 规范名 = resolveSnapshotCharKey(snapshot, 原名) || 原名;
      if (snapshot?.rootData?.char?.[规范名]) 动作模式表[规范名] = 模式;
    };
    const 登记请求 = (请求 = {}, 模式 = '') => {
      if (!请求 || typeof 请求 !== 'object' || Array.isArray(请求)) return;
      登记角色(请求.charKey || 请求.角色名 || 请求.角色, 模式);
      (Array.isArray(请求.角色列表) ? 请求.角色列表 : []).forEach(角色 => 登记角色(角色, 模式));
      const 参战者 = 请求.参战者 && typeof 请求.参战者 === 'object' && !Array.isArray(请求.参战者) ? 请求.参战者 : {};
      Object.values(参战者).forEach(队伍 => (Array.isArray(队伍) ? 队伍 : []).forEach(角色 => 登记角色(角色, 模式)));
    };
    const 遍历结果 = 结果 => {
      if (!结果 || typeof 结果 !== 'object' || Array.isArray(结果)) return;
      if (结果.kind === 'module_queue') {
        (Array.isArray(结果.results) ? 结果.results : []).forEach(遍历结果);
        return;
      }
      const 模式 = toText(结果.kind, '').trim();
      const 成功 = 结果.handled === true
        && 结果.dispatchMode !== 'failed_summary'
        && !/状态：执行失败/.test(toText(结果.runtimeEvent, ''));
      if (!成功 || !模式 || ['未命中', 'time_advance'].includes(模式)) return;
      const 登记前数量 = Object.keys(动作模式表).length;
      登记请求(结果.request, 模式);
      if (Object.keys(动作模式表).length === 登记前数量) 登记角色(snapshot?.activeName, 模式);
    };
    遍历结果(路由结果);
    if (!Object.keys(动作模式表).length) return 动作模式表;
    if (当前剧情模块路由事务上下文) {
      当前剧情模块路由事务上下文.角色动作模式表 = {
        ...(当前剧情模块路由事务上下文.角色动作模式表 || {}),
        ...动作模式表,
      };
    }
    const 记录 = 查找剧情模块预结算记录_桥接(options);
    if (记录) 记录.角色动作模式表 = { ...(记录.角色动作模式表 || {}), ...动作模式表 };
    return 动作模式表;
  }

  function installDirectModuleIntentGuard() {
    window.__LWCS_APPLY_BATTLE_ADJUDICATION__ = async (textOrPayload, options = {}) => {
      const 上一上下文 = 当前剧情模块路由事务上下文;
      if (toText(options && options.source, '') === 'story_generation_guard') {
        当前剧情模块路由事务上下文 = {
          ...(options && typeof options === 'object' ? options : {}),
          source: 'story_generation_guard',
        };
      }
      try {
        return await applyBattleAdjudicationFromText(textOrPayload, options);
      } finally {
        当前剧情模块路由事务上下文 = 上一上下文;
      }
    };
    window.__LWCS_BUILD_ROUTINE_SETTLEMENT_PATCHES__ = detail => {
      const 输入 = detail && typeof detail === 'object' ? detail : {};
      return 构建日常动作字段级写回补丁(
        输入.charKey || 输入.角色名 || 输入.actorName,
        输入.settledRoot || 输入.已结算根数据 || {},
        { systemText: 输入.systemText || 输入.系统播报 },
      );
    };
    window.__MVU_ROUTE_MODULE_INTENT__ = async (input, options = {}) => {
      const 上一上下文 = 当前剧情模块路由事务上下文;
      if (toText(options && options.source, '') === 'story_generation_guard') {
        当前剧情模块路由事务上下文 = {
          ...(options && typeof options === 'object' ? options : {}),
          source: 'story_generation_guard',
          角色动作模式表: {
            ...(options?.角色动作模式表 && typeof options.角色动作模式表 === 'object' ? options.角色动作模式表 : {}),
          },
        };
      }
      try {
        const 结果 = await routeModuleIntentPayload(input, options);
        登记模块结果动作角色_桥接(结果, options);
        return 结果;
      } finally {
        当前剧情模块路由事务上下文 = 上一上下文;
      }
    };
    window.__LWCS_GET_STORY_MODULE_STAGING_STAT__ = (options = {}) => 读取剧情模块预结算StatData_桥接(options);
    if (!window.__MVU_MODULE_INTENT_ROUTER_EVENT_BOUND__) {
      window.addEventListener('mvu-module-intent', event => {
        const detail = event && event.detail && typeof event.detail === 'object' ? event.detail : {};
        detail.result = routeModuleIntentPayload(
          detail.payload || detail.text || detail.plan || detail,
          detail.options || {},
        );
      });
      window.addEventListener('mvu-module-plan-ready', event => {
        const detail = event && event.detail && typeof event.detail === 'object' ? event.detail : {};
        detail.result = routeModuleIntentPayload(
          detail.payload || detail.text || detail.plan || detail,
          detail.options || {},
        );
      });
      window.__MVU_MODULE_INTENT_ROUTER_EVENT_BOUND__ = true;
    }
  }





  function 解析官方工坊委托副职业(地点名 = '') {
    const 文本 = toText(地点名, '');
    if (/锻造/.test(文本)) return '锻造师';
    if (/制造/.test(文本)) return '制造师';
    if (/设计/.test(文本)) return '设计师';
    if (/修理|维修/.test(文本)) return '修理师';
    return '';
  }

  function 获取地图工坊委托模式(副职业名 = '') {
    const 文本 = toText(副职业名, '');
    if (/锻造/.test(文本)) return 'forge';
    if (/制造/.test(文本)) return 'manufacture';
    if (/设计/.test(文本)) return 'design';
    if (/修理|维修/.test(文本)) return 'repair';
    return '';
  }

  function 构建地图工坊面板上下文(snapshot, detail = {}) {
    const currentLoc = toText(detail.currentLoc, 读取快照当前位置(snapshot || {}));
    const targetLoc = toText(detail.target, currentLoc);
    const executorType =
      toText(detail.executorType, '').trim() || (toText(detail.npcTarget, '') ? 'private' : 'official');
    const 副职业名 = executorType === 'official' ? 解析官方工坊委托副职业(targetLoc || currentLoc) : '';
    const 模式 = 获取地图工坊委托模式(副职业名 || toText(detail.profession, ''));
    const 请求 = {
      模式,
      副职业: 副职业名,
      状态: 'ready',
    };
    if (toText(detail.npcTarget, '')) 请求.执行者 = toText(detail.npcTarget, '');
    return {
      ...detail,
      action: 'commission',
      executorType,
      currentLoc,
      target: targetLoc,
      professionRequest: 请求,
    };
  }



  async function handleMapActionDispatch(event) {
    const detail = event && event.detail ? event.detail : {};
    const action = toText(detail.action, '');
    const services = normalizeMapDispatchServices(detail);
    if (!action && !services.length) return;
    if (!isSnapshotPlayerControlled(liveSnapshot)) {
      console.warn('[DragonUI] 旁观视角不可操作。', detail);
      return;
    }

    const 归一化动作 = (() => {
      if (action === 'commission' || action === 'craft') return 'commission';
      if (action === 'ascension' || action === 'tower') return action;
      if (['talk', 'brief', 'intel'].includes(action)) return action;
      if (action === 'battle' || services.includes('battle')) return 'battle';
      if (
        ['trade', 'bid', 'shop', 'auction', 'black_market'].includes(action) ||
        services.some(service => ['shop', 'auction', 'black_market'].includes(service))
      )
        return 'trade';
      return '';
    })();
    if (!归一化动作) return;
    mapDispatchContext = { ...detail, action: 归一化动作, services };

    if (归一化动作 === 'commission') {
      mapDispatchContext = 构建地图工坊面板上下文(liveSnapshot || lastRenderableSnapshot || {}, detail);
      打开地图工坊面板();
      return;
    }

    if (归一化动作 === 'ascension' || 归一化动作 === 'tower') {
      const 是魂灵塔入场 = 归一化动作 === 'tower';
      const 入场请求 = {
        试炼类型: 是魂灵塔入场 ? '魂灵塔' : '升灵台',
        ticketName: toText(detail.ticketName || (是魂灵塔入场 ? detail.soulTowerTicket : detail.ascensionTicket), ''),
        entryLocation: toText(detail.currentLoc, 读取快照当前位置(liveSnapshot || lastRenderableSnapshot || {})),
      };
      if (是魂灵塔入场) {
        入场请求.floor = Math.max(
          1,
          Math.floor(
            toNumber(detail.floor, getDefaultSoulTowerChallengeFloor(liveSnapshot || lastRenderableSnapshot || {})),
          ),
        );
      }
      try {
        await 登记试炼入场并推进剧情(liveSnapshot, 入场请求);
        showUiToast(是魂灵塔入场 ? '魂灵塔入场已登记。' : '升灵台入场已登记。', 'info', 2400);
      } catch (error) {
        showUiToast(
          error && error.message ? error.message : 是魂灵塔入场 ? '魂灵塔入场失败。' : '升灵台入场失败。',
          'error',
          4200,
        );
      }
      return;
    }

    if (['talk', 'brief', 'intel'].includes(归一化动作)) {
      const interactInit = buildMapInteractDispatchRequest(liveSnapshot, detail);
      if (interactInit) {
        dispatchUiAiRequest(interactInit.playerInput, interactInit.systemPrompt, {
          requestKind: interactInit.requestKind,
        });
        return;
      }
      const arenaName = toText(
        detail.currentLoc,
        toText(detail.target, toText(liveSnapshot && liveSnapshot.currentLoc, '未知地点')),
      );
      const npcTargets = Array.isArray(detail.npcTargets)
        ? detail.npcTargets.map(item => toText(item, '')).filter(Boolean)
        : [];
      const targetLabel = npcTargets.length ? `在场人物（${npcTargets.join('、')}）` : '在场人员';
      const playerInputMap = {
        talk: `我想在【${arenaName}】与${targetLabel}交谈。`,
        brief: `我想在【${arenaName}】向${targetLabel}汇报情况并请示安排。`,
        intel: `我想在【${arenaName}】向${targetLabel}请教情报。`,
      };
      const actionLabel = 归一化动作 === 'brief' ? '汇报' : 归一化动作 === 'intel' ? '请教' : '对话';
      const systemPrompt = `以下内容属于前端已经发起的地图${actionLabel}请求。当前没有锁定唯一 NPC 目标，不要报错，也不要要求玩家重新点击；请结合【${arenaName}】的场景功能与在场人物，自然选择最合适的回应对象承接本次互动。${npcTargets.length ? ` 当前可候选人物：${npcTargets.join('、')}。` : ' 当前未识别到明确人物名单，请按地点与事件功能自然承接。'}`;
      dispatchUiAiRequest(playerInputMap[归一化动作] || `我想在【${arenaName}】与在场人物互动。`, systemPrompt, {
        requestKind: 'map_interaction',
      });
      return;
    }

    if (归一化动作 === 'battle') {
      const arenaName = toText(
        detail.currentLoc,
        toText(detail.target, toText(liveSnapshot && liveSnapshot.currentLoc, '未知地点')),
      );
      const 战斗提交模式 = 读取战斗提交模式();
      if (战斗提交模式 === 'free_narrative') {
        dispatchUiAiRequest(
          `我想在【${arenaName}】继续当前冲突。`,
          `当前战斗提交模式为剧情自由。不要开启战斗模块，不要输出 <moduleIntent>，请直接按普通正文承接【${arenaName}】的冲突与角色行动。`,
          { requestKind: 'map_interaction' },
        );
        return;
      }
      if (战斗提交模式 === 'auto') {
        const autoResult = await 自动执行战斗模块路由(liveSnapshot || lastRenderableSnapshot || {}, detail);
        if (autoResult?.ok) return;
        showUiToast(`自动战斗失败：${autoResult?.reason || 'battle_auto_failed'}`, 'error', 4200);
        return;
      }
      let battleOpenResult = null;
      let battleSnapshot = liveSnapshot || lastRenderableSnapshot || {};
      try {
        battleOpenResult = await openMapBattleModule(battleSnapshot, detail);
        if (battleOpenResult?.reason === 'combat_context_unresolved') {
          await refreshLiveSnapshot({ force: true });
          battleSnapshot = liveSnapshot || lastRenderableSnapshot || battleSnapshot;
          battleOpenResult = await openMapBattleModule(battleSnapshot, detail);
        }
      } catch (error) {
        console.warn('[DragonUI] 战斗模块开启失败。', error);
        battleOpenResult = {
          ok: false,
          reason: error instanceof Error ? error.message : toText(error, 'battle_open_exception'),
        };
      }
      if (battleOpenResult && battleOpenResult.ok) return;
      const battleOpenReason = toText(battleOpenResult && battleOpenResult.reason, 'combat_context_unresolved');
      const battleOpenMessage =
        battleOpenReason === 'combat_context_unresolved'
          ? toText(detail.npcTarget, '').trim()
            ? `无法读取【${toText(detail.npcTarget, '').trim()}】的有效战斗档案。`
            : '请先选择明确的切磋对象。'
          : battleOpenReason;
      showUiToast(
        `战斗模块开启失败：${battleOpenMessage}`,
        'error',
        4200,
      );
      return;
    }

    if (归一化动作 === 'trade') {
      打开地图交易面板();
    }
  }

