  const pref = k => { try { return JSON.parse(localStorage.getItem('lwcs-cockpit-settings') || '{}')[k]; } catch (e) { return undefined; } };
  const hoverMs = () => ({ 快: 60, 标准: 100, 慢: 300 }[pref('hover')] || 100);
