    ATTRIBUTE_DELTA: 'ABS',
    JUDGMENT_DELTA: 'ABS',
    STATE_PRESENCE: 'BOOL',
    STATE_DURATION: 'TURNS',
    STATE_DELTA_PERCENT: 'PERCENT',
    SETTLEMENT_MODIFIER_PERCENT: 'PERCENT',
    SUMMON_COUNT: 'COUNT',
    SUMMON_STRENGTH: 'POWER',
    SUMMON_DURATION: 'TURNS',
