                  selectedRouteKey: String(row?.selectedRouteKey || ''),
                  routeUtilityHEPP: Number(row?.routeUtilityHEPP || 0),
                  balancesBefore: row?.balancesBefore || {},
                  balancesAfter: row?.balancesAfter || {},
