    const basic = { 原型: '伤害结算', 目标: '单体', 威力倍率: 50, 伤害类型: '近身攻击', 攻击段数: 1 };
    const observedKey = actor => JSON.stringify([preview.unitId(actor), actor.行动模式 === '协同攻击' ? 'ASSIST' : 'ACTIVE']);
