            if (['FAILURE', 'NO_EFFECT'].includes(String(event?.resultState || '').trim())) return false;
            const outcome = [
              event?.result,
              event?.resultState,
              event?.primaryOutcome,
              event?.ruleCode,
            ].map(value => String(value || '').trim()).join('|');
            if (/non[_ -]?lethal|非致死/i.test(outcome)) return false;
